(window.GIM_TS=window.GIM_TS||{})["Bava Batra.1"]={"from":24,"a":[["\u0003ואם בא לחתוך\u0004 — \u0003חותך.\u0004 ותוהים: \u0003מאי קאמר\u0004 \u0005[מה\u0006 הוא \u0005אומר]?\u0006 מדוע הוזכר כאן ענין החיתוך? ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך אמר]:\u0006 שעושה את הדברים באופן זה שאם מסיים מלמטה מתחיל מלמעלה מיד, כך \u0003שאם בא לחתוך\u0004 — \u0003חותך,\u0004 שאם לא יתחיל את הספר הבא אחריו בראש העמוד הבא — לא יוכל לחתוך את הספר.","\u0003ורמינהי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 מההלכה ששנינו בברייתא זו על מה ששנינו בברייתא אחרת, בה נאמר שצריך להניח קלף ב\u0003תחלת ספר וסופו\u0004 — \u0003כדי לגול.\u0004 ונברר: \u0003כדי לגול מאי\u0004 \u0005[מה]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003כדי לגול עמוד\u0004 — \u0003קשיא\u0004 \u0005[קשה]\u0006 ממה שאמרו בברייתא הראשונה שבסופו צריך להיות כדי לגול \u0003הקף, אי\u0004 \u0005[אם]\u0006 הכוונה היא \u0003כדי לגול הקף\u0004 — \u0003קשיא\u0004 \u0005[קשה]\u0006 ממה שאמרו שם שצריך שיהיה בתחילתו כדי לגול \u0003עמוד!\u0004","\u0003אמר רב נחמן בר יצחק: לצדדין קתני\u0004 \u0005[שנה],\u0006 שנאמר הדבר באופן כללי סתמי שצריך שישאר קלף כדי לגול, כל דבר בהתאם לדין המיוחד שלו, בתחילתו כדי עמוד ובסופו כדי היקף.","\u0003רב אשי אמר: כי תניא ההיא\u0004 \u0005[כאשר שנויה אותה\u0006 ברייתא\u0005]\u0006 ששני הצדדים שווים לגלילה — הרי זה \u0003בספר תורה. כדתניא\u0004 \u0005[כמו ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003כל הספרים נגללים מתחלתן לסופן\u0004 שכך ראוי לגלול אותם, \u0003וספר תורה\u0004 \u0003נגלל\u0004 משני צדדיו \u0003לאמצעיתו ו\u0004לצורך כך \u0003עושה לו עמוד אילך ואילך,\u0004 משני הצדדים של הספר. \u0003אמר ר' אליעזר בר' צדוק: כך היו כותבי ספרים שבירושלים עושין ספריהם,\u0004 שבשני הצדדים היו עמודים, על מנת שיהא הספר גלול באמצעו.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אין עושין ספר תורה לא\u0004 שיהא \u0003ארכו\u0004 (גובהו) \u0003יותר על הקיפו\u0004 בזמן שהוא גלול, \u0003ולא הקיפו יותר על ארכו,\u0004 אלא אורכו והיקפו צריכים להיות זהים. \u0003שאלו את רבי: שיעור\u0004 אורכו של \u0003ספר תורה בכמה? אמר להן: בגויל\u0004 (עור) — \u0003ששה\u0004 טפחים. שאלוהו: \u0003בקלף בכמה?\u0004 אמר להם: \u0003איני יודע.\u0004","מסופר: \u0003רב הונא כתב שבעין\u0004 \u0005[שבעים]\u0006 \u0003ספרי דאורייתא\u0004 \u0005[ספרי תורה]\u0006 בעצמו, \u0003ולא איתרמי ליה\u0004 \u0005[הזדמן לו]\u0006 \u0003אלא חד\u0004 \u0005[אחד]\u0006 שהיה אורכו בדיוק כהיקפו. \u0003רב אחא בר יעקב כתב\u0004 ספר תורה \u0003חד אמשכיה דעיגלי\u0004 \u0005[אחד על עורות של עגלים]\u0006 \u0003ואיתרמי ליה\u0004 \u0005[והזדמן לו]\u0006 שיהיו אורכו והיקפו שווים. ומכיון שהצליח כך כך \u0003יהבו ביה רבנן עינייהו\u0004 \u0005[נתנו בו חכמים עיניהם]\u0006 בקנאה, \u0003ונח נפשיה\u0004 \u0005[ונחה נפשו,\u0006 נפטר\u0005]\u0006 מחמת זה.","\u0003אמרו ליה רבנן\u0004 \u0005[לו חכמים]\u0006 \u0003לרב המנונא: כתב ר' אמי ארבע מאה ספרי תורה. אמר להו\u0004 \u0005[להם]:\u0006 \u0003דילמא\u0004 \u0005[שמא]\u0006 רק את הפסוק \u0003\"תורה צוה לנו משה\"\u0004 (דברים לג, ד) \u0003כתב,\u0004 ולא ממש ארבע מאות ספרי תורה, שקשה לומר שיספיק אדם לכתוב כל כך הרבה. ובדומה לכך מסופר: \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא לר' זירא: נטע ר' ינאי ארבע מאה כרמי\u0004 \u0005[ארבע מאות כרמים].\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003דילמא\u0004 \u0005[שמא]\u0006 לא כרמים גדולים ממש, אלא כדי שיעור הכרם הקטן ביותר שנזכר בהלכה, שהוא \u0003שתים,\u0004 שתי גפנים, \u0003כנגד שתים, ואחת,\u0004 חמישית, \u0003יוצא זנב\u0004, כלומר, יוצאת ונמשכת מחוץ לריבוע.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על מה ששנינו פה לגבי אורך ספר תורה, ממה ששנינו בברייתא: \u0003ארון\u0004 הברית \u0003שעשה משה, אמתים וחצי ארכו ואמה וחצי רחבו ואמה וחצי קומתו,\u0004 והוא נמדד \u0003באמה בת ששה טפחים;\u0004 ולפי זה אורכו חמישה עשר טפחים, רוחבו תשעה טפחים, וקומתו תשעה טפחים.","\u0003והלוחות, ארכן ששה\u0004 טפחים \u0003ורחבן ששה\u0004 טפחים \u0003ועביין שלשה\u0004 טפחים, והיו הלוחות \u0003מונחות\u0004 לאורך, זו אחר זו, \u0003כנגד ארכו של ארון.\u0004 אם כן, \u0003כמה לוחות אוכלות\u0004 (תופסות) \u0003בארון?\u0004 — \u0003שנים עשר טפחים,\u0004 שאורך כל אחד מן הלוחות היה ששה טפחים. \u0003נשתיירו שם שלשה טפחים\u0004 פנויים באורכו, שהוא סך הכל חמישה עשר טפחים, \u0003צא מהן\u0004 (הוצא מן החשבון) עוד \u0003טפח\u0004 אחד, \u0003חציו לכותל זה וחציו לכותל זה\u0004 שהוא עובי עץ הארון עצמו — \u0003נשתיירו שם שני טפחים שבהן ספר תורה\u0004 שכתב משה \u0003מונח.\u0004 ומנין שהיה מונח שם ספר תורה?","\u0003שנאמר: \"אין בארון רק שני לחות האבנים אשר הנח שם משה\"\u0004 (מלכים א ח, ט); \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"אין בארון רק\"?\u0004 הרי זה \u0003מיעוט אחר מיעוט\u0004 (\"אין\", \"רק\"), \u0003ו\u0004לפי כללי מדרש ההלכה \u0003אין מיעוט אחר מיעוט\u0004 בא \u0003אלא\u0004 כדי \u0003לרבות\u0004 דבר אחר, ומה הוא מרבה? \u0003ספר תורה שמונח בארון.\u0004","ואומרים: בהסבריך עד כאן \u0003פירנסת\u0004 (מילאת) את כל חלל ה\u0003ארון לארכו,\u0004 \u0003צא ופרנס ארון לרחבו: כמה לוחות אוכלות בארון\u0004 שרוחבו תשעה טפחים? — \u0003ששה טפחים, נשתיירו שם שלשה טפחים, צא מהן טפח,\u0004 ש\u0003חציו לכותל זה וחציו לכותל זה\u0004 לעובי עץ הארון עצמו — \u0003נשתיירו שם שני טפחים,\u0004 ולמה עשו אותם? — כדי \u0003שלא יהא ספר תורה נכנס ויוצא כשהוא דחוק,\u0004 אלו \u0003דברי ר' מאיר.\u0004","\u0003ר' יהודה אומר\u0004 בשיטה אחרת: כל המידות הללו היו \u0003באמה בת חמשה טפחים;\u0004 ולפיכך אורך הארון שנים עשר וחצי טפחים, ורוחבו שבעה וחצי, וקומתו שבעה וחצי. \u0003והלוחות, ארכן ששה ורחבן ששה ועביין שלשה,\u0004 והן \u0003מונחות באורכו של ארון; כמה לוחות אוכלות בארון\u0004 לאורכו? — \u0003שנים עשר טפחים,\u0004 נמצא ש\u0003נשתייר שם חצי טפח,\u0004 שהוא שלוש אצבעות \u0003אצבע ל\u0004עובי \u0003כותל זה ואצבע ל\u0004עובי \u0003כותל זה.\u0004","\u0003פירנסת ארון לארכו, צא ופרנס ארון לרחבו\u0004 שהיה שבעה טפחים ומחצה: \u0003כמה לוחות אוגדות\u0004 (משתמשות) \u0003בארון?\u0004 — \u0003ששה טפחים, נשתייר שם טפח ומחצה. צא מהן חצי טפח, אצבע ומחצה לכותל זה ואצבע ומחצה לכותל זה\u0004 — \u0003נשתייר שם טפח שבו עמודין\u0004 של כסף \u0003עומדין\u0004 (מונחים), \u0003שנאמר: \"אפריון עשה לו המלך שלמה מעצי הלבנון. עמודיו עשה כסף רפידתו זהב מרכבו ארגמן\"\u0004 (שיר השירים ג, ט–י) שפירשוהו כרמז לארון הברית (\"אפריון\") שעשה ה' (\"מלך שהשלום שלו\").","\u0003וארגז ששיגרו בו פלשתים דורון\u0004 (מתנה) \u0003לאלהי ישראל מונח מצדו\u0004 של הארון, \u0003שנאמר: \"ואת כלי הזהב אשר השבתם לו אשם תשימו בארגז מצדו ושלחתם אותו והלך\"\u0004 (שמואל א ו, ח). \u0003ועליו\u0004 על הארגז הזה היה \u0003ספר תורה מונח, שנאמר: \"לקח את ספר התורה הזה ושמתם אתו מצד ארון ברית ה'\"\u0004 (דברים לא, כו). ונדייק: \u0003מצד\u0004 הארון \u0003הוא מונח ולא בתוכו. ו\u0004מעתה","\u0003מה אני מקיים\u0004 כיצד אני מפרש את מה שנאמר \u0003\"אין בארון רק\"\u0004 (מלכים א ח, ט), שמכאן למדנו, לשיטת ר' מאיר לעיל, שהיה בארון עוד משהו מלבד הלוחות עצמם? — \u0003לרבות\u0004"],["\u0003שברי לוחות\u0004 הראשונים \u0003שמונחים בארון.\u0004 עד כאן לשון הברייתא. וכך יש להקשות ממנה: \u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 לומר כדברי רבי לעיל, ש\u0003ספר תורה הקיפו ששה טפחים, מכדי\u0004 \u0005[הרי]\u0006 \u0003כל\u0004 דבר עגול \u0003שיש בהקיפו שלשה טפחים יש בו רוחב טפח,\u0004 ולפיכך רוחב ספר שהיקפו ששה טפחים הריהו שני טפחים, \u0003וכיון\u0004 שספר התורה \u0003לאמצעיתו נגלל,\u0004 שיש לו שני צדדים גלולים, \u0003נפיש ליה מתרי טפחא\u0004 \u0005[יש יותר משני טפחים]\u0006 בגלל \u0003רווחא דביני ביני\u0004 \u0005[הרווח\u0006 שנמצא \u0005ביניהם]\u0006 בין היריעות, בגלל הגלילה הכפולה, ואם כן \u0003בתרי פושכי היכי יתיב\u0004 \u0005[בשני טפחים\u0006 שנותרו באורך הארון, לשיטת ר' מאיר, \u0005איך יושב,\u0006 מונח, הספר\u0005]?\u0006","\u0003אמר רב אחא בר יעקב: ספר עזרה\u0004 הספר שהיה בארון \u0003לתחלתו הוא נגלל,\u0004 כלומר, על עמוד אחד בלבד, ונמצא שרוחבו שני טפחים בלבד. ומקשים: \u0003ואכתי\u0004 \u0005[ועדיין]\u0006 \u0003תרי בתרי היכי יתיב\u0004 \u0005[שני\u0006 טפחים \u0005בתוך שני\u0006 טפחים בדיוק \u0005איך\u0006 הוא \u0005יושב]?\u0006 הרי אי אפשר להכניס אותו! \u0003אמר רב אשי: דכריך ביה פורתא וכרכיה לעיל\u0004 \u0005[שכורך,\u0006 גולל, \u0005ממנו מעט\u0006 מן הספר, \u0005וכורך אותו למעלה]\u0006 מעל הספר.","עד כאן לענייננו, ומעתה ממשיכים לדון בפרטי הברייתא, ושואלים: \u0003ו\u0004לדעת \u0003ר' יהודה, מקמי דליתי\u0004 \u0005[לפני שהובא]\u0006 ה\u0003ארגז\u0004 הזה שנתנו הפלישתים, \u0003ספר תורה היכי הוה יתיב\u0004 \u0005[איך היה יושב,\u0006 מונח\u0005]?\u0006 ומשיבים: \u0003דפא הוה נפיק מיניה\u0004 \u0005[מדף היה יוצא ממנו]\u0006 מן הארון \u0003ויתיב עילוה\u0004 \u0005[והיה יושב,\u0006 מונח, \u0005עליו]\u0006 \u0003ספר תורה.\u0004 ושואלים: \u0003ור' מאיר,\u0004 שסבור שספר התורה מונח היה בתוך הארון, \u0003האי\u0004 \u0005[זה\u0006 הכתוב\u0005]\u0006 \u0003\"\u0004ושמתם אותו \u0003מצד ארון\"\u0004 (דברים לא, כו) \u0003מאי עביד ליה\u0004 \u0005[מה עושה\u0006 הוא \u0005בו]?\u0006 ומשיבים: \u0003ההוא מיבעי ליה\u0004 \u0005[אותו\u0006 כתוב \u0005נצרך לו]\u0006 ללמד \u0003דמתנח ליה\u0004 \u0005[שמניח אותו]\u0006 \u0003מצד\u0004 הלוחות \u0003ולא מתנח ביני לוחי\u0004 \u0005[ואינו מניח\u0006 אותו \u0005בין\u0006 שני \u0005הלוחות],\u0006 \u0003ולעולם\u0004 הכוונה \u0003בגויה\u0004 \u0005[בתוכו\u0006 של הארון\u0005],\u0006 אבל \u0003מן הצד\u0004 של הלוחות.","ושואלים: \u0003ו\u0004לדעת \u0003ר' מאיר, עמודין היכא הוו קיימי\u0004 \u0005[איפה היו עומדים]?\u0006 ועונים: \u0003מבראי\u0004 \u0005[מבחוץ]\u0006 מחוץ לארון. ועוד שואלים: \u0003ור' מאיר, שברי לוחות\u0004 ש\u0003מונחין בארון מנא ליה\u0004 \u0005[מנין לו]?\u0006 שהרי מן המילים \"אין בארון רק\", מהן למד ר' יהודה דבר זה, למד הוא שספר התורה מונח שם. ומשיבים: \u0003נפקא ליה\u0004 \u0005[יוצא לו\u0006 הדבר\u0005]\u0006 \u0003מ\u0004מה שדרש \u0003רב הונא,\u0004 ש\u0003אמר רב הונא, מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"\u0004ארון האלקים \u0003אשר נקרא שם שם ה' צבאות ישב הכרבים עליו\"\u0004 (שמואל ב' ו, ב)? כפל הלשון \"שם שם ה'\" \u0003מלמד\u0004 \u0003שלוחות ושברי לוחות מונחים בארון.\u0004","ושואלים: \u0003ואידך\u0004 \u0005[והאחר,\u0006 ר' יהודה\u0005]\u0006 מה הוא למד מכך? ומשיבים: \u0003ההוא מבעי ליה\u0004 \u0005[אותו\u0006 כתוב \u0005נצרך לו]\u0006 \u0003ל\u0004כמו שאמר \u0003ר' יוחנן.\u0004 ש\u0003אמר ר' יוחנן אמר ר' שמעון בן יוחאי: מלמד, שהשם וכל כינויו מונחין בארון.\u0004","ושואלים: \u0003ואידך נמי מיבעי ליה להכי\u0004 \u0005[והאחר,\u0006 ר' מאיר, \u0005גם כן צריך אותו לכך]!\u0006 ומשיבים: \u0003אין הכי נמי\u0004 \u0005[אכן כך הוא גם כן]\u0006 שמכאן יש ללמוד דבר זה. ושואלים: \u0003אלא שברי לוחות\u0004 ש\u0003מונחין בארון מנא ליה\u0004 \u0005[מנין לו]?\u0006 ומשיבים: \u0003נפקא ליה\u0004 \u0005[יוצא לו\u0006 הדבר\u0005]\u0006 \u0003מדתני\u0004 \u0005[ממה ששנה]\u0006 \u0003רב יוסף. דתני\u0004 \u0005[ששנה]\u0006 \u0003רב יוסף\u0004 ברייתא זו: נאמר \"בעת ההיא אמר ה' אלי פסל לך שני לוחות אבנים כראשונים... ואכתוב על הלוחות את הדברים אשר היו על הלוחות הראשונים \u0003אשר שברת ושמתם\u0004 בארון\" (דברים י, א –ב) — \u0003מלמד, שהלוחות ושברי לוחות מונחין בארון,\u0004 שגם הלוחות הראשונים היו מונחים בו.","ושואלים: \u0003ואידך\u0004 \u0005[והאחר,\u0006 ר' יהודה\u0005]\u0006 מה הוא למד מפסוק זה? ומשיבים: \u0003ההוא מיבעי ליה\u0004 \u0005[אותו\u0006 פסוק \u0005נצרך לו]\u0006 \u0003ל\u0004כמו שאמר \u0003ריש לקיש,\u0004 ש\u0003אמר ריש לקיש:\u0004 מהו שנאמר: \u0003\"אשר שברת\"\u0004 — \u0003אמר לו הקדוש ברוך הוא למשה: יישר כחך ששברת,\u0004 שגם הקדוש ברוך הוא הסכים שיפה עשה ששיברם.","ואגב הדיון בכתבי הקודש מביאים, \u0003תנו רבנן\u0004 \u0005[שנו חכמים],\u0006 \u0003סדרן של נביאים\u0004 כאשר כורכים אותם יחד, כך הוא: \u0003יהושע ושופטים, שמואל ומלכים, ירמיה ויחזקאל, ישעיה ושנים עשר.\u0004 ושואלים: \u0003מכדי\u0004 \u0005[הרי]\u0006 \u0003הושע קדים\u0004 \u0005[קדם]\u0006 לכל הנביאים שספרי נבואתם נכללים בכתבי הקודש, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"תחלת דבר ה' בהושע\"\u0004 (הושע א, ב), ועל כך תמהו: \u0003וכי עם הושע דבר תחלה,\u0004 ולא דיבר עם נביא אחר לפניו? \u0003והלא ממשה ועד הושע\u0004 \u0003כמה נביאים היו! ואמר ר' יוחנן\u0004 כתשובה לכך: \u0003שהיה תחלה לארבעה נביאים\u0004 \u0003שנתנבאו באותו הפרק\u0004 (זמן) בערך, \u0003ואלו הן: הושע וישעיה, עמוס ומיכה.\u0004 ואם כן, כיון שהיה ראשון \u0003ליקדמיה להושע ברישא\u0004 \u0005[שיקדים את הושע בתחילת]\u0006 ספרי הנביאים!","ומשיבים: \u0003כיון דכתיב נבואתיה\u0004 \u0005[שכתובה נבואתו]\u0006 \u0003גבי\u0004 \u0005[אצל\u0006 בסמוך\u0005]\u0006 ל\u0003חגי זכריה ומלאכי\u0004 בספר אחד של תרי עשר, \u0003וחגי זכריה ומלאכי סוף נביאים הוו\u0004 \u0005[היו],\u0006 לכך \u0003חשיב ליה בהדייהו\u0004 \u0005[החשיב אותו איתם].\u0006 ושואלים: \u0003וליכתביה לחודיה וליקדמיה\u0004 \u0005[ושיכתוב\u0006 את ספר הושע \u0005לבדו ויקדים אותו]!\u0006 ומשיבים: \u0003איידי דזוטר מירכס\u0004 \u0005[מתוך ש\u0006הוא \u0005קטן,\u0006 היה","\u0005אובד].\u0006 ועוד שואלים: \u0003מכדי\u0004 \u0005[הרי]\u0006 \u0003ישעיה קדים\u0004 \u0005[קודם]\u0006 \u0003מירמיה ויחזקאל, ליקדמיה\u0004 \u0005[שיקדים]\u0006 את \u0003ישעיה ברישא\u0004 \u0005[בתחילה]!\u0006 ומשיבים: \u0003כיון\u0004 שספר \u0003מלכים סופיה חורבנא\u0004 \u0005[סופו\u0006 מדבר \u0005בחורבן]\u0006 \u0003וירמיה כוליה חורבנא\u0004 \u0005[כולו\u0006 עוסק בנבואות \u0005החורבן],\u0006 \u0003ויחזקאל רישיה חורבנא וסיפיה נחמתא\u0004 \u0005[תחילתו\u0006 בענין \u0005חורבן\u0006 הבית \u0005וסופו נחמה],\u0006 בבנין הבית הבא, \u0003וישעיה כוליה נחמתא\u0004 \u0005[כולו נחמה]\u0006 שרוב נבואותיו הן על הגאולה, \u0003סמכינן\u0004 \u0005[סומכין אנו,\u0006 מקרבים\u0005]\u0006 \u0003חורבנא לחורבנא ונחמתא לנחמתא\u0004 \u0005[חורבן לחורבן ונחמה לנחמה],\u0006 והסדר הוא: ירמיה, יחזקאל, ישעיה.","וממשיכה הברייתא, \u0003סידרן של כתובים: רות וספר תהלים, ואיוב ומשלי, קהלת, שיר השירים וקינות\u0004 (איכה), \u0003דניאל ומגילת אסתר, עזרא ודברי הימים.\u0004 ושואלים: \u0003ולמאן דאמר\u0004 \u0005[ולדעת מי שאומר]:\u0006 \u0003איוב בימי משה היה, ליקדמיה\u0004 \u0005[שיקדים]\u0006 את \u0003איוב ברישא\u0004 \u0005[בתחילה]!\u0006 ומשיבים: \u0003אתחולי בפורענותא לא מתחלינן\u0004 \u0005[להתחיל בפורענות אין אנו מתחילין],\u0006 ולכן אין מתחילים את הכתובים בספר המדבר על פורענות. ושואלים: \u0003רות\u0004 שפתחו בה, \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003פורענות היא,\u0004 שהרי מדובר בה על דברים רעים שאירעו למשפחת אלימלך! ומשיבים: זו היא \u0003פורענות דאית ליה\u0004 \u0005[שיש לה]\u0006 \u0003אחרית\u0004 של תקוה וגאולה. ש\u0003אמר ר' יוחנן: למה נקרא שמה רות?\u0004 משום \u0003שיצא ממנה דוד שריוהו להקדוש ברוך הוא בשירות ותושבחות.\u0004","ועוד נאמר בברייתא: \u0003ומי כתבן,\u0004 מי כתב את כל ספרי המקרא? ומפרטים: \u0003משה כתב\u0004 את \u0003ספרו\u0004 ספר התורה, \u0003ופרשת בלעם\u0004 נבואת בלעם שבתורה, \u0003ו\u0004את ספר \u0003איוב. יהושע כתב\u0004 את \u0003ספרו ושמונה פסוקים\u0004 אחרונים \u0003שבתורה\u0004 שמדובר בהם על מות משה. \u0003שמואל כתב\u0004 את \u0003ספרו ו\u0004ספר \u0003שופטים ו\u0004ספר \u0003רות. דוד כתב\u0004 את \u0003ספר תהלים על ידי עשרה זקנים,\u0004 כלומר, שאסף גם דברים של עשרה זקנים חכמים מדורות שונים: \u0003על ידי אדם הראשון, על ידי מלכי צדק\u0004 מלך שלם, \u0003ועל ידי אברהם, ועל ידי משה, ועל ידי הימן, ועל ידי ידותון, ועל ידי אסף,\u0004"],["\u0003ועל ידי שלשה בני קרח.\u0004","\u0003ירמיה כתב\u0004 את \u0003ספרו וספר מלכים וקינות\u0004 (איכה). \u0003חזקיה וסיעתו כתבו (\u0004ראשי תיבות \u0003ימש\"ק סימן\u0004 לדבר: יר השירים ו הלת. אנשי כנסת הגדולה כתבו (קנד\"ג סימן): יחזקאל, ושנים עשר, דניאל, ומגילת אסתר. עזרא כתב את \u0003ספרו ויחס\u0004 (ספרי היחוס) \u0003של דברי הימים עד לו\u0004 (לזמנו).","ומעירים: \u0003מסייעא ליה\u0004 \u0005[מסייע לו]\u0006 הדבר \u0003לרב,\u0004 ש\u0003אמר רב יהודה אמר רב: לא עלה עזרא מבבל עד שיחס עצמו ו\u0004אחרי שקבע את שלשלת היוחסין שלו \u0003עלה,\u0004 ויחוס זה הוא זה שכתוב בספר דברי הימים. \u0003ומאן אסקיה\u0004 \u0005[ומי גמר אותו]\u0006 את ספר דברי הימים לדורות שלאחר עזרא? — \u0003נחמיה בן חכליה.\u0004 ומעתה דנים בפרטי הדברים בברייתא זו.","\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003יהושע כתב\u0004 את \u0003ספרו ושמונה פסוקים\u0004 אחרונים \u0003שבתורה.\u0004 ומעירים לפי זה: \u0003תניא כמאן דאמר\u0004 \u0005[שנויה\u0006 הברייתא \u0005כ\u0006דעת \u0005מי שאומר]:\u0006 \u0003שמונה פסוקים\u0004 אחרונים \u0003שבתורה יהושע כתבן.\u0004 שדבר זה שנוי במחלוקת תנאים, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 על מה שנאמר \u0003\"וימת שם משה עבד ה'\"\u0004 (דברים לד, ה) — \u0003אפשר משה מת\u0004 כבר, \u0003וכתב\u0004 הוא עצמו \u0003\"וימת שם משה\"?! אלא, עד כאן כתב משה, מכאן ואילך כתב יהושע,\u0004 אלו \u0003דברי ר' יהודה. ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 כי אלו דברי \u0003ר' נחמיה.\u0004","\u0003אמר לו ר' שמעון: אפשר ספר תורה חסר אות אחת? וכתיב\u0004 \u0005[ונאמר\u0006 בו\u0005]\u0006 קודם לכן: \u0003\"לקח את ספר התורה הזה\"\u0004 (דברים לא, כו), ומשמע שהוא ספר שלם, שאין מוסיפים עליו! \u0003אלא, עד כאן הקדוש ברוך הוא אומר ומשה אומר\u0004 וחוזר אחריו \u0003וכותב. מכאן ואילך\u0004 לגבי מות משה \u0003הקדוש ברוך הוא אומר ומשה כותב בדמע, כמו שנאמר להלן\u0004 בענין כזה של הקראה: \u0003\"ויאמר להם ברוך מפיו יקרא אלי את כל הדברים האלה ואני כתב על הספר בדיו\"\u0004 (ירמיהו לו, יח).","ושואלים: \u0003כמאן אזלא\u0004 \u0005[כ\u0006דעת \u0005מי הולכת]\u0006 \u0003הא\u0004 \u0005[זו]\u0006 ש\u0003אמר ר' יהושע בר אבא אמר רב גידל אמר רב: שמונה פסוקים\u0004 אחרונים \u0003שבתורה יחיד קורא אותן\u0004 ואין מפסיקים בהם לשנים? \u0003לימא\u0004 \u0005[\u0006האם \u0005לומר]\u0006 כי דעת \u0003ר' יהודה היא ו\u0004ש\u0003לא כ\u0004דעת \u0003ר' שמעון?\u0004 שהרי לדעת ר' שמעון הם חלק גמור מן התורה! ומשיבים: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שהוא כשיטת \u0003ר' שמעון, הואיל ואשתנו\u0004 \u0005[והשתנו]\u0006 — \u0003אשתנו\u0004 \u0005[השתנו],\u0006 שכיון שלא נכתבו בדיוק כשאר מקראות שבתורה יש להם דין לעצמם.","שנינו שם: \u0003יהושע כתב\u0004 את \u0003ספרו.\u0004 ומקשים: \u0003והכתיב\u0004 \u0005[והרי נאמר]\u0006 בספר יהושע: \u0003\"וימת יהושע בן נון עבד ה'\"\u0004 (יהושע כד, כט)! ומשיבים: \u0003דאסקיה\u0004 \u0005[שסיים אותו]\u0006 \u0003אלעזר\u0004 בן אהרן הכהן. ומקשים: \u0003והכתיב\u0004 \u0005[והרי נאמר]\u0006 בסוף ספר יהושע: \u0003\"ואלעזר בן אהרן מת\"\u0004 (יהושע כד, לג)! ומשיבים: \u0003דאסקיה\u0004 \u0005[שסיים אותו]\u0006 \u0003פנחס.\u0004","שנינו שם: \u0003שמואל כתב\u0004 את \u0003ספרו.\u0004 ומקשים: \u0003והכתיב\u0004 \u0005[והרי נאמר]\u0006 בספר שמואל: \u0003\"ושמואל מת\"\u0004 (שמואל א כח, ג)! ומשיבים: \u0003דאסקיה\u0004 \u0005[שגמר אותו]\u0006 \u0003גד החוזה ונתן הנביא.\u0004","שנינו שם ש\u0003דוד כתב\u0004 את \u0003ספר תהלים על ידי עשרה זקנים\u0004 ומונים אותם. ושואלים: \u0003וליחשוב נמי\u0004 \u0005[ושימנה גם כן]\u0006 את \u0003איתן האזרחי\u0004 שיש מזמור על שמו (תהילים פ״ט:א׳)! \u0003אמר רב: איתן האזרחי זה הוא אברהם,\u0004 וראיה לדבר, \u0003כתיב הכא\u0004 \u0005[נאמר כאן]:\u0006 \u0003\"איתן האזרחי\"\u0004 (תהילים פט א), \u0003וכתיב התם\u0004 \u0005[ונאמר שם]:\u0006 \u0003\"מי העיר ממזרח צדק\"\u0004 (ישעיה מא, ב), שמפרשים כל ענין זה באברהם, ועל שם שבא מן המזרח נקרא \"איתן האזרחי\".","ומתקשים: \u0003קא חשיב\u0004 \u0005[\u0006הרי \u0005הוא מונה\u0006 שם\u0005]\u0006 את \u0003משה וקא חשיב\u0004 \u0005[ומונה]\u0006 גם את \u0003הימן, והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב: הימן\u0004 הנזכר במקרא (מלכים א' ה, יא) \u0003זה משה,\u0004 וראיה לדבר — \u0003כתיב הכא\u0004 \u0005[נאמר כאן]:\u0006 \u0003\"הימן\",\u0004 שמשמעו בארמית נאמן, \u0003וכתיב התם\u0004 \u0005[ונאמר שם]\u0006 בדברי ה' על משה: \u0003\"בכל ביתי נאמן הוא\"\u0004 (במדבר יב, ז)! ומשיבים: \u0003תרי\u0004 \u0005[שני]\u0006 \u0003הימן הוו\u0004 \u0005[היו],\u0006 האחד הוא כינויו של משה, והשני הוא אדם אחר (משורר במקדש מצאצאי שמואל).","עוד שנינו בברייתא: \u0003משה כתב\u0004 את \u0003ספרו ופרשת בלעם ואיוב.\u0004 ומעירים: \u0003מסייעא ליה\u0004 \u0005[מסייע הדבר]\u0006 \u0003לר' לוי בר לחמא,\u0004 ש\u0003אמר ר' לוי בר לחמא: איוב בימי משה היה, כתיב הכא\u0004 \u0005[נאמר כאן]:\u0006 \u0003\"מי יתן אפוא ויכתבון מלי\"\u0004 (איוב יט, כג), \u0003וכתיב התם\u0004 \u0005[ונאמר שם]\u0006 בדברי משה לה': \u0003\"ובמה יודע אפוא\"\u0004 (שמות לג, טז), והשימוש במלה המיוחדת \"אפוא\" מורה שהיה באותו זמן.","ואומרים: אם מכאן ראיה \u0003ואימא\u0004 \u0005[ואמור]:\u0006 ש\u0003בימי יצחק\u0004 היה, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"מי אפוא הוא הצד ציד\"\u0004 (בראשית כז, לג)! \u0003ואימא\u0004 \u0005[ואמור]:\u0006 \u0003בימי יעקב, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"אם כן אפוא זאת עשו\"\u0004 (בראשית מג, יא)! \u0003ואימא\u0004 \u0005[ואמור]:\u0006 \u0003בימי יוסף, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"איפה הם רעים\"\u0004 (בראשית לז, טז)!","ומשיבים: \u0003לא סלקא דעתך\u0004 \u0005[יכול לעלות על דעתך]\u0006 לומר כן, \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"מי יתן בספר ויחקו\"\u0004 (איוב יט, כג), \u0003ומשה הוא דאיקרי\u0004 \u0005[שנקרא]\u0006 \u0003\"מחקק\", דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וירא ראשית לו כי שם חלקת מחקק ספון\"\u0004 (דברים לג, כא).","\u0003רבא אמר: איוב בימי מרגלים היה, כתיב הכא\u0004 \u0005[נאמר כאן]:\u0006 \u0003\"איש היה בארץ עוץ איוב שמו\"\u0004 (איוב א, א), \u0003וכתיב התם\u0004 \u0005[ונאמר שם]\u0006 בשליחת המרגלים ששלחם משה לארץ לבדוק: \u0003\"היש בה עץ\u0004 אם אין\u0003\"\u0004 (במדבר יג, כ). ושואלים: \u0003מי דמי\u0004 \u0005[האם דומה\u0006 הדבר\u0005]?\u0006 \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003\"עוץ\", התם\u0004 \u0005[שם]\u0006 \u0003\"עץ\"!\u0004 ומשיבים: \u0003הכי קאמר להו\u0004 \u0005[כך אמר להם]\u0006 \u0003משה לישראל\u0004 (למרגלים): האם \u0003ישנו,\u0004 האם חי עוד \u0003אותו אדם ששנותיו ארוכות כעץ ומגין על דורו כעץ?\u0004 ולכן קרא לו \"עץ\" ולא \"עוץ\".","מסופר: \u0003יתיב ההוא מרבנן קמיה\u0004 \u0005[יושב\u0006 היה \u0005אחד החכמים לפני]\u0006 \u0003ר' שמואל בר נחמני, ויתיב וקאמר\u0004 \u0005[ויושב\u0006 היה \u0005ואומר]:\u0006 \u0003איוב לא היה ולא נברא,\u0004 שלא חי כלל אדם כזה, \u0003אלא משל היה. אמר ליה\u0004 \u0005[לו]:\u0006 \u0003עליך,\u0004 כלומר, כדי להוציא ולבטל סברה זו \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"איש היה בארץ עוץ איוב שמו\"\u0004 (איוב א, א), לומר שהיה איש כזה.","ומקשים: \u0003אלא מעתה\u0004 שאתה מוכיח ממה שנאמר \"היה\" שכך ממש היה, מה שנאמר בדברי נתן הנביא לדוד \u0003\"\u0004שני אנשים היו בעיר אחת אחד עשיר ואחד רש. לעשיר היה צאן ובקר הרבה מאד. \u0003ולרש אין כל כי אם כבשה אחת קטנה אשר קנה ויחיה\"\u0004 (שמואל ב' יב, א–ג), \u0003מי הוה\u0004 \u0005[האם היה]\u0006 איש כזה? \u0003אלא משל בעלמא\u0004 \u0005[בלבד],\u0006 \u0003הכא נמי משל בעלמא\u0004 \u0005[כאן גם כן משל בלבד].\u0006 ומשיבים: \u0003אם כן\u0004 שמשל הוא, \u0003שמו ושם עירו למה?\u0004 אלא ודאי היה אדם כזה. ומביאים דעה נוספת בענין זמנו של איוב.","\u0003ר' יוחנן ור' אלעזר דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003איוב מעולי גולה היה,\u0004 שבאו מן הגולה לארץ ישראל בראשית ימי בית שני, \u0003ובית מדרשו בטבריא היה. מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו בברייתא: \u0003ימי שנותיו של איוב\u0004 היו \u0003משעה שנכנסו ישראל למצרים ועד שיצאו,\u0004 משמע שחי בזמנים ההם, ולא כמו שאמרו שחי בראשית ימי בית שני!"],["ומתרצים, \u0003אימא\u0004 \u0005[אמור]:\u0006 \u0003כמשעה שנכנסו ישראל למצרים ועד שעה שיצאו,\u0004 זהו מנין שנותיו, אבל לא שחי באותן השנים.","\u0003מיתיבי\u0004 \u0005[מקשים]:\u0006 \u0003שבעה נביאים נתנבאו לאומות העולם, ואלו הן: בלעם ואביו\u0004 בעור, \u0003ואיוב, אליפז התימני, ובלדד השוחי, וצופר הנעמתי, ואליהוא בן ברכאל הבוזי,\u0004 משמע שאיוב לא מישראל היה! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003וליטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005],\u0006 וכי \u0003אליהוא בן ברכאל לאו\u0004 \u0005[לא]\u0006 \u0003מישראל הוה\u0004 \u0005[היה]?\u0006 \u0003והא כתיב\u0004 \u0005[והרי נאמר\u0006 בו\u0005]\u0006 \u0003\"ממשפחת רם\"\u0004 (איוב לב, ב) כלומר, אברהם!","\u0003אלא\u0004 יש לפרש כי \u0003אינבוי אינבי\u0004 \u0005[התנבא]\u0006 \u0003לאומות העולם,\u0004 ולכן נמנה ברשימה זו. \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 יכול אתה לומר ש\u0003איוב אינבוי אינבי\u0004 \u0005[התנבא]\u0006 \u0003לאומות העולם,\u0004 אבל הוא עצמו מישראל היה. ומקשים: \u0003אטו כולהו נביאי מי\u0004 \u0005[וכי כל הנביאים\u0006 האחרים \u0005האם]\u0006 \u0003לא אינבוי\u0004 \u0005[התנבאו]\u0006 \u0003לאומות העולם?\u0004 ואם כן, מדוע מנו רק שבעה אלה? ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 שאר הנביאים \u0003עיקר נביאותייהו\u0004 \u0005[נבואתם]\u0006 \u0003לישראל\u0004 היתה, \u0003הכא\u0004 \u0005[כאן]\u0006 שבעה אלו, \u0003עיקר נביאותייהו\u0004 \u0005[נבואתם]\u0006 \u0003לאומות העולם.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 ממה ששנינו בברייתא אחרת: \u0003חסיד היה באומות העולם ואיוב שמו, ולא בא לעולם אלא כדי לקבל שכרו, הביא הקדוש ברוך הוא עליו יסורין\u0004 — \u0003התחיל מחרף ומגדף, כפל לו הקדוש ברוך הוא שכרו בעולם הזה כדי לטרדו\u0004 (לסלק אותו) \u0003מן העולם הבא,\u0004 הרי שגוי היה!","ומשיבים: \u0003תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא\u0004 האם היה מישראל. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 בענין זמנו של איוב, \u0003ר' אלעזר אומר: איוב בימי שפוט השופטים היה, שנאמר: \"הן אתם כלכם חזיתם ולמה זה הבל תהבלו\"\u0004 (איוב כז, יב), \u0003איזה דור שכולו הבל? הוי אומר: זה דורו של שפוט השופטים,\u0004 כמבואר להלן שהיו שופטים את שופטיהם.","\u0003ר' יהושע בן קרחה אומר: איוב בימי אחשורוש היה, שנאמר: \"ולא נמצא נשים יפות כבנות איוב בכל הארץ\"\u0004 (איוב מב, טו), \u0003איזהו דור שנתבקשו\u0004 (חפשו) \u0003בו נשים יפות? הוי אומר: זה דורו של אחשורוש\u0004 (ראה אסתר פרק ב). ומקשים: \u0003ואימא\u0004 \u0005[ואמור]\u0006 שהיה \u0003בימי דוד, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויבקשו נערה יפה\u0004 בכל גבול ישראל\u0003\"\u0004 (מלכים א' א, ג)! ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 בימי דוד חיפשו \u0003בכל גבול ישראל,\u0004 וכפי שנאמר שם, \u0003הכא\u0004 \u0005[כאן]\u0006 בימי אחשורוש חיפשו \u0003בכל הארץ,\u0004 וכפי שנאמר בבנות איוב.","\u0003ר' נתן אומר: איוב בימי מלכות שבא היה, שנאמר: \"ותפל שבא ותקחם\"\u0004 (איוב א, טו). \u0003וחכמים אומרים: איוב בימי\u0004 גדולת מלכות \u0003כשדים,\u0004 בזמן נבוכדנצר \u0003היה, שנאמר: \"כשדים שמו שלשה ראשים\"\u0004 (איוב א, יז). \u0003ויש אומרים: איוב בימי יעקב היה, ו\u0004את \u0003דינה בת יעקב נשא,\u0004 ומסבירים: \u0003כתיב הכא\u0004 \u0005[נאמר כאן]:\u0006 \u0003\"כדבר אחת הנבלות תדברי\"\u0004 (איוב ב, י), \u0003וכתיב התם\u0004 \u0005[ונאמר שם]\u0006 במעשה דינה: \u0003\"כי נבלה עשה בישראל\"\u0004 (בראשית לד, ז). עד כאן דברי הברייתא, \u0003ו\u0004בהכרח \u0003כולהו תנאי סבירא להו\u0004 \u0005[כל\u0006 אותם \u0005התנאים סבורים]\u0006 ש\u0003איוב מישראל הוה\u0004 \u0005[היה],\u0006 \u0003לבר\u0004 \u0005[חוץ]\u0006 \u0003מ\"יש אומרים\"\u0004 שאמרו שבימי יעקב היה, והרי בוודאי לא היה מבני יעקב. ומה הראיה שכולם סבורים שהיה מישראל?","\u0003דאי סלקא דעתך\u0004 \u0005[שאם עולה על דעתך\u0006 לומר\u0005]\u0006 ש\u0003מאומות העולם הוה\u0004 \u0005[היה],\u0006 \u0003בתר דשכיב\u0004 \u0005[אחרי שמת]\u0006 \u0003משה מי שריא\u0004 \u0005[האם שרתה]\u0006 \u0003שכינה על אומות העולם? והא\u0004 \u0005[והרי]\u0006 \u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003בקש משה שלא תשרה שכינה על אומות העולם, ונתן לו\u0004 הדבר, \u0003שנאמר: \"ונפלינו אני ועמך\u0004 מכל העם אשר על פני האדמה","\u0003\"\u0004(שמות לג, טז) ונאמר שם שה' נענה לבקשותיו. \u0003אמר ר' יוחנן: דורו של איוב שטוף בזמה היה, שנאמר: \"הן אתם כלכם חזיתם ולמה זה הבל תהבלו\"\u0004 (איוב כז, יב), \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"שובי שובי השולמית שובי שובי ונחזה בך\"\u0004 (שיר השירים ז, א), ומכאן למדים שלשון זו \"חזיתם\" היא לשון הסתכלות של זנות. ומקשים: \u0003אימא\u0004 \u0005[אמור]\u0006 ש\"חזיתם\" זה בהסתכלות \u0003בנבואה\u0004 הוא, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"חזון ישעיהו בן אמוץ\"\u0004 (ישעיה א, א)! ואומרים: \u0003אם כן\u0004 מה שנאמר \u0003\"למה זה הבל תהבלו\" למה לי?\u0004 אלא שמדובר פה על ראיה של הבל.","ועוד בביאור דברי ר' אלעזר בברייתא, שדור שפוט השופטים דור שכולו הבל היה, מביאים, \u0003ואמר ר' יוחנן, מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"ויהי בימי שפוט השופטים\"\u0004 (רות א, א)? כוונתו \u0003דור ששופט את שופטיו, אומר לו\u0004 השופט לנשפט לפניו: \u0003\"טול קיסם מבין עיניך\",\u0004 כלומר, הסר מעליך עוון קטן שיש בידך, \u0003אומר לו\u0004 הנשפט: \u0003\"טול קורה מבין עיניך\",\u0004 שבידך עוונות גדולים הרבה יותר. \u0003אמר לו\u0004 השופט: \u0003\"כספך היה לסיגים\"\u0004 (ישעיה א, כב), זייפת מטבעות, \u0003אמר לו\u0004 הנשפט: \u0003\"סבאך מהול במים\"\u0004 (ישעיה א, כב), אתה בעצמך מוהל את יינך במים ומוכרו. שכיון שכולם לא היו נוהגים כהלכה, לא יכלו השופטים לשפוט.","ועוד בענין שנזכר בברייתא, \u0003אמר ר' שמואל בר נחמני אמר ר' יונתן: כל האומר מלכת שבא\u0004 שבאה לבקר את שלמה המלך (מלכים א' פרק י) \u0003אשה היתה\u0004 — \u0003אינו אלא טועה, מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"מלכת שבא\"? מלכותא דשבא\u0004 \u0005[מלכות שבא]\u0006 כמו שנזכר באיוב \"ותפול שבא ותקחם\".","כיון שהזכרנו את ספר איוב דנים בכמה דברים בתוכו. נאמר שם: \u0003\"ויהי היום ויבאו בני האלהים להתיצב על ה' ויבא גם השטן בתוכם. ויאמר ה' אל השטן מאין תבא ויען השטן\u0004 את ה' ויאמר משוט בארץ ומהתהלך בה\u0003\"\u0004 (איוב א, ו– ז). ומפרשים כך את תשובתו: \u0003אמר לפניו: רבונו של עולם, שטתי בכל העולם כולו ולא מצאתי נאמן כעבדך אברהם, שאמרת לו: \"קום התהלך בארץ לארכה ולרחבה כי לך אתננה\"\u0004 (בראשית יג, יז), \u0003ואפילו הכי\u0004 \u0005[כך]\u0006 \u0003בשעה שלא מצא מקום לקבור את שרה [עד שקנה בארבע מאות שקל כסף] לא הרהר אחר מדותיך,\u0004 שלא התרעם על שלא קיים הקדוש ברוך הוא את הבטחתו.","ועל כך מובאת תשובתו של ה': \u0003\"ויאמר ה' אל השטן השמת לבך אל עבדי איוב כי אין כמהו בארץ\u0004 איש תם וישר ירא אלהים וסר מרע\u0003\"\u0004 (איוב א, ח). ועל כך \u0003אמר ר' יוחנן: גדול הנאמר באיוב יותר ממה שנאמר באברהם,\u0004 ש\u0003אילו באברהם כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"כי עתה ידעתי כי ירא אלהים אתה\"\u0004 (בראשית כב, יב), \u0003ובאיוב כתיב\u0004 \u0005[נאמר]\u0006 יותר: \u0003\"איש תם וישר ירא אלהים וסר מרע\"\u0004 (איוב א, ב).","ואגב מבררים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"וסר מרע\"? אמר ר' אבא בר שמואל: איוב וותרן בממונו היה,\u0004 שלא היה מקפיד על ממונו, כגון \u0003מנהגו של עולם\u0004 — כאשר משלם לחנווני, \u0003נותן חצי פרוטה לחנוני, איוב\u0004 אם קנה אדם ממנו דבר \u0003ויתרה,\u0004 שהיה מוותר על חצי הפרוטה \u0003משלו.\u0004 וממשיכים בפירוש אותה פרשה.","\u0003\"ויען השטן את ה' ויאמר החנם ירא איוב אלהים. הלא אתה סכת בעדו ובעד ביתו\u0004 ובעד כל אשר לו מסביב. מעשה ידיו ברכת ומקנהו פרץ בארץ\u0003\"\u0004 (איוב א, ט-י). \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"מעשה ידיו ברכת\"\u0004 (איוב א, י)? \u0003אמר ר' שמואל בר רב יצחק: כל הנוטל פרוטה מאיוב מתברך.\u0004 שלא רק מה שעשה בעצמו, אלא כל מי שקיבל ממנו היה מבורך.","ועוד מבררים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"ומקנהו פרץ בארץ\"\u0004 (איוב א, י)? \u0003אמר ר' יוסי בר חנינא: מקנהו של איוב פרצו גדרו של עולם, מנהגו של עולם\u0004 — \u0003זאבים הורגים העזים,\u0004 ואילו \u0003מקנהו של איוב\u0004 — \u0003עזים הורגים את הזאבים.\u0004","והמשך דברי השטן: \u0003\"ואולם שלח נא ידך וגע בכל אשר לו אם לא על פניך יברכך. ויאמר ה' אל השטן הנה כל אשר לו בידך רק אליו אל תשלח ידך\u0004 ויצא השטן מעם פני ה'\u0003\"\u0004 (איוב א, יא–יב). \u0003\"ויהי היום ובניו ובנתיו אכלים ושתים יין בבית אחיהם הבכור. ומלאך בא אל איוב ויאמר הבקר היו חורשות\u0004 והאתונות רועות על ידיהם\u0003\"\u0004 (איוב א, יג–יד). ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"הבקר היו חרשות והאתנות רעות על ידיהם\"? אמר ר' יוחנן: מלמד, שהטעימו הקדוש ברוך הוא לאיוב\u0004"],["\u0003מעין העולם הבא\u0004 שהחרישה והקציר באים כאחד, ואף כאן הבקר היו חורשות בזריעה והאתונות רועות ואוכלות מן הדברים הצומחים.","ועוד בפירוש הדברים באיוב: \u0003\"עוד זה מדבר וזה בא ויאמר אש אלהים\u0004 נפלה מן השמים ותבער בצאן ובנערים ותאכלם... \u0003עוד זה מדבר וזה בא ויאמר כשדים שמו שלשה ראשים ויפשטו על הגמלים ויקחום\u0004 ואת הנערים הכו לפי חרב... \u0003עוד זה מדבר וזה בא ויאמר בניך ובנותיך אכלים ושתים יין בבית אחיהם הבכור. והנה רוח גדולה באה מעבר המדבר ויגע בארבע פנות הבית ויפל על הנערים\u0004 וימותו... \u0003ויקם איוב ויקרע את מעלו ויגז את ראשו\u0004 ויפול ארצה וישתחו. \u0003ויאמר ערם יצתי מבטן אמי וערם אשוב שמה ה' נתן וה' לקח יהי שם ה' מבורך. בכל זאת לא חטא איוב ולא נתן תפלה לאלהים\"\u0004 (איוב א, טז–כב)","\u0003\"ויהי היום ויבאו בני האלהים להתיצב\u0004 על ה' ויבוא גם השטן בתוכם להתיצב על ה'. \u0003ויאמר ה' אל השטן אי מזה תבא ויען השטן את ה' ויאמר משט בארץ\u0004 ומהתהלך בה\u0003\"\u0004 (איוב ב א–ב). \u0003אמר לפניו: רבונו של עולם, שטתי בכל העולם ולא מצאתי כעבדך אברהם, שאמרת לו: \"קום התהלך בארץ לארכה ולרחבה כי לך אתננה\"\u0004 (בראשית יג, יז), \u0003ובשעה שבקש לקבור\u0004 את \u0003שרה לא מצא מקום\u0004 כלל \u0003לקוברה, ולא הרהר אחר מדותיך,\u0004 ולא טען כנגד ה' שלא מילא את הבטחתו.","ועל כך נאמר: \u0003\"ויאמר ה' אל השטן השמת לבך אל עבדי איוב כי אין כמהו בארץ\u0004 איש תם וישר ירא אלהים וסר מרע \u0003ועדנו מחזיק בתמתו, ותסיתני בו לבלעו חנם\"\u0004 (איוב ב, ג).","\u0003אמר ר' יוחנן: אלמלא\u0004 (אם לא היה) \u0003מקרא כתוב אי אפשר לאומרו,\u0004 שנאמר \"ותסיתני\", \u0003כאדם שמסיתין אותו וניסת,\u0004 שכאילו הקדוש ברוך הוא לא רצה בכך, אלא הסיתו אותו.","\u0003במתניתא תנא\u0004 \u0005[בברייתא שנה]\u0006 לגבי דרך הנהגתו של השטן: \u0003יורד\u0004 למטה לעולם הזה \u0003ומתעה\u0004 את הבריות ומחטיא אותם, \u0003ו\u0004אחר \u0003עולה\u0004 למרום ומקטרג ומשטין על אותן הבריות שחטאו \u0003ומרגיז\u0004 את הקדוש ברוך הוא, \u0003נוטל רשות ונוטל נשמה\u0004 כעונש.","ומשיבים בענין איוב, נאמר שם \u0003\"ויען השטן את ה' ויאמר עור בעד עור וכל אשר לאיש יתן בעד נפשו. אולם שלח נא ידך וגע אל עצמו ואל בשרו אם לא על פניך יברכך. ויאמר ה' אל השטן הנו בידך אך את נפשו שמר. ויצא השטן מאת פני ה' ויך את איוב\u0004 בשחין רע מכף רגלו עד קדקדו\u0003\"\u0004 (איוב ב, ד–ז). \u0003אמר ר' יצחק: קשה\u0004 היה \u0003צערו של שטן יותר משל איוב,\u0004 ומדוע? — \u0003משל לעבד שאמר לו רבו\u0004 (אדוניו): \u0003שבור חבית ושמור את יינה.\u0004 ואף כאן אמר לשטן שהוא יכול לעשות לאיוב כל מה שירצה, אבל שישמור את נפשו.","\u0003אמר ריש לקיש: הוא שטן הוא יצר הרע הוא מלאך המות,\u0004 שלושתם פנים של אותה מהות. \u0003הוא שטן\u0004 המשטין ומנסה לקטרג על האדם ולהכשילו, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויצא השטן מאת פני ה'\u0004 ויך את איוב בשחין\u0003\"\u0004 (איוב ב, ז). \u0003הוא יצר הרע, כתיב התם\u0004 \u0005[נאמר שם]:\u0006 \u0003\"\u0004יצר מחשבות לבו \u0003רק רע כל היום\"\u0004 (בראשית ו, ה), \u0003וכתיב הכא\u0004 \u0005[ונאמר כאן]:\u0006 \u0003\"רק את נפשו שמר\"\u0004 (איוב ב, ו), \u0003\"רק אליו אל תשלח ידך\"\u0004 (איוב א, יב), ולמדים בגזירה שווה \"רק\" \"רק\". \u0003הוא מלאך המות, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"אך את נפשו שמר\"\u0004 (איוב ב, ו), \u0003אלמא בדידיה קיימא\u0004 \u0005[נמצא\u0006 ש\u0005בו תלוי\u0006 הדבר\u0005],\u0006 משמע שהוא הוא מלאך המוות.","\u0003אמר ר' לוי: שטן\u0004 שקטרג על איוב \u0003ופנינה\u0004 שהציקה לחנה אמו של שמואל הנביא, \u0003לשם שמים נתכוונו. שטן\u0004 — \u0003כיון דחזיא\u0004 \u0005[שראה]\u0006 \u0003להקדוש ברוך הוא דנטיה דעתיה בתר\u0004 \u0005[שנוטה דעתו אחר]\u0006 \u0003איוב\u0004 ומשבח אותו\u0005,\u0006 \u0003אמר: חס ושלום, מינשי ליה לרחמנותיה\u0004 \u0005[ישכח את אהבתו]\u0006 של \u0003אברהם.\u0004 \u0003פנינה\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וכעסתה צרתה גם כעס בעבור הרעימה\"\u0004 (שמואל א' א, ו), כלומר, כדי שתצטער ותתפלל. \u0003דרשה\u0004 \u0005[דרש]\u0006 \u0003רב אחא בר יעקב בפפוניא\u0004 את הדברים הללו, \u0003אתא\u0004 \u0005[בא]\u0006 ה\u0003שטן נשקיה לכרעיה\u0004 \u0005[\u0006ו\u0005נישק את רגליו]\u0006 כתודה על שלימד עליו זכות. ומעתה דנים בדמותו של איוב, ובדבריו.","נאמר: \u0003\"בכל זאת לא חטא איוב בשפתיו\"\u0004 (איוב ב, י). \u0003אמר רבא:\u0004 ידוייק בפסוק, \u0003בשפתיו לא חטא,\u0004 אבל \u0003בלבו חטא.\u0004 והראיה לדבר: \u0003מאי קאמר\u0004 \u0005[מה אמר]?\u0006 \u0003\"ארץ נתנה ביד רשע פני שפטיה יכסה אם לא איפו מי הוא\"\u0004 (איוב ט, כד), \u0003אמר רבא: בקש איוב להפוך קערה על פיה.\u0004 כלומר, שיש בכך רמז של כפירה גדולה, שהרי אמר שהארץ ניתנה ביד רשע, ומתכוון בכך לקדוש ברוך הוא. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: לא דבר איוב\u0004 כאן \u0003אלא כנגד השטן,\u0004 שהוא הרשע שבידו ניתנה הארץ.","ומעירים: דבר זה הוא \u0003כתנאי\u0004 \u0005[כ\u0006דברי \u0005תנאים]\u0006 שנחלקו כבר בענין זה, ששנינו: \u0003\"ארץ נתנה ביד רשע\"\u0004 — \u0003ר' אליעזר אומר: בקש איוב להפוך קערה על פיה; אמר לו ר' יהושע: לא דבר איוב אלא כלפי שטן.\u0004","ועוד בהסבר דברי איוב: \u0003\"על דעתך כי לא ארשע ואין מידך מציל\"\u0004 (איוב י, ז) — \u0003אמר רבא: בקש איוב\u0004 \u0003לפטור את כל העולם כולו מן הדין,\u0004 שטען שכל מה שהאדם עושה אינו עושה אלא מכוחו של הקדוש ברוך הוא, ולכן אין להענישו על מעשיו. \u0003אמר לפניו: רבונו של עולם, בראת\u0004 את ה\u0003שור\u0004 ש\u0003פרסותיו סדוקות\u0004 והוא כשר, \u0003בראת חמור\u0004 ש\u0003פרסותיו קלוטות\u0004 (בלא סדק) ועשית אותו אסור; \u0003בראת גן עדן, בראת גיהנם;\u0004 ובאותו אופן \u0003בראת צדיקים, בראת רשעים, מי מעכב על ידך!\u0004 ואם כן, כיון שבראת אותם מתחילה צדיקים ורשעים, אין אתה יכול לבוא עליהם אחר כך בתרעומת על מעשיהם!","\u0003ומאי אהדרו ליה חבריה\u0004 \u0005[ומה השיבו לו\u0006 על כך \u0005חביריו]\u0006 של \u0003איוב?\u0004 — \u0003\"אף אתה תפר יראה ותגרע שיחה לפני אל\"\u0004 (איוב טו, ד) על ידי דבריך אלה, כי אמנם \u0003ברא הקדוש ברוך הוא יצר הרע,\u0004 אבל \u0003ברא לו תורה\u0004 שהיא \u0003תבלין\u0004 למתק אותו, שלא ישלוט באדם.","\u0003דרש רבא: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 בדברי איוב על עצמו: \u0003\"ברכת אבד עלי תבא ולב אלמנה ארנן\"\u0004 (איוב כט, יג)? \u0003\"ברכת אבד עלי תבא\"\u0004 — \u0003מלמד שהיה\u0004 איוב \u0003גוזל שדה מיתומים,\u0004 עובד בה \u0003ומשביחה ומחזירה להן,\u0004 ונמצא שמברכים אותו על שדה שאבד להם, \u0003\"ולב אלמנה ארנן\"\u0004 — ש\u0003כל היכא דהוה\u0004 \u0005[מקום שהיתה]\u0006 \u0003אלמנה\u0004 ש\u0003לא הוו נסבי לה\u0004 \u0005[היו נושאים אותה\u0006 לאשה\u0005],\u0006 \u0003הוה אזיל שדי שמיה עילווה, והוו אתו נסבי לה\u0004 \u0005[היה הולך\u0006 ו\u0005מטיל\u0006 את \u0005שמו עליה,\u0006 מוציא קול שהיא קרובתו,","\u0005והיו נושאים אותה].\u0006 ועוד אמר איוב: \u0003\"לו שקול ישקל כעשי והותי במאזנים ישאו יחד\"\u0004 (איוב ו, ב) — \u0003אמר רב: עפרא לפומיה\u0004 \u0005[עפר לפיו]\u0006 של \u0003איוב,\u0004 כלומר, אסור היה לו לומר דברים כאלה, ובאופן כזה, כאילו שוקל מה עשה לו ה', וכי יש \u0003חברותא\u0004 \u0005[חברות]\u0006 \u0003כלפי שמיא\u0004 \u0005[שמים]?\u0006 וכיוצא בזה דברים אחרים שאמר איוב: \u0003\"לו יש בינינו מוכיח ישת ידו על שנינו\"\u0004 (איוב ט, לג) — \u0003אמר רב: עפרא לפומיה\u0004 \u0005[עפר לפיו]\u0006 של \u0003איוב\u0004 שאמר כך, \u0003כלום יש עבד שמוכיח את רבו?\u0004 ועוד נאמר: \u0003\"ברית כרתי לעיני ומה אתבונן על בתולה\"\u0004 (איוב לא, א) — \u0003אמר רבא: עפרא לפומיה\u0004 \u0005[עפר לפיו]\u0006 של \u0003איוב, איהו באחרניתא\u0004 \u0005[הוא ב\u0006נשים \u0005אחרות]\u0006 לא הסתכל, \u0003אברהם אפילו בדידיה\u0004 \u0005[בשלו,\u0006 באשתו\u0005]\u0006 \u0003לא איסתכל\u0004 \u0005[הסתכל],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בדברי אברהם לשרה: \u0003\"הנה נא ידעתי כי אשה יפת מראה את\"\u0004 (בראשית יב, יא), \u0003מכלל\u0004 הדברים אתה למד \u0003דמעיקרא\u0004 \u0005[שמתחילה]\u0006 \u0003לא הוה ידע לה\u0004 \u0005[היה יודע בה]\u0006 כמה היא יפה, מפני שלא היה מסתכל בה.","ועוד נאמר בדברי איוב: \u0003\"כלה ענן וילך כן יורד שאול לא יעלה\"\u0004 (איוב ז, ט) — \u0003אמר רבא: מכאן שכפר איוב בתחיית המתים,\u0004 שהרי אמר שהיורד שאול לא יעלה, כדרך שהענן שכלה שוב אינו חוזר. ועוד נאמר \u0003\"אשר בשערה\u0004 \u0003ישופני והרבה פצעי חנם\"\u0004 (איוב ט, יז) — \u0003אמר רבה: איוב בסערה חרף ובסערה השיבוהו.\u0004","\u0003בסערה חרף\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"אשר בשערה ישופני\", אמר לפניו: רבונו של עולם, שמא רוח סערה עברה לפניך ונתחלף לך בין איוב לאויב! בסערה השיבוהו\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויען ה' את איוב מן הסערה ויאמר.\u0004 מי זה מחשיך עצה במילין בלי דעת. \u0003אזר נא כגבר חלציך\u0004 ו\u0003אשאלך והודיעני\"\u0004 (איוב לח, א–ג), ומה פירוש \"מן הסערה\"?","\u0003אמר לו\u0004 הקדוש ברוך הוא: \u0003הרבה נימין\u0004 (שערות) \u0003בראתי באדם, וכל נימא ונימא בראתי לה גומא\u0004 \u0003בפני עצמה\u0004 שהשערה יונקת ממנה, \u0003שלא יהו שתים יונקות מגומא אחת, שאלמלי\u0004 (שאילו) \u0003שתים יונקות מגומא אחת\u0004 — \u0003מחשיכות מאור עיניו של אדם.\u0004 ואם \u0003בין גומא לגומא לא נתחלף לי, בין איוב לאויב נתחלף לי?\u0004","ועוד אמר לו: \u0003\"מי פלג לשטף תעלה\u0004 ודרך לחזיז קולות\" (איוב לח, כה) — \u0003הרבה טיפין בראתי בעבים, וכל טיפה וטיפה בראתי לה דפוס\u0004 (תבנית) \u0003בפני עצמה, כדי שלא יהו שתי טיפין יוצאות מדפוס אחד, שאלמלי שתי טיפין יוצאות מדפוס אחד\u0004 — \u0003מטשטשות\u0004 (ממיסות, מקלקלות) \u0003את הארץ\u0004 והורסות אותה \u0003ואינה מוציאה פירות.\u0004 ואם \u0003בין טיפה לטיפה לא נתחלף לי, בין איוב לאויב נתחלף לי?\u0004 אגב כך שואלים: \u0003מאי\u0004 \u0005[כיצד]\u0006 \u0003משמע דהאי\u0004 \u0005[שזו]\u0006 הלשון \u0003\"תעלה\" לישנא\u0004 \u0005[לשון]\u0006 \u0003דפוס היא?\u0004 \u0003אמר רבה בר שילא, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויעש תעלה כבית סאתים זרע\"\u0004 (מלכים א' יח, לב).","נאמר באותו פסוק שבספר איוב: \u0003\"ודרך לחזיז קלות\"\u0004 ומפרשים שכך אמר הקדוש ברוך הוא: \u0003הרבה קולות בראתי בעבים, וכל קול וקול בראתי לו שביל בפני עצמו, כדי שלא יהו שתי קולות יוצאות משביל אחד, שאלמלי שתי קולות יוצאות משביל אחד\u0004 — \u0003מחריבין את כל העולם.\u0004 ואם \u0003בין קול לקול לא נתחלף לי, בין איוב לאויב נתחלף לי?\u0004","ועוד, נאמר שם: \u0003\"הידעת עת לדת יעלי סלע חלל אילות תשמר\"\u0004 (איוב לט, א) — \u0003יעלה זו אכזרית על בניה\u0004 ואינה חסה עליהם, \u0003בשעה שכורעת\u0004"],["\u0003ללדת, עולה לראש ההר כדי שיפול ממנה\u0004 הולד \u0003וימות, ואני מזמין לה נשר שמקבלו בכנפיו ומניחו לפניה, ואלמלי מקדים\u0004 הנשר \u0003רגע אחד או מתאחר רגע אחד מיד\u0004 היה הוולד \u0003מת.\u0004 ואם \u0003בין רגע לרגע לא נתחלף לי, בין איוב לאויב נתחלף לי?\u0004","וכן \u0003\"חלל אילות תשמר\"\u0004 (איוב לט, א) — \u0003אילה זו\u0004 פתח \u0003רחמה צר\u0004 וקשה לה ללדת, \u0003בשעה שכורעת ללדת, אני מזמין לה דרקון\u0004 (מין נחש) \u0003שמכישה\u0004 (נושכה) \u0003בבית הרחם ו\u0004על ידי כך \u0003מתרפה ממולדה\u0004 ומולידה, \u0003ואלמלי מקדים\u0004 הנחש \u0003רגע אחד או מאחר רגע אחד מיד מתה.\u0004 ואם \u0003בין רגע לרגע לא נתחלף לי, בין איוב לאויב נתחלף לי?\u0004","ומעירים: נאמר מצד אחד: \u0003\"איוב לא בדעת ידבר ודבריו לא בהשכיל\"\u0004 (איוב לד, לה) \u0003ו\u0004מן הצד האחר \u0003כתיב\u0004 \u0005[נאמר]\u0006 לרעיו של איוב: \u0003\"כי לא דברתם אלי נכונה כעבדי איוב\"\u0004 (איוב מב, ח)! \u0003אמר רבא: מכאן שאין אדם נתפס בשעת צערו,\u0004 שאף על פי שהובאו כמה דברים שאמר איוב שלא כדין ושלא כראוי, מכל מקום, כיון שאמרם בשעת צער, אין אדם נתפס להיענש עליהם.","נאמר: \u0003\"וישמעו שלשת רעי איוב את כל הרעה הזאת הבאה עליו ויבאו איש ממקמו אליפז התימני ובלדד השוחי וצופר הנעמתי ויועדו יחדו לבוא לנוד לו ולנחמו\"\u0004 (איוב ב, יא) — \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"ויועדו יחדו\"? אמר רב יהודה אמר רב: מלמד\u0004 הפסוק \u0003שנכנסו כולן בשער אחד\u0004 בבת אחת. \u0003ותנא\u0004 \u0005[ושנה\u0006 החכם בברייתא\u0005]:\u0006 \u0003בין כל אחד ואחד\u0004 מהם \u0003שלש מאות פרסי\u0004 \u0005[פרסות]\u0006 מרחק.","ושואלים: \u0003מנא הוו ידעי\u0004 \u0005[מנין ידעו]\u0006 כאחד שאירע כך לאיוב ובאו ביחד? \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]:\u0006 \u0003כלילא הוה להו\u0004 \u0005[כתר היה להם]\u0006 לכל אחד ואחד, ובו היו רואים סימנים שנפגע אחד מהם. \u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]:\u0006 \u0003אילני הוה להו\u0004 \u0005[אילנות היו להם],\u0006 \u0003וכיון דכמשי הוו ידעי\u0004 \u0005[שכמשו\u0006 האילנות \u0005היו יודעים]\u0006 שבאה צרה לאחד מהם. \u0003אמר רבא: היינו דאמרי אינשי\u0004 \u0005[זהו שאומרים האנשים]:\u0006 \u0003או חברא\u0004 \u0005[חבר]\u0006 \u0003כחברי איוב או מיתותא\u0004 \u0005[מוות],\u0006 כי אם אין לאדם חברים קרובים, מוטב לו למות. ומביאים ענין נוסף בו נזכר איוב.","\u0003\"ויהי כי החל האדם לרב על פני האדמה ובנות ילדו להם\"\u0004 (בראשית ו, א) — \u0003ר' יוחנן אמר:\u0004 \"לרוב\" משמעו \u0003רביה באה לעולם\u0004 על ידי הבנות. \u0003ריש לקיש אמר: מריבה באה לעולם,\u0004 ש\"לרוב\" זה הוא מלשון מריבה, שעל ידי שנולדו בנות הרי נגרמות קטטות בין הגברים. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ריש לקיש לר' יוחנן: לדידך דאמרת\u0004 \u0005[ל\u0006שיטתך \u0005שלך שאתה אומר]\u0006 שעל ידי הבנות \u0003רבייה באה לעולם, מפני מה לא נכפלו בנותיו של איוב,\u0004 שהרי בסוף כפל לו הקדוש ברוך הוא כל מה שאיבד (ראה איוב א, ג ואיוב מב, יב), ומדוע לא כפל לו גם את מספר בנותיו?","\u0003אמר לו: נהי\u0004 \u0005[אם אמנם]\u0006 ש\u0003לא נכפלו בשמות,\u0004 שלא נתרבו במספר, \u0003אבל נכפלו ביופי, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויהי לו שבענה בנים ושלוש בנות, ויקרא שם האחת ימימה ושם השנית קציעה ושם השלישית קרן הפוך\"\u0004 (איוב מב, יג–יד), וכולן נקראו כך על שם יופיין:","\u0003ימימה\u0004 — \u0003שהיתה דומה\u0004 ביופיה \u0003ליום, קציעה\u0004 — \u0003שהיה ריחה נודף כ\u0004צמח הבושם \u0003קציעה, קרן הפוך\u0004 — \u0003אמרי דבי\u0004 \u0005[היו אומרים\u0006 חכמים \u0005מבית]\u0006 מדרשו של \u0003ר' שילא: שדומה לקרנא דקרש\u0004 \u0005[לקרן של חד־קרן]\u0006 שקרניו יפות ביותר. \u0003מחייכו עלה במערבא\u0004 \u0005[היו צוחקים על כך בארץ ישראל],\u0006 הלא \u0003קרנא דקרש לקותא היא\u0004 \u0005[קרן של קרש ליקוי הוא]\u0006 אם אדם נראה כמוהו! \u0003אלא אמר רב חסדא: ככורכמא דרישקא במיניה\u0004 \u0005[כמו כרכום של נרד ש\u0006הוא מעולה \u0005במינו]\u0006 ו\"קרן\" במשמעות: גינה, ערוגה של פוך. וראיה לדבר ש\"פוך\" עניינו תכשיט, \u0003שנאמר: \"כי תקרעי בפוך\u0004 עיניך לשוא תתייפי\u0003\"\u0004 (ירמיה ד, ל).","מסופר: \u0003ר' שמעון ברבי\u0004 \u0005[\u0006בנו \u0005של רבי]\u0006 \u0003איתילידא ליה ברתא\u0004 \u0005[נולדה לו בת],\u0006 \u0003הוה קא חלש דעתיה\u0004 \u0005[היתה לו חולשת הדעת]\u0006 מכך שלא נולד לו בן, \u0003אמר ליה אבוה\u0004 \u0005[לו אביו]:\u0006 \u0003רביה באה לעולם\u0004 על ידי הבת. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003בר קפרא: תנחומין של הבל ניחמך אבוך\u0004 \u0005[אביך].\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אי אפשר לעולם בלא זכרים ובלא נקבות\u0004 והעולם זקוק לשניהם, \u0003אלא אשרי למי שבניו זכרים, אוי לו למי שבניו נקבות;\u0004 וכיוצא בו: \u0003אי אפשר לעולם בלא\u0004 כל המקצועות, בלא \u0003בסם\u0004 שמלאכתו בבשמים, \u0003ובלא בורסי\u0004 שמלאכתו בדברים שריחם רע, \u0003אשרי מי שאומנותו בוסמי, אוי למי שאומנותו בורסי.\u0004","ומעירים: דבר זה הוא \u0003כתנאי\u0004 \u0005[כ\u0006מחלוקת \u0005תנאים]\u0006 באותו נושא. שנאמר: \u0003\"וה' ברך את אברהם בכל\"\u0004 (בראשית כד, א) ונחלקו \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"בכל\"? ר' מאיר אומר: שלא היתה לו בת\u0004 וזו היתה הברכה. \u0003ר' יהודה אומר: שהיתה לו בת. אחרים אומרים: בת היתה לו לאברהם ו\"בכל\" שמה. ר' אלעזר המודעי אומר: איצטגנינות\u0004 (ידיעת חכמת הכוכבים) \u0003היתה בלבו של אברהם אבינו, שכל מלכי מזרח ומערב\u0004 היו \u0003משכימין לפתחו\u0004 בגלל חכמתו זו, והוא הענין של הברכה \"בכל\" — בדבר שהכל צריכים לו. \u0003ר' שמעון בן יוחי אומר: אבן טובה היתה תלויה בצוארו של אברהם אבינו, שכל חולה הרואה אותו מיד מתרפא, ובשעה שנפטר אברהם אבינו מן העולם\u0004 — \u0003תלאה הקדוש ברוך הוא\u0004 לאבן זו \u0003בגלגל חמה\u0004 ומאז השמש מרפאת. \u0003אמר אביי, היינו דאמרי אינשי\u0004 \u0005[זהו שאומרים האנשים]\u0006 בפתגם עממי: \u0003אידלי יומא אידלי קצירא\u0004 \u0005[עלה היום היקל החולי].\u0006","\u0003דבר אחר:\u0004 מהו הברכה \"בכל\"? — \u0003שלא מרד עשו בימיו,\u0004 שכל עוד היה חי אברהם, לא חטא עשיו. \u0003דבר אחר: שעשה ישמעאל תשובה בימיו.\u0004 ומפרשים: \u0003שלא מרד עשו בימיו מנלן\u0004 \u0005[מנין לנו]?\u0006 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"\u0004ויזד יעקב נזיד \u0003ויבא עשו מן השדה והוא עיף\"\u0004 (בראשית כה, כט), \u0003ותנא\u0004 \u0005[ושנה\u0006 בברייתא\u0005]:\u0006 \u0003אותו היום נפטר אברהם אבינו, ועשה יעקב אבינו תבשיל של עדשים לנחם את יצחק אביו\u0004 כמפורש בהמשך (בראשית כה, לד), שכן נוהגים לעשות תבשיל עדשים לאבלים.","ומסבירים: \u0003ומאי שנא\u0004 \u0005[ומה שונה]\u0006 מדוע דווקא \u0003של עדשים? אמרי במערבא משמיה\u0004 \u0005[אומרים בארץ ישראל משמו]\u0006 של \u0003רבה בר מרי: מה עדשה זו אין לה פה\u0004 כעין סדק שיש בשאר קטניות, \u0003אף אבל אין לו פה,\u0004 שאינו יכול לדבר מחמת צערו. \u0003דבר אחר: מה עדשה זו מגולגלת,\u0004 שהיא עגולה לגמרי, כגלגל, \u0003אף אבילות מגלגלת ומחזרת על באי העולם,\u0004 ורמז הוא לאדם שכל אדם באה עליו אבילות במוקדם או במאוחר. ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל \u0005ביניהם\u0006 למעשה\u0005]\u0006 אם מסבירים כך או כך? ואומרים: \u0003איכא בינייהו לנחומי בביעי\u0004 \u0005[יש ביניהם\u0006 הבדל \u0005ל\u0006ענין \u0005ניחום בביצים]\u0006 שאין להן פה, אבל אינן עגולות לגמרי כגלגל.","\u0003אמר ר' יוחנן, חמש עבירות עבר אותו רשע\u0004 (עשיו) \u0003באותו היום\u0004 שמת אברהם: \u0003בא על נערה מאורסה, והרג את הנפש, וכפר בעיקר, וכפר בתחיית המתים, ושט\u0004 (בזה) \u0003את הבכורה.\u0004","ומביאים ראיות: \u0003בא על נערה מאורסה\u0004 — \u0003כתיב הכא\u0004 \u0005[נאמר כאן]:\u0006 \u0003\"ויבא עשו מן השדה\", וכתיב התם\u0004 \u0005[ונאמר שם]\u0006 באונס נערה מאורסה: \u0003\"כי בשדה מצאה\"\u0004 (דברים כב, כז). \u0003הרג את הנפש\u0004 — \u0003כתיב הכא\u0004 \u0005[נאמר כאן]:\u0006 \u0003\"עיף\", וכתיב התם\u0004 \u0005[ונאמר שם]:\u0006 \u0003\"אוי נא לי כי עיפה נפשי להרגים\"\u0004 (ירמיה ד, לא). \u0003וכפר בעיקר\u0004 — \u0003כתיב הכא\u0004 \u0005[נאמר כאן]:\u0006 \u0003\"\u0004ו\u0003למה זה לי\"\u0004 (בראשית כה, לב), \u0003וכתיב התם\u0004 \u0005[ונאמר שם]:\u0006 \u0003\"זה אלי ואנוהו\"\u0004 (שמות טו, ב), ו\"למה זה לי\" משמע שפקפק ב\"זה\". \u0003וכפר בתחיית המתים\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"הנה אנכי הולך למות\"\u0004 (בראשית כה, לב) שחשב שאחרי מותו שוב אין לו תחיה. \u0003ושט\u0004 (בזה) \u0003את הבכורה\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויבז עשו את הבכרה\"\u0004 (בראשית כה, לד).","\u0003ושעשה ישמעאל תשובה בימיו\u0004 של אברהם \u0003מנלן\u0004 \u0005[מנין לנו]?\u0006 \u0003כי הא\u0004 \u0005[כמו\u0006 מעשה \u0005זה]\u0006 ש\u0003רבינא ורב חמא בר בוזי הוו יתבי קמיה\u0004 \u0005[היו יושבים לפני]\u0006 \u0003רבא וקא מנמנם\u0004 \u0005[והיה מנמנם]\u0006 \u0003רבא\u0004 ובינתיים שוחחו הם. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב חמא בר בוזי, ודאי דאמריתו\u0004 \u0005[\u0006האם \u0005נכון שאתם אומרים]:\u0006 \u0003כל מיתה שיש בה\u0004 (שנאמר בה גם) לשון \u0003\"גויעה\"\u0004 — \u0003זו היא מיתתן של צדיקים? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אין\u0004 \u0005[כן]\u0006 (וכגון זה שנאמר \u0005ביצחק: \"ויגוע יצחק וימת ויאסף אל עמיו\".\u0006 בראשית לה, כט). והקשה לו: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003דור המבול\u0004 נאמר בו \"ויגוע כל בשר\" (בראשית ז, כא), והם מתו בגלל רשעם! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אנן\u0004 \u0005[אנו]\u0006 לשון \u0003\"גויעה\" ו\"אסיפה\" קאמרינן\u0004 \u0005[אומרים אנו],\u0006 שבמקום שנאמר \"ויגוע ויאסף\" זו היא מיתת צדיקים.","הקשה לו: \u0003והא\u0004 \u0005[והרי]\u0006 ישנו \u0003ישמעאל דכתיב ביה\u0004 \u0005[שנאמר בו]\u0006 \u0003גויעה ואסיפה\u0004 (\"ואלה שני חיי ישמעאל... ויגוע וימת ויאסף אל עמיו\". בראשית כה, יז)?! \u0003אדהכי איתער בהו\u0004 \u0005[בין כך התעורר בהם]\u0006 \u0003רבא,\u0004 שהיה מנמנם, אבל שמע מקצת דבריהם וניעור לגמרי, \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003דרדקי\u0004 \u0005[ילדים],\u0006 \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר ר' יוחנן: ישמעאל עשה תשובה בחיי אביו,\u0004 וראיה לדבר, \u0003שנאמר: \"ויקברו אתו יצחק וישמעאל בניו\"\u0004 (בראשית כה, ט), וכיון שהקדים ישמעאל את יצחק לפניו משמע שעשה תשובה וקיבל על עצמו את מרותו.","ושואלים: \u0003ודילמא\u0004 \u0005[ושמא]\u0006 \u0003דרך חכמתן קא חשיב להו\u0004 \u0005[מחשיב להם,\u0006 מונה אותם הכתוב\u0005]\u0006 שבאמת ישמעאל קדם, אלא שהכתוב אינו מונה אותם לפי סדר זה! ומשיבים: \u0003אלא מעתה\u0004 מה שנאמר: \u0003\"ויקברו אותו עשו ויעקב בניו\"\u0004 (בראשית לה, כט), \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא חשיב להו\u0004 \u0005[מנה אותם]\u0006 \u0003דרך חכמתן? אלא מדאקדמיה\u0004 — \u0003אדבורי אדבריה\u0004 \u0005[מכיון שהקדים אותו,\u0006 משמע ש\u0005הנהיג אותו\u0006 עליו\u0005],\u0006 \u0003ומדאדבריה\u0004 \u0005[וכיון שהנהיג אותו\u0006 עליו\u0005]\u0006 — \u0003שמע מינה\u0004 \u0005[למד מכאן]:\u0006 \u0003תשובה עבד\u0004 \u0005[עשה]\u0006 \u0003בימיו\u0004 של אברהם.","ואגב הדיון בפסוק \"וה' ברך את אברהם בכל\" (בראשית כד, א), מביאים: \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003שלשה\u0004 אנשים \u0003הטעימן הקדוש ברוך הוא בעולם הזה\u0004"],["\u0003מעין העולם הבא, אלו הן: אברהם, יצחק ויעקב. אברהם\u0004 — \u0003דכתיב ביה\u0004 \u0005[שנאמר בו]:\u0006 \u0003\"\u0004ואברהם זקן בא בימים וה' ברך את אברהם \u0003בכל\"\u0004 (בראשית כד, א). \u0003יצחק\u0004 — \u0003דכתיב ביה\u0004 \u0005[שנאמר בו]:\u0006 \u0003\"\u0004ואוכל \u0003מכל\"\u0004 (שםבראשית כז, יג) \u0003יעקב\u0004 — \u0003דכתיב ביה\u0004 \u0005[שנאמר בו]:\u0006 \u0003\"\u0004כי חנני אלהים וכי יש לי \u0003כל\"\u0004 (בראשית לג, יא). לומר שזכו בחייהם למידה של שלמות (\"כל\").","\u0003שלשה לא שלט בהן יצר הרע, אלו הן: אברהם, יצחק ויעקב, דכתיב בהו\u0004 \u0005[שנאמר בהם]:\u0006 \u0003\"בכל\", \"מכל\", \"כל\".\u0004 וזה הוא ענין הברכה השלימה, שלא היו צריכים להלחם ביצרם. \u0003ויש אומרים: אף דוד, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ולבי חלל בקרבי\"\u0004 (תהילים קט, כב), לומר שיצר הרע שבלבו בטל כאילו היה לבו חלל. ושואלים: \u0003ואידך\u0004 \u0005[והאחר]\u0006 שאינו מונה את דוד, מה הוא מסביר? ומשיבים: \u0003צעריה\u0004 \u0005[צערו]\u0006 \u0003הוא דקא מדכר\u0004 \u0005[שמזכיר],\u0006 שהתכוון לומר שלבו מת בתוכו מרוב הצרות שעברו עליו, ולא לענין יצר הרע.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003ששה לא שלט בהן מלאך המות\u0004 בפטירתם, \u0003ואלו הן: אברהם, יצחק ויעקב, משה, אהרן ומרים. אברהם, יצחק ויעקב\u0004 — \u0003דכתיב בהו\u0004 \u0005[שנאמר בהם]:\u0006 \u0003\"בכל\", \"מכל\", \"כל\",\u0004 וכיון שניתן להם כל הטוב ודאי נפטרו גם מצרת מלאך המות; \u0003משה, אהרן ומרים\u0004 — \u0003דכתיב בהו\u0004 \u0005[שנאמר בהם]:\u0006 \u0003\"על פי ה'\"\u0004 (\"ויעל אהרן הכהן אל הור ההר על פי ה' וימת שם\". במדבר לג, לח. \"וימת שם משה עבד ה' בארץ מואב על פי ה'\". דברים לד, ה) שהיא מיתת נשיקה (\"על פי\") ולא בידי מלאך המות.","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003מרים לא כתיב\u0004 \u0005[נאמר]\u0006 \u0003בה \"על פי ה'\"! אמר ר' אלעזר: מרים נמי\u0004 \u0005[גם כן]\u0006 \u0003בנשיקה מתה, דאתיא\u0004 \u0005[שבא,\u0006 נלמד\u0005]\u0006 הדבר בגזירה שווה של \u0003\"שם\" \"שם\" ממשה\u0004 (\"ותמת שם מרים\". במדבר כ, א. \"וימת שם משה\". דברים לד, ה). \u0003ומפני מה לא נאמר בה \"על פי ה'\"?\u0004 — \u0003שגנאי הדבר לומר\u0004 מיתת נשיקה באשה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003שבעה לא שלט בהן רמה ותולעה, ואלו הן: אברהם, יצחק ויעקב, משה, אהרן ומרים, ובנימין בן יעקב.\u0004 ומפרטים: \u0003אברהם, יצחק ויעקב\u0004 — \u0003דכתיב בהו\u0004 \u0005[שנאמר בהם]:\u0006 \u0003\"בכל\", \"מכל\", \"כל\"; משה, אהרן ומרים\u0004 — \u0003דכתיב בהו\u0004 \u0005[שנאמר בהם]:\u0006 \u0003\"על פי ה'\"; בנימין בן יעקב\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ולבנימין אמר ידיד ה' ישכן לבטח עליו\"\u0004 (דברים לג, יב). שאף כאשר שכן במותו היה זה לבטח, בלא שתגיענו תולעת. \u0003ויש אומרים: אף דוד, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"אף בשרי ישכן לבטח\"\u0004 (תהילים טז, ט). ושואלים: \u0003ואידך\u0004 \u0005[והאחר]\u0006 שאינו סבור כן כיצד הוא מפרש? ומשיבים: \u0003ההוא רחמי הוא דקא בעי\u0004 \u0005[רחמים הוא שמבקש]\u0006 שכך יהיה לו במותו, ואולם לא נתקבלה בקשתו זו. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003ארבעה מתו בעטיו\u0004 (בעצתו, בסיבתו) \u0003של נחש\u0004 הקדמוני, שנגזרה מיתה על בני האדם כולם, ולא מפני חטאיהם. \u0003ואלו הן: בנימין בן יעקב, ועמרם אבי משה, וישי אבי דוד, וכלאב בן דוד. וכולהו גמרא\u0004 \u0005[וכולם מסורת]\u0006 שכך היה, \u0003לבר\u0004 \u0005[חוץ]\u0006 \u0003מישי אבי דוד\u0004 ש\u0003מפרש ביה [קרא]\u0004 \u0005[בו המקרא],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ואת עמשא שם אבשלם תחת יואב על הצבא ועמשא בן איש ושמו יתרא הישראלי אשר בא אל אביגיל בת נחש אחות צרויה אם יואב\"\u0004 (שמואל ב' יז, כה), \u0003וכי\u0004 אביגיל \u0003בת נחש היא? והלא בת ישי היא, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ואחיתיהם צרויה ואביגיל\"\u0004 (דברי הימים א' ב, טז)! \u0003אלא,\u0004 נקראה \"בת נחש\" לומר: \u0003בת מי שמת בעטיו של נחש.\u0004","","","\u0003לא יחפור אדם בור סמוך לבורו של חבירו,\u0004 שלא יקלקל על ידי כן את הבור, \u0003ו\u0004כן \u0003לא\u0004 יעשה \u0003שיח\u0004 (בור ארוך וצר) \u0003ולא מערה\u0004 (בור מכוסה), \u0003ולא אמת המים\u0004 (תעלה), \u0003ולא נברכת כובסין\u0004 (חפירה של מים המשמשת לכביסה), \u0003אלא אם כן הרחיק\u0004 את כל אלה \u0003מכותל חבירו שלשה טפחים וסד בסיד\u0004 את המקום שיש בו מים.","\u0003ומרחיקים את הגפת\u0004 (פסולת הזיתים לאחר שהוצא מהם השמן) \u0003ואת הזבל\u0004 של בהמות, \u0003ואת המלח ואת הסיד, ואת הסלעים מכותלו של חבירו שלשה טפחים\u0004 שלא יזיקו לכותל, \u0003או סד בסיד\u0004 את הקיר שלא יינזק. \u0003מרחיקין את הזרעים,\u0004 שאין זורעים, \u0003ואת המחרישה\u0004 שאין חורשים, \u0003ואת מי רגלים מן הכותל\u0004 של חבירו \u0003שלשה טפחים.\u0004","\u0003ומרחיקין את הריחים\u0004 מן הכותל מרחק \u0003שלשה\u0004 טפחים \u0003מן השכב\u0004 (האבן התחתונה של הריחיים), \u0003שהן ארבעה\u0004 טפחים \u0003מן הרכב\u0004 (האבן העליונה) שהיא קטנה יותר; \u0003ואת התנור\u0004 — \u0003שלשה מן הכליא,\u0004 החלק הבולט שלו, \u0003שהן ארבעה מן השפה\u0004 הצרה יותר של התנור."],["על המשנה תוהים: \u0003פתח בבור,\u0004 \"לא יחפור בור סמוך לבורו של חבירו\", \u0003ומסיים בכותל\u0004 \"אלא אם כן הרחיק מכותל חבירו\", \u0003ליתני\u0004 \u0005[שישנה]:\u0006 \u0003אלא אם כן הרחיק מבורו של חבירו שלשה טפחים\u0004 כמו בתחילת המשנה, ומדוע מזכיר כאן כותל?","\u0003אמר אביי, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003רב יהודה: מכותל בורו שנינו\u0004 וכך היא שנויה: \"אלא אם הרחיק מכותל בורו של חבירו שלשה טפחים\", שאף חבירו הרחיק את חלל בורו מרחק שיעור כותל מן הגבול שביניהם.","ושואלים: \u0003וליתני\u0004 \u0005[ושישנה]:\u0006 \u0003אלא אם כן הרחיק מבורו של חבירו שלשה טפחים,\u0004 וממילא מובן שהכוונה לכותל הבור! ומשיבים: \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה השמיע לנו]\u0006 בדרך אגב, ש\u0003כותל בור\u0004 צריך להיות לפחות \u0003שלשה טפחים, נפקא מינה\u0004 \u0005[יוצא מכאן]\u0006 תוצאה \u0003ל\u0004דיני \u0003מקח וממכר; כדתניא\u0004 \u0005[כפי ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003האומר לחבירו \"בור וכותליה אני מוכר לך\"\u0004 — \u0003צריך שיהא הכותל\u0004 של הבור \u0003שלשה טפחים.\u0004","\u0003איתמר\u0004 \u0005[נאמר]:\u0006 \u0003הבא לסמוך\u0004 באחד מכל הדברים הללו \u0003בצד המצר,\u0004 על גבול שדהו, שאין שם בור של החבר — \u0003אביי אמר: סומך, ורבא אמר: אינו סומך.\u0004 ומסבירים: \u0003בשדה\u0004 חבירו \u0003העשויה ל\u0004כך שיכרו בה \u0003בורות\u0004 — \u0003דברי הכל אינו סומך,\u0004 שהרי יודע שהשדה עשוי לכריית בורות. \u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 — הרי זה \u0003בשדה שאינה עשויה לבורות.\u0004","\u0003אביי אמר\u0004 \u0005[אומר]:\u0006 \u0003סומך,\u0004 וטעם הדבר — \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003אינה עשויה לבורות; רבא אמר\u0004 \u0005[אומר]:\u0006 \u0003אינו סומך, דאמר ליה\u0004 \u0005[שאומר לו]\u0006 השכן: \u0003כי היכי דאת אימלכת\u0004 \u0005[כמו שאתה נמלכת]\u0006 בדעתך \u0003וחפרת\u0004 בור, \u0003אנא נמי ממלכנא וחפרנא\u0004 \u0005[אני גם כן\u0006 אולי \u0005אמלך\u0006 בדעתי \u0005ואחפור]\u0006 ועתה לא אוכל לחפור סמוך לגבולי, כיון שאתה קירבת את בורך עד למצר.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 מחלוקת זו באופן אחר: \u0003בשדה שאינה עשויה לבורות\u0004 — \u0003דברי הכל סומך, כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 הרי זה \u0003בשדה העשויה לבורות.\u0004 \u0003אביי אמר: סומך.\u0004 ו\u0003אפילו לרבנן דאמרי\u0004 \u0005[לחכמים שאומרים]\u0006 במשנה להלן: \u0003מרחיקין את האילן מן הבור עשרים וחמש אמה,\u0004 שצריך לדאוג שלא יצמחו שרשי האילן שלו ויזיקו לבורו של חבירו בשדהו, ולכך על המזיק להרחיק את עצמו, \u0003התם\u0004 \u0005[שם]\u0006 הדין כך \u0003הוא\u0004 משום \u0003דבעידנא דקא נטע איתא\u0004 \u0005[שבזמן שהוא נוטע\u0006 כבר \u0005ישנו]\u0006 \u0003לבור, אבל הכא בעידנא דקא חפר ליתא לבור\u0004 \u0005[כאן בזמן שהוא חופר\u0006 בשדהו \u0005אין הבור]\u0006 של השכן קיים עדיין.","\u0003ורבא אמר: אינו סומך. ואפילו ל\u0004דעת \u0003ר' יוסי דאמר\u0004 \u0005[שאומר]\u0006 באותה משנה: \u0003זה חופר בתוך שלו וזה נוטע בתוך שלו\u0004 ואינו צריך להרחיק מפני החשש שמא אילנו יתפשט ויזיק לאחר, \u0003הני מילי התם\u0004 \u0005[דברים אלה\u0006 אמורים דווקא \u0005שם],\u0006 \u0003דבעידנא דקא נטע ליתנהו לשרשיו דמזקי ליה\u0004 \u0005[שבזמן שהוא נוטע אין\u0006 עדיין \u0005שורשים שמזיקים לו]\u0006 \u0003לבור,\u0004 ונמצא שבשעת נטיעה לא גרם שום היזק, \u0003אבל הכא\u0004 \u0005[כאן]\u0006 — \u0003אמר ליה\u0004 \u0005[\u0006יכול \u0005לומר לו]:\u0006 \u0003כל מרא ומרא דקא מחיית קא מרפית ליה לארעאי\u0004 \u0005[כל מעדר ומעדר שאתה מקיש בו מרפה את הקרקע שלי]\u0006 וכבר עכשיו אתה גורם לי נזק.","ומנסים להביא עוד ראיה, \u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003לא יחפור אדם בור סמוך לבורו של חבירו\u0004 אלא אם כן הרחיק מכותל חבירו שלושה טפחים. ונדייק מכאן: \u0003טעמא דאיכא\u0004 \u0005[הטעם,\u0006 דווקא, \u0005שיש\u0006 שם\u0005]\u0006 \u0003בור, הא ליכא\u0004 \u0005[הרי\u0006 אם \u0005אין]\u0006 \u0003בור\u0004 — \u0003סומך\u0004 לכותל חבירו. ומעתה, \u0003בשלמא להך לישנא\u0004 \u0005[נניח ל\u0006פי \u0005אותה לשון]\u0006 ש\u0003אמרת\u0004 ש\u0003בשדה שאינה עשויה לבורות דברי הכל סומך,\u0004 אם כן אפשר להסביר כי \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 עוסקת \u0003בשדה שאינה עשויה לבורות.\u0004","\u0003אלא להך לישנא\u0004 \u0005[ל\u0006פי \u0005אותה לשון]\u0006 ש\u0003אמרת:\u0004 ש\u0003בשדה שאינה עשויה לבורות פליגי\u0004 \u0005[חלוקים הם],\u0006 \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003לאביי ניחא\u0004 \u0005[נוח\u0006 הדבר\u0005],\u0006 כפי שדייקנו ממשנתנו, שכשאין בור — סומך, \u0003אלא לרבא קשיא\u0004 \u0005[קשה],\u0006 שהוא אומר שאסור לסמוך למצר בכל אופן!","ומתרצים: \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך רבא:\u0004 אינך יכול לדייק דיוק זה ממשנתנו, שכן \u0003הא איתמר עלה\u0004 \u0005[הרי נאמר עליה],\u0006 \u0003אמר אביי ואיתימא\u0004 \u0005[ויש שאומרים]\u0006 שאמר זאת \u0003רב יהודה: מכותל בורו\u0004 של חבירו \u0003שנינו.\u0004 ומכאן שחבירו שחפר בתחילה צריך היה כבר להרחיק את חלל בורו שלושה טפחים מן המצר.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 הסבר זה כהוכחה נגד אביי. שנינו במשנה שמרחיק מבורו של חבירו, \u0003ואיתמר עלה\u0004 \u0005[ונאמר עליה],\u0006 \u0003אמר אביי ואיתימא\u0004 \u0005[ויש אומרים]\u0006 \u0003רב יהודה: מכותל בורו שנינו\u0004 ומכאן למדנו שחבירו כבר הרחיק כדי שיעור כותל מן המצר. ומעתה, \u0003בשלמא להך לישנא\u0004 \u0005[נניח ל\u0006פי \u0005אותה לשון]\u0006 ש\u0003אמרת: בשדה העשויה לבורות דברי הכל אינו סומך,\u0004 לפי זה \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 עוסקת \u0003בשדה העשויה לבורות.\u0004","\u0003אלא להך לישנא\u0004 \u0005[ל\u0006פי \u0005אותה לשון]\u0006 ש\u0003אמרת: בשדה העשויה לבורות פליגי\u0004 \u0005[חלוקים\u0006 הם\u0005],\u0006 \u0003בשלמא לרבא ניחא\u0004 \u0005[ל\u0006שיטת \u0005רבא נוח\u0006 הדבר\u0005],\u0006 \u0003אלא לאביי קשיא\u0004 \u0005[קשה],\u0006 הרי לא היה צריך חבירו להרחיק את בורו מן המצר!","ומתרצים: \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך אביי: מתניתין\u0004 \u0005[משנתנו]\u0006 מדברת באופן \u0003שבאו לחפור\u0004 שניהם \u0003בבת אחת\u0004 ואז צריכים שניהם להרחיק. אבל אם אין עדיין בור סמוך למצר, וחבירו אינו בא לחפור באותה שעה — רשאי לסמוך למצר.","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר ממה ששנינו בברייתא: \u0003סלע הבא בידים,\u0004 כלומר, סלע רך שאפשר לחפור בו בידים בלבד, בלי כלי — \u0003זה חופר בורו מכאן, וזה חופר בורו מכאן, זה מרחיק שלשה טפחים וסד בסיד, וזה מרחיק שלשה טפחים וסד בסיד,\u0004 משמע מכאן שאפילו הראשון צריך להרחיק גם כשאין עוד בור של השני! ודוחים: \u0003בא בידים שאני\u0004 \u0005[שונה]\u0006 כיון שהסלע רך מאד צריך להרחיק יותר.","ותוהים: \u0003ודקארי לה מאי קארי לה\u0004 \u0005[ו\u0006זה \u0005שהקשה אותה מה הקשה אותה]?\u0006 הרי במפורש נאמר שכאן מדובר בסלע הבא בידים! ומשיבים: לדעתו מדברת הברייתא בכל סוג של קרקע, אלא \u0003בא בידים איצטריכא ליה\u0004 \u0005[הוצרך לו]\u0006 לתנא לומר ולהשתמש דווקא בדוגמא זו, שכן \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006 ש\u0003כיון\u0004 ש\u0003בא בידים ליבעי נמי רווחא טפי\u0004 \u0005[יצטרך גם רווח\u0006 גדול \u0005יותר],\u0006 על \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שדי בשלושה טפחים.","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר ממה ששנינו במשנתנו: \u0003מרחיקין את הגפת, ואת הזבל, ואת\u0004"],["\u0003המלח, ואת הסיד, ואת הסלעים מכותלו של חבירו שלשה טפחים או סד בסיד;\u0004 ונדייק: \u0003טעמא דאיכא\u0004 \u0005[הטעם,\u0006 דווקא, \u0005כשיש\u0006 שם\u0005]\u0006 \u0003כותל\u0004 של חבירו, \u0003הא ליכא\u0004 \u0005[הרי\u0006 אם \u0005אין]\u0006 \u0003כותל\u0004 — \u0003סומך\u0004 עד לגבול החצר. וקשה לרבא, לפי השיטה הראשונה שאין סומך אפילו לשדה שאינו עשוי לבורות!","ודוחים: \u0003לא, כי ליכא\u0004 \u0005[כאשר אין]\u0006 \u0003כותל נמי לא סמיך\u0004 \u0005[גם כן אינו סומך].\u0006 \u0003ו\u0004שואלים: אם כן, \u0003אלא מאי קא משמע לן\u0004 \u0005[מה השמיע לנו]\u0006 בזה שמזכיר פה כותל? ומשיבים: \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה השמיע לנו],\u0006 \u0003דהני קשו\u0004 \u0005[ש\u0006כל הדברים \u0005הללו קשים]\u0006 ומזיקים \u0003לכותל.\u0004","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו במשנתנו: \u0003מרחיקים את הזרעים, ואת המחרישה, ואת מי רגלים מן הכותל שלשה טפחים;\u0004 ונדייק: \u0003טעמא דאיכא\u0004 \u0005[הטעם,\u0006 דווקא, כ\u0005שיש\u0006 שם\u0005]\u0006 \u0003כותל, הא ליכא\u0004 \u0005[הרי\u0006 אם \u0005אין]\u0006 שם \u0003כותל\u0004 — \u0003סמיך\u0004 \u0005[סומך]\u0006 עד לגבול השדה! ודוחים: \u0003לא, כי ליכא\u0004 \u0005[כאשר אין]\u0006 \u0003כותל נמי לא סמיך\u0004 \u0005[גם כן אינו סומך].\u0006 ושואלים: \u0003ואלא מאי קא משמע לן\u0004 \u0005[מה השמיע לנו]?\u0006 ומשיבים: \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה השמיע לנו],\u0006 \u0003דמתונתא\u0004 \u0005[שרטיבות]\u0006 \u0003קשה לכותל.\u0004","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר ממה ששנינו: \u0003ואת הריחים\u0004 — מרחיק מן הכותל \u0003שלשה\u0004 טפחים \u0003מן השכב שהן ארבעה\u0004 טפחים \u0003מן הרכב;\u0004 ונדייק: \u0003טעמא דאיכא\u0004 \u0005[הטעם\u0006 דווקא \u0005כשיש]\u0006 \u0003כותל, הא ליכא\u0004 \u0005[הרי\u0006 אם \u0005אין]\u0006 שם \u0003כותל\u0004 — \u0003סמיך\u0004 \u0005[סומך]\u0006 עד הגבול! ודוחים: \u0003לא, כי ליכא\u0004 \u0005[כאשר אין]\u0006 שם \u0003כותל נמי לא סמיך\u0004 \u0005[גם כן אינו סומך].\u0006 ושואלים: \u0003ואלא מאי קא משמע לן\u0004 \u0005[מה השמיע לנו]?\u0006 ומשיבים: \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה השמיע לנו],\u0006 \u0003דטירייא\u0004 \u0005[שהזעזוע]\u0006 \u0003קשה לכותל.\u0004","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר ממה ששנינו עוד במשנתנו: \u0003ואת התנור\u0004 — מרחיק מן הכותל \u0003שלשה\u0004 טפחים \u0003מן הכליא שהן ארבעה טפחים מן השפה.\u0004 ונדייק: \u0003טעמא דאיכא\u0004 \u0005[הטעם,\u0006 דווקא, \u0005שיש]\u0006 שם \u0003כותל, הא ליכא\u0004 \u0005[הרי\u0006 אם \u0005אין]\u0006 שם \u0003כותל\u0004 — \u0003סמיך\u0004 \u0005[סומך]!\u0006 ודוחים: \u0003לא, כי ליכא\u0004 \u0005[כאשר אין]\u0006 \u0003כותל נמי לא סמיך\u0004 \u0005[גם כן אינו סומך].\u0006 ושואלים: \u0003אלא מאי קא משמע לן\u0004 \u0005[מה השמיע לנו]?\u0006 ומשיבים: \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה השמיע לנו],\u0006 \u0003דהבלא\u0004 \u0005[שההבל,\u0006 החום\u0005]\u0006 \u0003קשה לכותל.\u0004","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר ממה ששנינו במשנה להלן: \u0003לא יפתח אדם חנות של נחתומין\u0004 (אופים) או \u0003של צבעין תחת אוצרו\u0004 (מחסן יין) \u0003של חבירו, ולא\u0004 יפתח שם \u0003רפת בקר.\u0004 ונדייק: \u0003טעמא דאיכא\u0004 \u0005[הטעם,\u0006 דווקא \u0005כשיש]\u0006 שם \u0003אוצר\u0004 במקום, \u0003הא ליכא\u0004 \u0005[הרי\u0006 אם \u0005אין]\u0006 שם \u0003אוצר\u0004 — \u0003עביד\u0004 \u0005[\u0006יכול \u0005לעשות]\u0006 ומכאן יש ללמוד אף לבור, שמותר לחפור סמוך למצר!","ומשיבים: דין \u0003דירה שאני\u0004 \u0005[שונה],\u0006 ששם יש לאדם רשות לעשות בדרך כלל מה שהוא רוצה, אלא אם הוא מזיק באותה שעה. \u0003דיקא נמי\u0004 \u0005[מדויק גם כן],\u0006 \u0003דתני עלה\u0004 \u0005[ששנויה\u0006 ברייתא מפורשת \u0005עליה]:\u0006 \u0003אם היתה רפת\u0004 ה\u0003בקר קודמת לאוצר\u0004 — \u0003מותר,\u0004 ולא נאמר כך בברייתא על הדינים של משנתנו שאינם עוסקים במקום דירה.","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר ממה ששנינו: \u0003לא יטע אדם אילן סמוך לשדה אלא אם כן הרחיק ממנו ארבעה אמות, ותני עלה\u0004 \u0005[ושנויה\u0006 ברייתא \u0005עליה]:\u0006 \u0003ארבעה אמות שאמרו\u0004 — \u0003כדי עבודת הכרם,\u0004 שצריך מרחב קצת ליד האילנות להביא שם בהמות החורשות בין האילנות, ויש חשש שיזיק בכך לשדה הסמוך.","ונדייק: \u0003טעמא\u0004 \u0005[הטעם\u0006 דווקא\u0005]\u0006 ש\u0003משום כדי עבודת הכרם, הא לאו\u0004 \u0005[הרי\u0006 אם \u0005לא\u0006 היה\u0005]\u0006 \u0003משום כדי עבודת הכרם\u0004 — \u0003סמיך\u0004 \u0005[סומך],\u0006 \u0003ואף על גב דאיכא שרשין דקא מזקי\u0004 \u0005[ואף על פי שיש שורשים\u0006 של האילן \u0005שמזיקים]\u0006 לתבואה! ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — באופן \u0003ש\u0004\u0003מפסיק צונמא\u0004 \u0005[סלע]\u0006 מלמטה, ואינו מניח לשורשים לעבור.","ומוסיפים: \u0003דיקא נמי\u0004 \u0005[מדוייק גם כן]\u0006 הדבר ממה \u0003דקתני\u0004 \u0005[ש\u0006הוא \u0005שונה]\u0006 בהמשך: אם \u0003היה גדר בינתים\u0004 — \u0003זה סומך לגדר מכאן, וזה סומך לגדר מכאן,\u0004 ואם מדובר במקרה שהשורשים יכולים לעבור — כיצד רשאי השני לסמוך? ומכאן משמע שהיה סלע מפסיק מלמטה, וכיון שכך אין מרחיק אלא משום עבודת האילן.","ואומרים: \u0003אי הכי, אימא סיפא\u0004 \u0005[אם כך, אמור\u0006 את \u0005סופה\u0006 של אותה משנה\u0005]:\u0006 \u0003היו שרשיו\u0004 של האילן \u0003יוצאין בתוך של חבירו\u0004 — \u0003מעמיק להן\u0004 החבר \u0003שלשה טפחים,\u0004 שחותך את השרשים עד לעומק שלושה טפחים \u0003כדי שלא יעכב\u0004 את \u0003המחרישה; ואי\u0004 \u0005[ואם]\u0006 מדובר באופן ש\u0003מפסיק צונמא\u0004 \u0005[הסלע],\u0006 אם כן \u0003מאי בעו התם\u0004 \u0005[מה עושים שם\u0006 השורשים\u0005],\u0006 כיצד הם מגיעים לשם? ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך הוא אומר]:\u0006 \u0003ואי לאו צונמא\u0004 \u0005[ואם אין\u0006 שם \u0005סלע],\u0006 \u0003והיו שרשיו יוצאין לתוך של חבירו\u0004 — \u0003מעמיק שלשה טפחים כדי שלא יעכב\u0004 את \u0003המחרישה.\u0004","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר ממה ששנינו: \u0003מרחיקין את האילן מן הבור עשרים וחמש אמה;\u0004 ונדייק: \u0003טעמא דאיכא\u0004 \u0005[הטעם,\u0006 דווקא כ\u0005שיש\u0006 שם\u0005]\u0006 \u0003בור, הא ליכא\u0004 \u0005[הרי\u0006 אם \u0005אין]\u0006 שם \u0003בור\u0004 — \u0003סמיך\u0004 \u0005[סומך]!\u0006 ואומרים: \u0003לא, כי ליכא\u0004 \u0005[כאשר אין]\u0006 שם \u0003בור נמי לא סמיך\u0004 \u0005[גם כן אינו סומך],\u0006 \u0003ו\u0004מדוע הוזכר כאן הבור? \u0003הא קמשמע לן\u0004 \u0005[\u0006דבר \u0005זה השמיע לנו],\u0006 ש\u0003עד עשרים וחמש אמה אזלי\u0004 \u0005[הולכים]\u0006 \u0003שרשים ומזקי\u0004 \u0005[ומזיקים]\u0006 \u0003לבור.\u0004","ומקשים: \u0003אי הכי, אימא סיפא\u0004 \u0005[אם כך, אמור\u0006 את \u0005סופה\u0006 של אותה הלכה\u0005]:\u0006 \u0003ואם אילן קדם\u0004 לבור — \u0003לא יקוץ\u0004 את האילן; \u0003ואי דלא סמיך\u0004 \u0005[ואם\u0006 מתחילה \u0005אינו\u0006 רשאי \u0005לסמוך\u0006 את האילן לגבול\u0005],\u0006 \u0003היכי משכחת לה\u0004 \u0005[איך אתה יכול למצוא אותה]\u0006 מוסברת? מדוע לא יצטרך לקצוץ? ומשיבים: \u0003כדאמר\u0004 \u0005[כמו שאמר]\u0006 \u0003רב פפא\u0004 בענין דומה, שמדובר \u0003בלוקח\u0004 שקנה עכשיו חלקת שדה זו, \u0003הכי נמי\u0004 \u0005[כאן גם כן\u0006 מדובר\u0005]\u0006 \u0003בלוקח,\u0004 כגון שבשדה של המוכר היו בור ואילן סמוכים, ומכר אחד מהם לאחר.","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו: \u0003מרחיקין את המשרה\u0004 (מים ששורים בהם פשתן) \u0003מן הירק, ו\u0004מרחיקין \u0003את הכרישין\u0004 (כרתי) \u0003מן הבצלין, ו\u0004מרחיקים \u0003את החרדל מן הדבורים.\u0004 ונדייק מכאן: \u0003טעמא דאיכא\u0004 \u0005[הטעם\u0006 דווקא \u0005שיש\u0006 שם\u0005]\u0006 \u0003ירק, הא ליכא\u0004 \u0005[הרי\u0006 אם \u0005אין]\u0006 \u0003ירק\u0004 — \u0003סמיך\u0004 \u0005[סומך]\u0006 משרה אם רוצה הוא בכך! ודוחים: \u0003לא, כי ליכא\u0004 \u0005[כאשר אין]\u0006 \u0003ירק נמי לא סמיך\u0004 \u0005[גם כן אינו סומך],\u0006 \u0003והא קא משמע לן\u0004 \u0005[ו\u0006דבר \u0005זה השמיע לנו],\u0006 \u0003דהני קשו אהדדי\u0004 \u0005[ש\u0006דברים \u0005אלה מזיקים זה לזה].\u0006","ומשיבים: \u0003אי הכי, אימא סיפא\u0004 \u0005[אם כך, אמור\u0006 את \u0005סוף\u0006 אותה משנה\u0005]:\u0006 \u0003ר' יוסי מתיר בחרדל, מפני שיכול לומר לו\u0004 לבעל הדבורים: \u0003עד שאתה אומר לי הרחק חרדלך מן דבוראי\u0004 \u0005[הדבורים שלי],\u0006 אני יכול לומר לך: \u0003הרחק דבורך מן חרדלאי\u0004 \u0005[חרדליי],\u0006 כיון \u0003ש\u0004הן \u0003באות ואוכלות\u0004 את \u0003לגלוגי חרדלאי\u0004 \u0005[צמחי החרדל שלי],\u0006 ואם כן, גם אתה מזיק לי."],["\u0003ואי\u0004 \u0005[ואם]\u0006 תאמר ש\u0003לא סמיך\u0004 \u0005[סומך]\u0006 אדם לגבול חבירו בדבר העלול להזיק, \u0003היכי משכחת לה\u0004 \u0005[איך אתה יכול למצוא אותה]?\u0006 \u0003אמר רב פפא:\u0004 כאן מדובר \u0003בלוקח\u0004 (קונה)\u0005,\u0006 שקנה מקצת שדה חבירו ובו דבר המזיק, כגון משרה או חרדל, ובחלקו השני של השדה העמיד הקונה דבר הניזק, ונמצא שהדבר המזיק נעשה סמוך לגבול השכן בהיתר.","ומקשים: \u0003אי\u0004 \u0005[אם]\u0006 מדובר \u0003בלוקח, מאי טעמא דרבנן\u0004 \u0005[מה הטעם של חכמים]\u0006 שהשני יכול לדרוש ממנו להרחיק? הלא ברשות גמורה עשה! \u0003ועוד\u0004 אפשר לשאול, \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' יוסי\u0004 שחולק דווקא בחרדל ודבורים? \u0003אפילו משרה וירקא\u0004 \u0005[וירק]\u0006 \u0003נמי\u0004 \u0005[גם כן]\u0006 צריך להיות בהם דין זה, מדוע יהא חייב להרחיק, הואיל ועשה בהיתר!","\u0003אמר רבינא:\u0004 כך צריך להבין, \u0003קא סברי רבנן\u0004 \u0005[סבורים חכמים\u0006 בכלל\u0005]:\u0006 \u0003על המזיק להרחיק את עצמו.\u0004 כלומר, מי שגורם נזק לאחר הוא זה שצריך להתרחק, שלא יביא לנזק, ואפילו עשה מתחילה ברשות (כגון שקנה מחצית שדה).","ומקשים: \u0003מכלל\u0004 הדברים אתה לומד ש\u0003ר' יוסי\u0004 שחולק \u0003סבר\u0004 \u0005[סבור]\u0006 כי \u0003על הניזק להרחיק\u0004 \u0003את עצמו,\u0004 ואולם \u0003אי\u0004 \u0005[אם]\u0006 לדעתו \u0003על הניזק\u0004 להרחיק, \u0003אפילו משרה וירקא\u0004 \u0005[וירק]\u0006 \u0003נמי\u0004 \u0005[גם כן]\u0006 אין בעל המשרה צריך להרחיק, ומדוע מחלק ר' יוסי בין אלה לדבורים וחרדל!","\u0003אלא, לעולם\u0004 צריך לומר ש\u0003ר' יוסי נמי\u0004 \u0005[גם כן]\u0006 \u0003על המזיק\u0004 להרחיק את עצמו \u0003סבירא ליה\u0004 \u0005[סבור הוא],\u0006 ואף שעשה ברשות, \u0003ו\u0004אולם \u0003הכי קאמר להו\u0004 \u0005[כך אמר להם]\u0006 \u0003ר' יוסי לרבנן\u0004 \u0005[לחכמים]:\u0006 \u0003תינח\u0004 \u0005[נניח]\u0006 \u0003משרה וירקא\u0004 \u0005[וירק],\u0006 שמחייבים את המזיק להרחיק, משום \u0003דהני מזקי הני והני לא מזקי הני\u0004 \u0005[שאלה מזיקים\u0006 את \u0005אלה ואלה אינם מזיקים\u0006 את \u0005אלה],\u0006 המשרה מזיקה את הירק, והירק אינו מזיק למשרה, \u0003אלא חרדל ודבורים\u0004 — \u0003תרוייהו מזקי אהדדי\u0004 \u0005[שניהם מזיקים זה לזה]\u0006 ומשום כך, כיון שנזרע החרדל ברשות — מדוע לא נחייב אף את בעל הדבורים להרחיק?","ומעירים: \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 מה הם אומרים? — הם סבורים ש\u0003דבורים לחרדל לא מזקי ליה\u0004 \u0005[אינם\u0006 יכולים \u0005להזיק לו].\u0006 וטעמו של דבר: \u0003אי בבינתא\u0004 \u0005[אם\u0006 מדובר \u0005בזרע]\u0006 — \u0003לא משכחא ליה\u0004 \u0005[אין אתה מוצא]\u0006 הזדמנות שהדבורה תגיע אליו, \u0003אי בטרפא\u0004 \u0005[אם בעלה]\u0006 — \u0003הדר פארי\u0004 \u0005[חוזר וצומח]\u0006 ואין כאן נזק.","ושואלים: \u0003וסבר\u0004 \u0005[ו\u0006האם \u0005סבור]\u0006 \u0003ר' יוסי\u0004 כי \u0003על המזיק להרחיק את עצמו? והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005],\u0006 \u0003ר' יוסי אומר: אף על פי שהבור קודמת לאילן\u0004 — \u0003לא יקוץ\u0004 זה את האילן, \u0003שזה חופר\u0004 בור \u0003בתוך שלו, וזה נוטע בתוך שלו! אלא, לעולם\u0004 צריך לומר ש\u0003ר' יוסי סבירא ליה\u0004 \u0005[סבור הוא]\u0006 ש\u0003על הניזק\u0004 להרחיק את עצמו, \u0003ולדבריהם דרבנן קאמר להו\u0004 \u0005[של חכמים אמר להם],\u0006 לפי שיטתם, וכך אמר:","\u0003לדידי\u0004 \u0005[לעצמי,\u0006 לשיטתי\u0005]\u0006 \u0003על הניזק להרחיק את עצמו, ואפילו משרה וירקא\u0004 \u0005[וירק]\u0006 \u0003לא בעי רחוקי\u0004 \u0005[צריך\u0006 בעל המשרה \u0005להרחיק].\u0006 \u0003אלא לדידכו דאמריתו\u0004 \u0005[לכם,\u0006 לשיטתכם \u0005שאתם אומרים]\u0006 ש\u0003על המזיק\u0004 להרחיק את עצמו, \u0003תינח\u0004 \u0005[נניח]\u0006 \u0003משרה וירקא\u0004 \u0005[וירק],\u0006 \u0003דהני מזקי הני והני לא מזקי הני\u0004 \u0005[שאלה מזיקים\u0006 את \u0005אלה ואלה אינם מזיקים\u0006 את \u0005אלה],\u0006 \u0003אלא חרדל ודבורים\u0004 — \u0003תרוייהו מזקי אהדדי\u0004 \u0005[שניהם מזיקים זה לזה],\u0006 ואם עשה בעל החרדל ברשות — מדוע לא נחייב אף את בעל הדבורים להרחיק?","ומוסיפים: \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 מה הם אומרים? \u0003דבורים לחרדל לא מזקי ליה\u0004 \u0005[מזיקות אותו],\u0006 \u0003אי בבינתא\u0004 \u0005[אם בזרע]\u0006 —"],["\u0003לא משכחת ליה\u0004 \u0005[מוצאת אותו],\u0006 \u0003אי בטרפא\u0004 \u0005[אם בעלה]\u0006 — הרי הוא \u0003הדר פארי\u0004 \u0005[חוזר וגדל].\u0006","שנינו במשנה ש\u0003לא\u0004 יעמיד את \u0003נברכת הכובסין\u0004 ליד כותל חבירו אלא אם הרחיק שלושה טפחים. \u0003אמר רב נחמן אמר רבה בר אבוה: לא שנו אלא מן המחמצן,\u0004 שהיא כעין בריכה ששורים בה את הבגדים המתכבסים למשך זמן מסויים, \u0003אבל מן הנדיין,\u0004 שהיא בריכה שמשפשפים בה את הבגדים המתכבסים — \u0003ארבע אמות.\u0004 ומעירים: \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003נברכת הכובסין\u0004 — צריך שירחיק מכותל חבירו \u0003ארבע אמות,\u0004 ולכאורה יש לתמוה: \u0003והא אנן תנן\u0004 \u0005[והרי אנו שנינו\u0006 במשנה\u0005]\u0006 שמרחיק רק \u0003שלשה טפחים! אלא לאו שמע מינה\u0004 \u0005[האם לא תלמד מכאן]\u0006 \u0003כ\u0004דברי \u0003רב נחמן.\u0004","\u0003ואיכא דרמי להו מירמי\u0004 \u0005[ויש שמשליכים אותם\u0006 את המשנה והברייתא הללו \u0005כסתירה],\u0006 \u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003נברכת הכובסין\u0004 יש להרחיקה מן הכותל \u0003שלשה טפחים, והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 שיש להרחיקה \u0003ארבע אמות!\u0004 על כך \u0003אמר רב נחמן אמר רבה בר אבוה, לא קשיא\u0004 \u0005[אינו קשה]:\u0006 \u0003כאן מן המחמצן\u0004 מרחיק שלושה טפחים, \u0003כאן מן הנדיין\u0004 מרחיק ארבע אמות. \u0003רב חייא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אויא: מתני לה בהדיא\u0004 \u0005[היה שונה אותה במפורש\u0006 כך\u0005],\u0006 \u0003אלא אם כן הרחיק משפת מחמצן ולכותל שלשה טפחים.\u0004","שנינו במשנה שהחופר בור וכו' מרחיק שלושה טפחים \u0003וסד בסיד. איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]\u0006 מהו הנוסח המדוייק במשנתנו: האם \u0003\"וסד בסיד\" תנן\u0004 \u0005[שנינו]\u0006, שנוסף להרחקה צריך גם לטוח את הדפנות בסיד, \u0003או דילמא\u0004 \u0005[שמא]\u0006 \u0003\"או סד בסיד\" תנן\u0004 \u0005[שנינו],\u0006 שבמקום להרחיק יכול לסוד בסיד?","ומשיבים: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 ש\u0003\"וסד בסיד\" תנן\u0004 \u0005[שנינו],\u0006 \u0003דאי סלקא דעתך\u0004 \u0005[שאם עולה על דעתך\u0006 לומר\u0005]\u0006 ש\u0003\"או סד בסיד\" תנן\u0004 \u0005[שנינו],\u0006 כמו בחלקה השני של המשנה העוסק בגפת וכו', \u0003אם כן ליערבינהו וליתנינהו\u0004 \u0005[שיערב וישנה אותם],\u0006 את כל המקרים שבמשנה יחד, שהרי לפי גרסה זו הדין שווה בכולם!","ומשיבים: זו אינה הוכחה, \u0003דילמא\u0004 \u0005[שמא]\u0006 \u0003משום דלא דמי האי היזיקא להאי היזיקא\u0004 \u0005[שאינו דומה היזק זה להיזק זה]\u0006 הפרידה אותם המשנה, שהרי \u0003רישא\u0004 \u0005[\u0006ב\u0005תחילת\u0006 המשנה\u0005]\u0006 מדובר ב\u0003היזיקא דמתונא\u0004 \u0005[היזק של לחות]\u0006 ואילו \u0003סיפא\u0004 \u0005[\u0006ב\u0005סוף]\u0006 מדובר ב\u0003היזיקא דהבלא\u0004 \u0005[היזק של חום].\u0006","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר ממה ששנינו בברייתא, \u0003ר' יהודה אומר: סלע הבא בידים\u0004 שהוא רך ואינו צריך לחציבה — \u0003זה חופר בורו מכאן\u0004 בחלקתו שלו, \u0003וזה חופר בורו מכאן, זה מרחיק שלשה טפחים וסד בסיד, וזה מרחיק שלשה טפחים וסד בסיד.\u0004 ונדייק: \u0003טעמא\u0004 \u0005[הטעם\u0006 דווקא\u0005]\u0006 בסלע ש\u0003בא בידים\u0004 צריך גם לסוד בסיד, \u0003הא\u0004 \u0005[הרי\u0006 אם\u0005]\u0006 \u0003לא בא בידים\u0004 — \u0003לא,\u0004 אינו צריך לסוד בסיד!","ומשיבים: יש לומר כי \u0003הוא הדין דאף על גב\u0004 \u0005[שאף על פי]\u0006 ש\u0003לא בא בידים נמי\u0004 \u0005[גם כן]\u0006 \u0003סד בסיד, ובא בידים איצטריכא ליה\u0004 \u0005[נצרך לו\u0006 להיאמר\u0005],\u0006 שכן \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006 \u0003כיון\u0004 ש\u0003בא בידים ליבעי רווחא טפי\u0004 \u0005[\u0006ש\u0005יצטרך רווח\u0006 מרחק גדול \u0005יותר],\u0006 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין צורך בכך.","שנינו במשנה ש\u0003מרחיקין את הגפת ואת הזבל ואת המלח ואת הסלעים\u0004 מכותלו של חבירו שלושה טפחים או סד בסיד. \u0003תנן התם\u0004 \u0005[שנינו שם]\u0006 במשנה במסכת שבת: \u0003במה טומנין\u0004 אוכל לשבת \u0003ובמה אין טומנין?\u0004","ואמרו ש\u0003אין טומנין לא בגפת ולא בזבל ולא במלח, ולא בסיד ולא בחול, בין\u0004 שהם \u0003לחין בין\u0004 שהם \u0003יבשין,\u0004 מפני שהם מתחממים מעצמם ומעלים את החום הקיים. ושואלים: \u0003מאי שנא הכא דקתני\u0004 \u0005[\u0006ב\u0005מה שונה כאן ששנה]\u0006 \u0003סלעים ולא קתני\u0004 \u0005[שנה]\u0006 \u0003חול, ומאי שנא התם דקתני\u0004 \u0005[ומה שונה שם ששנה]\u0006 \u0003חול ולא קתני\u0004 \u0005[שנה]\u0006 \u0003סלעים?\u0004","\u0003אמר רב יוסף:\u0004 ענין זה לפי המציאות הוא, שם לא שנינו סלעים \u0003לפי שאין דרכן של בני אדם להטמין בסלעים. אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: וכי דרכן של בני אדם להטמין\u0004 אוכל \u0003בגיזי צמר ולשונות של ארגמן? דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003טומנין בגיזי צמר\u0004 (צמר גזוז) \u0003ובציפי צמר\u0004 (פקעות צמר מעובד, אך לא טווי), \u0003ובלשונות של ארגמן, ובמוכין\u0004 (סמרטוטים), \u0003ואין מטלטלין\u0004 \u0003אותן\u0004 עצמן בשבת משום מוקצה!","\u0003אלא אמר אביי:\u0004 יש לומר כאן כמליצת הכתוב \u0003\"יגיד עליו רעו\"\u0004 (איוב לו, לג), שמזכיר דבר אחד והוא הדין לחבירו, \u0003תנא הכא\u0004 \u0005[שנה כאן]\u0006 \u0003סלעים והוא הדין לחול, תנא התם\u0004 \u0005[שנה שם]\u0006 \u0003חול והוא הדין לסלעים. אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: אי\u0004 \u0005[אם]\u0006 אתה מפרש זאת בסגנון של \u0003\"יגיד עליו רעו\", ליתנינהו לכולהו בחדא\u0004 \u0005[שישנה את כולם ב\u0006מקום \u0005אחד],\u0006 \u0003וליתני חדא מנייהו באידך\u0004 \u0005[וישנה\u0006 רק \u0005אחד מהם ב\u0006מקום \u0005אחר]\u0006 \u0003ו\u0004נאמר ש\u0003הוא הדין לאידך\u0004 \u0005[לאחרים]!\u0006","\u0003אלא אמר רבא: התם היינו טעמא\u0004 \u0005[שם זהו הטעם]\u0006 ש\u0003לא קתני\u0004 \u0005[שנה]\u0006 \u0003סלעים, משום דמשתכי לה\u0004 \u0005[שהם שוברים,\u0006 שורטים \u0005אותה],\u0006 את ה\u0003קדרה\u0004 ולכן אין דרך בני אדם לטמון בהם כלל, \u0003הכא היינו טעמא\u0004 \u0005[כאן זהו הטעם]\u0006 ש\u0003לא קתני\u0004 \u0005[שנה]\u0006 \u0003חול, משום דמחמימי חיים ומקרירי קריר\u0004 \u0005[שמ\u0006 דברים \u0005חמים\u0006 הוא \u0005מתחמם ומ\u0006דברים \u0005קרים\u0006 הוא \u0005מתקרר]\u0006 והוא עצמו אינו גורם נזק לכותל.","ומקשים: \u0003והא תני\u0004 \u0005[והרי שנה]\u0006 \u0003ר' אושעיא\u0004 בברייתא שלו שמרחיקים גם \u0003חול!\u0004 ומשיבים: \u0003התם במתונא\u0004 \u0005[שם\u0006 מדובר \u0005ב\u0006חול \u0005רטוב]\u0006 וטעם ההרחקה שם הוא בגלל רטיבות. ושואלים: \u0003תנא דידן נמי ליתני ולוקמיה במתונא\u0004 \u0005[התנא שלנו גם כן שישנה\u0006 חול \u0005ונעמיד זאת ב\u0006חול \u0005רטוב]!\u0006 ומשיבים: \u0003הא תנא ליה\u0004 \u0005[הרי\u0006 כבר \u0005שנה]\u0006 \u0003אמת המים\u0004 שגורמת לרטיבות, ומשום כך אין צורך גם לשנות חול רטוב.","ודוחים: זו אינה תשובה, \u0003אטו מי לא קתני\u0004 \u0005[האם אינו שונה]\u0006 \u0003אמת המים וקתני\u0004 \u0005[ושונה]\u0006 גם \u0003נברכת הכובסין?\u0004 משמע שמפרט את כל הפרטים המצויים, ואם כן, היה צריך לשנות גם חול!","ומשיבים: \u0003הנהו צריכי\u0004 \u0005[אלה צריכים],\u0006 \u0003דאי תנא\u0004 \u0005[שאם היה שונה]\u0006 רק \u0003אמת המים\u0004 היינו אומרים שצריך להרחיקה \u0003משום דקביעא\u0004 \u0005[ש\u0006היא \u0005קבועה],\u0006 שעוברים בה מים תמיד, \u0003אבל נברכת הכובסין\u0004 ש\u0003לא קביעא\u0004 \u0005[קבועה]\u0006 ופעמים יש בה ופעמים אין בה מים — \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא.\u0004 ולהיפך: \u0003ואי תנא\u0004 \u0005[ואם היה שונה]\u0006 \u0003נברכת הכובסין\u0004 — הייתי אומר שצריך להרחיק \u0003משום דקוו וקיימי\u0004 \u0005[שקבועים ועומדים]\u0006 המים במקום אחד ומחלחלים, \u0003אבל אמת המים\u0004 — \u0003לא,\u0004 לכן \u0003צריכא\u0004 \u0005[נצרכה\u0006 לומר\u0005].\u0006 אבל חול אין צורך להזכיר.","שנינו במשנה ש\u0003מרחיקין את הזרעים ואת המחרישה וכו',\u0004 שאין חורשים ולא זורעים בתוך שלושה טפחים לכותל. ותוהים: מדוע היה צריך לשנות \u0003זרעים? תיפוק ליה\u0004 \u0005[תצא לו]\u0006 הלכה זו של הרחקה \u0003משום מחרישה,\u0004 שהרי צריך תחילה לחרוש כדי לזרוע! ומשיבים: מדובר כאן בזריעה \u0003ב\u0004אופן של \u0003מפולת יד,\u0004 שזורע בלי חרישה.","ועוד שואלים: שנה \u0003מחרישה, ותיפוק ליה\u0004 \u0005[ותצא לו]\u0006 הלכה זו של הרחקה \u0003משום זרעים,\u0004 שהרי חרישה היא רק הכנה לזריעה! ומשיבים: מדובר שם \u0003בחורש לאילנות.\u0004 ומקשים: \u0003ותיפוק ליה\u0004 \u0005[ותצא לו]\u0006 \u0003משום מיא\u0004 \u0005[מים],\u0006 שהרי אם יש שם אילנות צריכים להעביר תעלת מים להשקותם, ומטעם זה יהא אסור! ומשיבים: \u0003תנא בארץ ישראל קאי\u0004 \u0005[עומד,\u0006 נמצא\u0005],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בה: \u0003\"למטר השמים תשתה מים\"\u0004 (דברים יא, יא) ואין עושים שם תעלות לצורך השקייה.","ושואלים: \u0003למימרא\u0004 \u0005[האם לומר,\u0006 ללמוד מכאן\u0005]\u0006 ש\u0003זרעים\u0004"],["\u0003לצדדין קא משתרשי\u0004 \u0005[הם משתרשים],\u0006 שהשורשים צומחים לצדדים ומשום כך מזיקים לכותל? \u0003והא תנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003המבריך את הגפן בארץ,\u0004 שמכופף ענף מן הגפן ומכניסו לאדמה כדי שיגדל שורשים ותצמח גפן חדשה, \u0003אם אין על גבה עפר שלשה טפחים\u0004 — \u0003לא יביא זרע עליה,\u0004 שיש בכך מעין כלאים,","\u0003ותני עלה\u0004 \u0005[ושנינו על\u0006 משנה \u0005זו]:\u0006 \u0003אבל זורע את הצדדין\u0004 מצדדיה של אותה הברכה \u0003אילך ואילך.\u0004 משמע שאין חוששים ששורשי הזרעים יתפשטו לצדדים, ומדוע חוששים כאן? \u0003אמר ר' חגא בשם ר' יוסי:\u0004 הטעם כאן הוא לא משום שהשורשים מתפשטים הצידה ומגיעים לכותל, אלא \u0003מפני שמחלידין\u0004 (מחוררים) \u0003את הקרקע ומעלין עפר תיחוח\u0004 (רך), ועל ידי זה ניזק יסודו של הכותל.","שנינו במשנה: מרחיקים \u0003את מי רגלים מן הכותל\u0004 — \u0003שלשה טפחים וכו'.\u0004 ובענין זה מביאים את מה ש\u0003אמר רבה בר בר חנה: מותר לאדם להשתין מים בצד כותלו של חבירו, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"והכרתי לאחאב משתין בקיר ועצור ועזוב בישראל\"\u0004 (מלכים א' כא, כא), ומכאן למדים שכך דרכו של עולם. ומקשים: \u0003והא אנן תנן\u0004 \u0005[והרי אנו שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003ו\u0004מרחיקים \u0003את מי רגלים מן הכותל\u0004 — \u0003שלשה טפחים!\u0004 ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 מדובר \u0003ב\u0004מי \u0003שופכין,\u0004 לא בהטלת מי רגלים עצמה, אלא במי שלוקח כלי של מי רגלים ושופך שם.","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו: \u0003לא ישפוך אדם מים בצד כותלו של חבירו\u0004 — \u0003אלא אם כן הרחיק ממנו שלשה טפחים\u0004 משמע ששפיכת מים בלבד אסורה, וכל שכן להשתין! ומשיבים: \u0003התם נמי\u0004 \u0005[שם גם כן]\u0006 מדובר \u0003ב\u0004מי \u0003שופכין\u0004 ולא בסתם מים.","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה נוספת ממה ששנינו: \u0003לא ישתין אדם מים בצד כותלו של חבירו\u0004 — \u0003אלא אם כן הרחיק ממנו שלשה טפחים; במה דברים אמורים\u0004 — \u0003בכותל לבינים, אבל בכותל אבנים\u0004 — צריך להרחיק \u0003בכדי שלא יזיק, וכמה\u0004 ירחיק? — כדי \u0003טפח, ושל צונמא,\u0004 אם היה שם סלע קשה מאד — \u0003מותר\u0004 להשתין שם. ואם כן משיטת ברייתא זו \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 ל\u0003רבה בר בר חנה\u0004 האומר כי \u0003מותר להשתין בצד כותלו של חבירו בלא כל הרחקה!\u0004 ומסכמים: אכן \u0003תיובתא\u0004 \u0005[קושיה חמורה\u0006 היא\u0005]\u0006 ובטלו דבריו.","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003רבה בר בר חנה קרא קאמר\u0004 \u0005[מקרא אמר]\u0006 כטעם לדבריו! ומשיבים: \u0003התם הכי קאמר\u0004 \u0005[שם\u0006 במקרא \u0005כך\u0006 הוא \u0005אומר],\u0006 כך כוונת הדברים: \u0003אפילו מידי דדרכיה לאישתוני\u0004 \u0005[דבר שדרכו להשתין]\u0006 \u0003בקיר לא שביקנא ליה\u0004 \u0005[אינני מניח לו],\u0006 \u0003ומאי ניהו\u0004 \u0005[ומיהו זה]?\u0006 — \u0003כלבא\u0004 \u0005[כלב],\u0006 כלומר, שאין הכוונה שם כלל לאדם, אלא הכוונה היא לכלב, שאף כלב לא יישאר בבית אחאב.","\u0003אמר ר' טובי בר קיסנא אמר שמואל: רקיק\u0004 (מין עוגה רכה ודקה) \u0003אינו ממעט בחלון,\u0004 שאם הניח אותו בחלון אינו ממעט את שיעורו של החלון לדיני טומאה. ושואלים: \u0003מאי איריא\u0004 \u0005[מה שייך]?\u0006 מדוע דווקא שנה ב\u0003רקיק? אפילו\u0004 לחם \u0003עבה נמי\u0004 \u0005[גם כן]\u0006 איננו ממעט!","ומשיבים: בלשון \u0003לא מיבעיא קאמר\u0004 \u0005[נצרכה אמר],\u0006 ובאופן הבא: \u0003לא מיבעיא\u0004 \u0005[נצרכה\u0006 לומר\u0005]\u0006 בלחם \u0003עבה, כיון דאיחזי ליה\u0004 \u0005[שראוי לו]\u0006 ויכול להשתמש בו \u0003לא מבטיל ליה\u0004 \u0005[מבטל אותו],\u0006 \u0003אבל רקיק דממאיס\u0004 \u0005[ש\u0006הוא \u0005נמאס]\u0006 ומתלכלך בקלות — \u0003אימא בטולי מבטיל ליה\u0004 \u0005[אמור\u0006 ש\u0005מבטל אותו],\u0006 ונעשה כחלק מן הבית, וממעט את שיעור הפתח, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאפילו זה אינו מתבטל. שכל שראוי לשימוש כלשהו, כגון ליתנו לבהמתו שאינה מואסת בו, ויתכן שיקחנו משם — אינו מהווה חלק מן המקום בו הוא נמצא.","ושואלים: \u0003ותיפוק ליה דהוה ליה\u0004 \u0005[ותצא לו\u0006 הלכה זו מצד אחר, \u0005שכן\u0006 רקיק זה \u0005הריהו]\u0006 \u0003דבר שהוא מקבל טומאה, וכל דבר שהוא מקבל טומאה\u0004 — \u0003אינו חוצץ בפני הטומאה!\u0004 ומשיבים: מדובר שם ברקיק \u0003שנילש במי פירות,\u0004 שכיון שלא נילוש באחד מהמשקים המכשירים אותו לקבל טומאה — אינו מקבל טומאה. ומטעם זה בלבד — היה חוצץ וממעט.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על שיטת שמואל ממה ששנינו: \u0003קופה\u0004 (סל) \u0003מלאה תבן, ו\u0004כן \u0003חבית\u0004 של חרס \u0003מלאה גרוגרות המונחים בחלון\u0004 — \u0003רואין, כל שאילו ינטלו\u0004 הקופה או החבית \u0003ויכולין תבן וגרוגרות לעמוד בפני עצמן\u0004 — הרי הם \u0003חוצצין, ואם לאו\u0004 — \u0003אין חוצצין.\u0004 ויש לשאול: מדוע חוצצים? \u0003והא\u0004 \u0005[והרי]\u0006 \u0003תבן\u0004 אף שיכול לעמוד בפני עצמו הריהו \u0003חזי\u0004 \u0005[ראוי]\u0006 \u0003לבהמתו,\u0004 ומן הסתם יקח אותו משם, ואינו בטל במקומו!","ומשיבים: מדובר \u0003בסריא\u0004 \u0005[ב\u0006תבן \u0005שהסריח]\u0006, שאינו ראוי למאכל בהמה. ושואלים: הרי הוא \u0003חזי לטינא\u0004 \u0005[ראוי לטיט]\u0006 לערבו בטיט ולעשות ממנו לבנים! ומשיבים: \u0003דאית ביה קוצי\u0004 \u0005[שיש בו קוצים]\u0006 ואינו ראוי אף לכך. ואומרים: מכל מקום \u0003חזי\u0004 \u0005[ראוי\u0006 הוא\u0005]\u0006 \u0003להסקה!\u0004 ומשיבים: מדובר \u0003במתונא\u0004 \u0005[ב\u0006תבן \u0005לח].\u0006 ואומרים: עדיין \u0003חזי\u0004 \u0005[ראוי]\u0006 \u0003להסק גדול\u0004 שאם עושה מדורה גדולה, גם תבן לח יתייבש ויהיה ראוי לשריפה! ומשיבים: \u0003הסק גדול לא שכיח\u0004 \u0005[מצוי],\u0006","ולכן מן הסתם משאיר את התבן הזה במקומו. ועוד שואלים: \u0003גרוגרות\u0004 — \u0003הא חזו ליה\u0004 \u0005[הרי ראויות לו]\u0006 ובודאי יקח אותן משם, ואם כן, אינן כקבועות במקום! \u0003אמר שמואל:\u0004 מדובר כאן \u0003בשהתריפו\u0004 (התליעו). \u0003וכן תני\u0004 \u0005[שנה]\u0006 \u0003רבה בר אבוה: בשהתריפו.\u0004","ומעתה מבררים: \u0003האי\u0004 \u0005[אותה]\u0006 \u0003חבית\u0004 שהיו בה תבן וגרוגרות \u0003היכי דמיא\u0004 \u0005[כיצד היתה בדיוק]?\u0006 \u0003אי דפומא לבר\u0004 \u0005[אם שפיה\u0006 פונה \u0005לחוץ],\u0006 לצד שאין המת נמצא בו —"],["\u0003היא\u0004 החבית \u0003גופה תיחוץ\u0004 \u0005[עצמה תחצוץ],\u0006 שכן אינה מקבלת טומאה במקרה כזה, \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003כלי חרש אינו מטמא\u0004 אם הגיעה אליו טומאה \u0003מגבו! אלא\u0004 צריך לומר \u0003דפומא לגאו\u0004 \u0005[שפיה לפנים]\u0006 ומקבלת טומאה מפיה, ונטמאת. \u0003ואי בעית אימא\u0004 \u0005[אם תרצה אמור]:\u0006 \u0003לעולם דפומא לבר\u0004 \u0005[שפיה לחוץ],\u0006 \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003בחבית של מתכת\u0004 שכלי מתכת מקבל טומאה גם מגבו.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 עוד על ההנחה שדבר שראוי לשימוש כלשהו אינו ממעט בחלון (ואף שאינו מקבל טומאה), ממה ששנינו בברייתא על דברים שונים שאינם מקבלים טומאה, שממעטים ושאינם ממעטים בחלון. וכך שנינו: \u0003עשבין שתלשן והניחן בחלון, או שעלו מאליהן בחלונות, ומטלוניות\u0004 (מטליות, חתיכות בד) \u0003שאין בהן שלש\u0004 אצבעות \u0003על שלש\u0004 אצבעות, \u0003והאבר והבשר המדולדלין בבהמה ובחיה, ועוף ששכן בחלון, וגוי שישב בחלון, ובן שמנה,\u0004 תינוק הנולד בחודש השמיני להריון, שמן הסתם אינו בר קיימא, \u0003המונח בחלון, והמלח, וכלי חרס, וספר תורה\u0004 — \u0003כולם ממעטין בחלון\u0004 שאין טומאה עוברת דרך החלון אם לא נשתייר בו מקום פנוי בשיעור טפח על טפח. \u0003אבל השלג, והברד, והגליד, והכפור,\u0004 \u0003והמים\u0004 — \u0003כולן אין ממעטין בחלון.\u0004","ושואלים: לשיטת שמואל, לפיה דבר שראוי לשימוש אינו בטל לחלון, ואינו ממעט, \u0003והא עשבין חזו\u0004 \u0005[והרי עשבים ראויים]\u0006 \u0003לבהמתו\u0004 ומן הסתם יקחם משם, ולפי הברייתא ממעטים! ומשיבים: מדובר \u0003באפרזתא\u0004 (עשב מרעיל) שאינו ראוי לבהמה.","ושואלים עוד מהמשך הברייתא: \u0003או\u0004 עשבים \u0003שעלו מאליהן.\u0004 והרי \u0003כיון דקשו\u0004 \u0005[שקשים]\u0006 ומזיקים \u0003לכותל\u0004 הרי \u0003בוודאי\u0004 \u0003שקיל להו\u0004 \u0005[נוטל\u0006 הוא \u0005אותם]\u0006 ואם כן יש לראותם כנטולים כבר עכשיו! \u0003אמר רבה:\u0004 מדובר \u0003בכותל חורבה\u0004 שאינו חושש לקיומו. \u0003רב פפא אמר: אפילו בכותל יישוב\u0004 — \u0003בבאין חוץ לשלשה לחלון\u0004 שאינם צומחים בחלון עצמו אלא שרשיהם במקום מרוחק והם מגיעים לחלון, ואת אלה אינו מקפיד לעקור.","ועוד שואלים: \u0003מטלוניות\u0004 מדוע הן בטלות? הרי \u0003חזו ליה לקריעה דלבושא\u0004 \u0005[ראויות לו\u0006 לשים טלאי \u0005לקרע שבמלבוש]!\u0006 ומתרצים: מדובר \u0003בסמיכתא\u0004 \u0005[ב\u0006מטליות \u0005עבות],\u0006 שאינן ראויות להטלאה. ושואלים: בכל זאת הרי \u0003חזו לאומנא\u0004 \u0005[ראויות למקיז דם]\u0006 לנגב בה את מקום ההקזה! ומתרצים: \u0003בריסקא\u0004 \u0005[ב\u0006אריג \u0005מחוספס]\u0006 של שקים, ששורט את העור.","ומקשים: \u0003אי בריסקא\u0004 \u0005[אם\u0006 מדובר \u0005במחוספס],\u0006 מדוע אמר \u0003שאין בהן שלש על שלש\u0004 אצבעות, \u0003שאין בהן ארבעה על ארבעה\u0004 טפחים \u0003מיבעי ליה\u0004 \u0005[נצרך היה לו]\u0006 לומר, כי אריג גס כזה שמשמש לשקים ולא לבגד אין מקבל טומאה אלא רק בחתיכה גדולה של ארבעה על ארבעה טפחים! ומתרצים: אין מדובר בשק ממש, אלא \u0003כעין ריסקא\u0004 שהוא אריג רגיל של בגד, אלא שנעשה נוקשה כשק.","ועוד מקשים: שנינו שם \u0003והאבר והבשר המדולדלין בבהמה ובחיה\u0004 ממעטים בחלון, ולשיטת שמואל מדוע אלו ממעטים? הלא \u0003ערקא ואזלא\u0004 \u0005[בורחת והולכת]\u0006 לה הבהמה, ויהו נחשבים כנטולים כבר מעכשיו! ומתרצים: מדובר \u0003ב\u0004בהמה \u0003קשורה.\u0004","ומקשים: והרי \u0003שחיט לה\u0004 \u0005[שוחט אותה]!\u0006 ומתרצים: מדובר \u0003ב\u0004בהמה \u0003טמאה\u0004 שאינו עתיד לשוחטה. ושואלים: אם כך הוא \u0003מזבין לה\u0004 \u0005[מוכר אותה]\u0006 \u0003לגוי!\u0004 ומשיבים: מדובר \u0003בכחושה,\u0004 שאף אחד לא יקנה אותה. וממשיכים לשאול: אף אם את הבהמה אינו מזיז משם, מכל מקום אותה חתיכה מדולדלת יש לה שימוש, שכן \u0003פסיק שדי לה\u0004 \u0005[חותך\u0006 אותה ו\u0005זורק אותה]\u0006 \u0003לכלבים!\u0004 ומשיבים: \u0003כיון דאיכא\u0004 \u0005[שיש\u0006 בכך\u0005]\u0006 \u0003צער בעלי חיים לא עביד\u0004 \u0005[אינו עושה]\u0006 כן לחתוך ממנה.","עוד שנינו שם: \u0003ועוף ששכן בחלון\u0004 ממעט. ומקשים: הלא \u0003פרח ואזיל\u0004 \u0005[פורח,\u0006 עף, \u0005והולך\u0006 לו\u0005]!\u0006 ומתרצים: \u0003בקשור.\u0004 ושואלים עוד: שמא \u0003שחיט ליה\u0004 \u0005[שוחט אותו]!\u0006 ומתרצים: מדובר \u0003ב\u0004עוף \u0003טמא\u0004 שאינו שוחטו. ושואלים: טמא \u0003מזבין ליה\u0004 \u0005[מוכר אותו]\u0006 \u0003לגוי!\u0004 ומשיבים: מדובר \u0003בקלניתא\u0004 (מין עוף) שאין לו קונים מפני שהוא רזה ביותר.","ושואלים: הרי \u0003יהיב ליה לינוקא\u0004 \u0005[נותן אותו לתינוק]\u0006 לשחק ומדוע ממעט! ומשיבים: מדובר \u0003ב\u0004עוף ש\u0003מסרט.\u0004 ושוב שואלים: הרי \u0003קלניתא לא מסרטא\u0004 \u0005[מסרט]!\u0006 ומשיבים: מדובר בסוג עוף כחוש \u0003כעין קלניתא\u0004 שהיה מסרט.","עוד שנינו שם: \u0003וגוי שישב בחלון\u0004 ממעט. ושואלים: \u0003קאי ואזיל\u0004 \u0005[יקום וילך],\u0006 ומדוע ממעט בחלון! ומשיבים: מדובר \u0003בכפות.\u0004 וממשיכים לשאול: \u0003אתי חבריה שרי ליה\u0004 \u0005[יבוא חבירו\u0006 ו\u0005יתיר אותו]!\u0006 ומשיבים: מדובר \u0003במצורע,\u0004 שאחרים חוששים לנגוע בו. ושואלים: \u0003אתי\u0004 \u0005[יבוא]\u0006 \u0003מצורע חבריה שרי ליה\u0004 \u0005[חבירו\u0006 ו\u0005יתיר אותו]!\u0006 \u0003אלא\u0004 מדובר \u0003בחבושי מלכות\u0004 שהיו מונחים שם כעונש, ואותם אין מתירים ומשחררים מפני מורא המלכות.","שנינו שם: ו\u0003בן שמנה המונח בחלון\u0004 ממעט. ושואלים: שמא \u0003אתיא אמיה דריא ליה\u0004 \u0005[תבוא אמו\u0006 ו\u0005תיקח אותו\u0006 משם\u0005]!\u0006 ומשיבים: מדובר שם \u0003בשבת\u0004 שאסור לטלטלו; \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003בן שמנה הרי הוא כאבן,\u0004 לענין איסור מוקצה, \u0003ואסור לטלטלו בשבת, אבל אמו שוחה\u0004 (מתכופפת) \u0003עליו ומניקתו מפני הסכנה\u0004 שיש לה לעצמה, מפני החלב הדוחק אותה.","ועוד שואלים: שנינו שם \u0003מלח,\u0004 הלא \u0003חזיא ליה\u0004 \u0005[הרי ראוי לו\u0006 לשימוש\u0005]\u0006 ועשוי לקחתו משם! ומשיבים: מדובר \u0003במרירתא\u0004 \u0005[במר],\u0006 שיש בו מרירות ואינו ראוי לתיבול. ומשיבים: מכל מקום \u0003חזיא\u0004 \u0005[ראוי]\u0006 הוא לעיבוד \u0003לעורות!\u0004 ומשיבים: מדובר כאן \u0003דאית בה קוצי\u0004 \u0005[שיש בו קוצים]\u0006 ולכן אינו מניח בו עורות.","ומקשים: \u0003כיון דקשיא\u0004 \u0005[ש\u0006הוא \u0005קשה]\u0006 \u0003לכותל\u0004 שהמלח הזה יזיק לכותל, \u0003שקלא\u0004 \u0005[יקח\u0006 אותו\u0005]\u0006 משם! ומשיבים: \u0003דיתבא אחספא\u0004 \u0005[ש\u0006הוא \u0005מונח על\u0006 חתיכת \u0005חרס]\u0006 ולכן אינו מזיק לכותל. ואומרים: אם מונח הוא על החרס \u0003חספא גופא תיחוץ\u0004 \u0005[\u0006חתיכת \u0005החרס עצמה תחצוץ]\u0006 ומדוע צריך להזכיר כאן מלח פה?"],["ומשיבים: מדובר פה באופן \u0003דלית\u0004 \u0005[שאין]\u0006 \u0003בה שיעורא\u0004 \u0005[שיעור],\u0006 ובפחות משיעור אינו נחשב, \u0003כדתנן\u0004 \u0005[כפי ששנינו\u0006 במשנה\u0005]\u0006 שיש שיעור ל\u0003חרס\u0004 לענין הוצאה בשבת, שמתחייב אדם אם הוציאו מרשות היחיד לרשות הרבים ולהיפך — \u0003כדי ליתן בין פצים לחבירו,\u0004 שמניחים חרס ליד המסגרת של החלון שעושים כדי ליישרה, ואם כן חרס פחות משיעור מסויים אינו נחשב כלל.","ועוד שנינו שם: \u0003כלי חרס\u0004 ממעט בחלון. ומקשים: הלא \u0003חזי ליה\u0004 \u0005[ראוי\u0006 הוא \u0005לו]\u0006 לשימוש, ושמא יקחנו משם! ומשיבים: מדובר במקרה \u0003דמיטנף\u0004 \u0005[ש\u0006הוא \u0005מלוכלך].\u0006 ושואלים: \u0003חזי לאומנא\u0004 \u0005[\u0006והרי הוא \u0005ראוי למקיז דם]\u0006 לקבל בתוכו את הדם, שלא איכפת לו בזה! ומשיבים: \u0003דמנקב\u0004 \u0005[ש\u0006הוא \u0005מנוקב]\u0006 ולכן אינו ראוי לשימוש.","ועוד אמרו שם ש\u0003ספר תורה\u0004 ממעט בחלון. ומקשים: הלא \u0003חזי למקרא\u0004 \u0005[ראוי\u0006 הוא \u0005לקרוא\u0006 בו\u0005]\u0006 ושמא יקחנו משם! ומשיבים: מדובר \u0003בבלוי\u0004 שאינו ראוי עוד לקרוא בו. ומקשים: \u0003והא בעי\u0004 \u0005[והרי צריך]\u0006 ספר זה \u0003גניזה,\u0004 ובודאי יטלנו לגונזו! ומשיבים: באומר \u0003שם תהא גניזתה.\u0004 כלומר, שהניחו בחלון כדי שישאר שם.","\u0003ו\u0004בענין המלח שהוזכר לעיל מביאים מה ש\u0003אמר רב: בכל עושין מחיצה,\u0004 לצורך הגדרת רשות היחיד בשבת, או לחצוץ בפני טומאה, \u0003חוץ ממלח ורבב\u0004 (שומן), משום שהמלח מתפורר, והשומן נמס בחום. \u0003ושמואל אמר: אפילו מלח\u0004 עושים בו מחיצה. \u0003אמר רב פפא, ולא פליגי\u0004 \u0005[נחלקו],\u0006 כי \u0003הא\u0004 \u0005[זה]\u0006 שאמר שמואל שאפשר לעשות מחיצה במלח, הרי זה \u0003במלח סדומית\u0004 שהוא כאבן, ואפשר לעשות בו מחיצה, \u0003הא\u0004 \u0005[זה]\u0006 שאמר רב שאין עושים מחיצה ממלח, הרי זה \u0003במלח איסתרוקנית\u0004 שעושים ממי הים, שהוא גרגרים גרגרים.","ומוסיפים: \u0003והשתא\u0004 \u0005[ועכשיו]\u0006 ש\u0003אמר רבה: עושה אדם שני צבורי\u0004 (ערימות) \u0003מלח\u0004 בפתח מבוי \u0003ומניח עליהם קורה, שהמלח מעמדת את הקורה והקורה מעמדת את המלח,\u0004 שמכבידה עליו ומהדקת אותו, ויכול להשתמש באלה לשם קורה המתירה טלטול במבוי בשבת, לפי זה אפשר לומר כי \u0003אפילו\u0004 ב\u0003מלח איסתרוקנית\u0004 אפשר לעשות מחיצה, \u0003ו\u0004\u0003לא פליגי\u0004 \u0005[נחלקו]\u0006 רב ושמואל: \u0003הא דאיכא\u0004 \u0005[זה שיש]\u0006 \u0003קורה\u0004 שמכבידה עליו, \u0003הא דליכא\u0004 \u0005[זה שאין]\u0006 \u0003קורה.\u0004","שנינו במשנה ש\u0003מרחיקין את הריחים שלשה\u0004 טפחים \u0003מן השכב, שהן ארבעה\u0004 טפחים \u0003מן הרכב וכו'.\u0004 ואומרים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 מרחיקים את הריחיים? — \u0003משום טיריא\u0004 \u0005[התנודה],\u0006 הזעזוע שהם גורמים. ושואלים: \u0003והא תניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ו\u0004שיעור ההרחקה בריחיים \u0003של חמור\u0004 (מבנה שהריחיים מונחים עליו) — \u0003שלשה מן האיסטרוביל\u0004 (החלק התחתון של הריחיים) \u0003שהן ארבעה מן הקלת\u0004 (האפרכסת ששופכים בה התבואה); \u0003התם מאי טיריא איכא\u0004 \u0005[שם מה זעזוע יש\u0006 בזה\u0005]?\u0006 \u0003אלא\u0004 יש לפרש שסיבת ההרחקה היא \u0003משום קלא\u0004 \u0005[הקול]\u0006 שגורם נזק לכותל.","שנינו במשנה: \u0003ו\u0004מרחיקים \u0003את התנור\u0004 מן הכותל — \u0003שלשה\u0004 טפחים \u0003מן הכליא\u0004 החלק הבולט שבו, \u0003שהן ארבעה מן השפה. אמר אביי, שמע מינה\u0004 \u0005[למד מכאן]\u0006 ש\u0003כליא\u0004 של \u0003תנור\u0004 הוא ברוחב \u0003טפח\u0004 יותר משפתו. \u0003נפקא מינה\u0004 \u0005[יוצא מכאן]\u0006 לימוד להלכה \u0003ל\u0004ענין \u0003מקח וממכר.\u0004 שכך צריך להיות, ובפחות מכאן אינו תנור ראוי.","\u0003לא יעמיד אדם תנור בתוך הבית, אלא אם כן יש על גביו גובה ארבע אמות\u0004 עד תקרת הבית, כדי שלא יגרום לשריפה. \u0003היה מעמידו בעלייה\u0004 (קומה עליונה) — \u0003צריך שיהא תחתיו מעזיבה\u0004 (כיסוי טיט) על הרצפה שהיא תקרת הקומה הראשונה, בעובי \u0003שלשה טפחים\u0004 לפחות, שלא תישרף התיקרה שתחתיו. \u0003ובכירה\u0004 צריך מתחתיה מעזיבה בעובי \u0003טפח\u0004 לפחות;","\u0003ואם הזיק\u0004 בכל זאת — \u0003משלם מה שהזיק. ר' שמעון אומר: לא אמרו כל השיעורין האלו, אלא שאם הזיק\u0004 — \u0003פטור מלשלם,\u0004 שהרי נקט בכל אמצעי הזהירות הדרושים.","הלכה אחרת היא: \u0003לא יפתח אדם חנות של נחתומין\u0004 (אופים) \u0003ושל צבעין תחת אוצרו\u0004 (מחסנו) \u0003של חבירו, ולא\u0004 יעשה \u0003רפת בקר,\u0004 שכל אלה: החום, העשן, או הריח העולה מהם מזיק לדברים שבאוצר. ומעירים: \u0003באמת\u0004 ההלכה היא, ש\u0003ב\u0004אוצר של \u0003יין\u0004 — התירו לעשות תחתיו חנות של נחתומים ושל צבעים משום שאין החום שהם גורמים מזיק ליין, \u0003אבל לא רפת בקר\u0004 שריחה רע ומזיק ליין.","על דברי המשנה בענין העמדה של תנור וכירה בעליה שואלים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003בתנור\u0004 שבעליה צריך שיהיו תחתיו \u0003ארבעה\u0004 טפחים מעזיבה, \u0003ובכירה שלשה! אמר אביי: כי תניא ההיא\u0004 \u0005[כאשר שנויה שם]\u0006 הרי זה \u0003ב\u0004של \u0003נחתומין,\u0004 שכיון שאופים כל היום מתחממים מתקני האפיה הרבה יותר, ש\u0003תנור דידן כי\u0004 \u0005[\u0006של המשנה \u0005שלנו\u0006 הוא \u0005כמו]\u0006 \u0003כירה\u0004 של \u0003נחתומין,\u0004 ותנור של נחתומים צריך הפסק גדול יותר.","שנינו: \u0003לא יפתח חנות\u0004 של נחתומים ושל צבעים תחת אוצרו של חבירו. ועל כך \u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003אם היתה רפת קודמת לאוצר\u0004 — \u0003מותר,\u0004 ואין בעל הרפת צריך להרחיק משם. ובפרטי דבר זה \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003אביי:\u0004 אם \u0003כיבד\u0004 (ניקה) \u0003וריבץ,\u0004 כלומר, הכשיר והכין אותו \u0003ל\u0004צורך \u0003אוצר,\u0004 ועדיין לא הניח בו את הדברים \u0003מהו?\u0004 האם אומרים שנחשב שיש במקום כבר אוצר ואין אחרים עושים רפת שם, או שמא כל עוד אין אוצר מצוי שם אינו יכול לעכב בידי אחרים?","וכן, אם \u0003ריבה בחלונות\u0004 לשם איוורור, שמראה שכוונתו לעשות שם אוצר, \u0003מהו?\u0004 וכן אם עשה \u0003אכסדרה תחת האוצר, מהו?\u0004 וכן אם \u0003בנה עלייה על גבי ביתו\u0004 לצורך איחסון, \u0003מהו?\u0004 אף אחת מן השאלות הללו לא נפתרה ועל כן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה. ומביאים כי מעין שאלות אלו \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע:\u0004 אם הניח שם \u0003תמרי ורמוני\u0004 \u0005[תמרים ורימונים],\u0006 \u0003מאי\u0004 \u0005[מה]\u0006 יהא הדין? האם נחשב זה כהתחלה של אוצר, או לא? אף שאלה זו לא נפתרה ועל כן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","שנינו: \u0003באמת, ביין התירו\u0004 לעשות תחתיו חנות של נחתומים או צבעים, אבל לא רפת בקר. ובהסבר דבר זה \u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003ביין התירו מפני שמשביחו\u0004 החום והעשן, \u0003ו\u0004אולם \u0003לא רפת בקר, מפני שמסריחו\u0004 ריח הרפת. \u0003אמר רב יוסף: האי דידן\u0004 \u0005[זה\u0006 היין \u0005שלנו]\u0006 ממהר יותר להתקלקל, ולכן \u0003אפילו קוטרא דשרגא נמי קשיא ליה\u0004 \u0005[עשן של נר גם כן קשה לו,\u0006 ומזיק לו\u0005].\u0006 \u0003אמר רב ששת: ואספסתא\u0004 \u0005[ואספסת,\u0006 שחת של תבואה\u0005]\u0006 \u0003כרפת בקר דמיא\u0004 \u0005[נחשבת]\u0006 מפני שבמשך הזמן היא נרקבת ויוצרת סרחון.","אם רוצה אחד הדיירים לפתוח \u0003חנות שבחצר\u0004 — \u0003יכול\u0004 השכן שבחצר \u0003למחות בידו\u0004 מלעשות כן \u0003ולומר לו: איני יכול לישן מקול הנכנסין ומקול היוצאין\u0004 לחנות; \u0003אבל עושה\u0004 אדם בתוך ביתו \u0003כלים, יוצא ומוכר\u0004 אותם \u0003בתוך השוק,\u0004 אף על פי שאינו רשאי לעשות בחצרו חנות, \u0003ואינו יכול\u0004 השכן \u0003למחות בידו ולומר לו: איני יכול לישן לא מקול הפטיש\u0004 שאתה עושה בו כלים, \u0003ולא מקול הריחים\u0004 שאתה טוחן בהם, \u0003ולא מקול התינוקות,\u0004 שכל אחד רשאי לעשות בדירתו מה שירצה.","ושואלים: \u0003מאי שנא רישא\u0004 \u0005[מה שונה\u0006 ב\u0005ראש,\u0006 בתחילה\u0005]\u0006 שנאמר שיכול לעכב בעדו מלפתוח חנות, ולומר לו שאינו יכול לישון בגלל קול הנכנסים, \u0003ומאי שנא סיפא\u0004 \u0005[ומה שונה הסוף]\u0006 שאינו יכול לטעון שאינו יכול לישון מפני התינוקות? \u0003אמר אביי: סיפא אתאן\u0004 \u0005[\u0006ב\u0005סוף באנו\u0006 אנו עוסקים\u0005]\u0006 במי שעושה ב\u0003חצר אחרת,\u0004 שאינו יכול לעכב על בן חצר אחרת, אף שהוא בן אותו מבוי. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: אי הכי\u0004 \u0005[אם כך]\u0006 \u0003ליתני\u0004 \u0005[שישנה]:\u0006 \u0003חצר אחרת\u0004 — \u0003מותר,\u0004 ומדוע אמר בלשון זו? \u0003אלא אמר רבא:\u0004"],["\u0003סיפא אתאן\u0004 \u0005[\u0006ב\u0005סוף באנו]\u0006 \u0003לתינוקות של בית רבן\u0004 הבאים ללמוד תורה בביתו, \u0003ומתקנת יהושע בן גמלא ואילך.\u0004 ומה עניינה של תקנה זו?","— ש\u0003אמר רב יהודה אמר רב: ברם\u0004 (אכן) \u0003זכור אותו האיש לטוב ויהושע בן גמלא שמו, שאלמלא הוא נשתכח תורה מישראל; שבתחלה, מי שיש לו אב\u0004 — היה האב \u0003מלמדו תורה, מי שאין לו אב\u0004 — \u0003לא היה למד תורה\u0004 כלל. ומסבירים: \u0003מאי דרוש\u0004 \u0005[מה דרשו]\u0006 שבגלל זה נהגו כך? — את הציווי \u0003\"ולמדתם אתם\u0004 את בניכם\u0003\"\u0004 (דברים יא, יט) הסבירו שכוונתו \u0003\"ולמדתם אתם\",\u0004 שאתם, ההורים עצמם — תלמדו את בניכם.","אבל כיון שראו חכמים שלא הכל יכלו ללמד את בניהם, ומתמעטת התורה בישראל, \u0003התקינו שיהו מושיבין מלמדי תינוקות בירושלים,\u0004 ומסבירים: \u0003מאי דרוש\u0004 \u0005[מה דרשו]\u0006 שעשו כך? — \u0003\"כי מציון תצא תורה\"\u0004 (ישעיה ב, ג); \u0003ועדיין מי שיש לו אב\u0004 — \u0003היה מעלו\u0004 לירושלים \u0003ומלמדו, מי שאין לו אב\u0004 — \u0003לא היה עולה ולמד, התקינו שיהו מושיבין\u0004 מלמדי תינוקות בעיר אחת \u0003בכל פלך\u0004 (מחוז) \u0003ופלך; ומכניסין אותן\u0004 ללמוד כשהיו \u0003כבן שש עשרה כבן שבע עשרה\u0004 שנים,","\u0003ו\u0004כיון שהיו התלמידים גדולים ולא למדו קודם באופן מסודר, \u0003מי שהיה רבו כועס עליו\u0004 — היה התלמיד \u0003מבעיט בו ויצא,\u0004 שאי אפשר היה להחזיק אותם בכוח בבית הספר. \u0003עד שבא יהושע בן גמלא ותיקן, שיהו מושיבין מלמדי תינוקות בכל מדינה\u0004 (אזור) \u0003ומדינה ובכל עיר ועיר, ומכניסין אותן\u0004 ללמוד כבר כשהם \u0003כבן שש כבן שבע\u0004 שנים. וכיון שתוקנה תקנה זו לצורך הרבים, אין השכנים יכולים למנוע מחכם שילמד תינוקות תורה בחצר.","ובאותו ענין \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב לרב שמואל בר שילת\u0004 שהיה מלמד תינוקות: \u0003עד\u0004 גיל \u0003שית\u0004 \u0005[שש]\u0006 \u0003לא תקביל\u0004 \u0005[תקבל]\u0006 תלמיד ללמדו, משום שהם קטנים מדי וקשה להם הלימוד בקביעות, \u0003מכאן ואילך קביל ואספי ליה כתורא\u0004 \u0005[קבל, ופטם אותו\u0006 בתורה \u0005כשור].\u0006 \u0003ו\u0004עוד \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב לרב שמואל בר שילת: כי מחית לינוקא\u0004 \u0005[כאשר אתה מכה תינוק]\u0006 לצורך לימודו וחינוכו, \u0003לא תימחי\u0004 \u0005[אל תכה אותו]\u0006 \u0003אלא בערקתא דמסנא\u0004 \u0005[ברצועת הסנדל]\u0006 שהיא קטנה ואינה מכאיבה ביותר. ועוד יעץ לו: \u0003דקארי\u0004 \u0005[\u0006מי \u0005שקורא]\u0006 — \u0003קארי\u0004 \u0005[קורא]\u0006 מעצמו, \u0003דלא קארי\u0004 \u0005[\u0006מי \u0005שאינו קורא]\u0006 — \u0003ליהוי צוותא לחבריה\u0004 \u0005[שיהיה חברה לחבירו]\u0006 וילמד על ידי כך לקרוא. ולענין בני חצר המסקנה היא איפוא שמותר לעשות בביתו תלמוד תורה ואין השכנים מעכבים.","\u0003מיתיבי\u0004 \u0005[מקשים\u0006 על כך\u0005]\u0006 ממה ששנינו בברייתא: \u0003אחד מבני חצר שביקש לעשות רופא\u0004 או \u0003אומן\u0004 (מקיז דם) או \u0003גרדי\u0004 (אורג) או \u0003מלמד תינוקות\u0004 — שאר \u0003בני\u0004 ה\u0003חצר מעכבין עליו\u0004 אם הדבר מפריע להם. משמע שגם בלימוד תינוקות בני חצר מעכבים! ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 שיכולים לעכב כשהוא מלמד — \u0003בתינוקות\u0004 של \u0003גוים,\u0004 ובדבר זה שאין בו מצוה — יכולים השאר לעכב מפני הרעש.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 קושיה ממה ששנינו בברייתא נוספת: \u0003שנים שיושבין\u0004 הגרים \u0003בחצר\u0004 אחת, \u0003וביקש אחד מהן לעשות רופא ו\u0004כן \u0003אומן, וגרדי, ומלמד תינוקות\u0004 — \u0003חבירו מעכב\u0004 \u0003עליו\u0004 מלעשות כן! ומשיבים: \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 מדובר \u0003במלמד\u0004 \u0003תינוקות\u0004 של \u0003גוים.\u0004","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 קושיה מברייתא נוספת, ששנינו: \u0003מי שיש לו בית בחצר השותפין\u0004 — \u0003הרי זה לא ישכירנו לא לרופא, ולא לאומן, ולא לגרדי, ולא לסופר יהודי, ולא לסופר ארמאי.\u0004 ואם כן הרי שיכול לעכב עליו אפילו היה סופר (מלמד תינוקות) יהודי! ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]?\u0006 \u0003בסופר מתא\u0004 \u0005[העיר]\u0006 שאינו מלמד תינוקות, אלא כותב שטרות או מכתבים לבני העיר. שבכגון זה, שהיא עבודה שאינה מצוה, ובאים אצלו אנשים רבים — יכולים בני חצר לעכב עליו.","משהוזכרה תקנת יהושע בן גמלא דנים בה, ובענין מלמדי תינוקות בכלל. \u0003אמר רבא: מתקנת יהושע בן גמלא\u0004 שתיקן להושיב מלמדי תינוקות בכל עיר ועיר \u0003ואילך, לא ממטינן ינוקא ממתא למתא\u0004 \u0005[אין מביאים תינוק מעיר לעיר],\u0006 אלא בכל מקום משאירים את התינוקות ללמוד בעירם, \u0003אבל מבי כנישתא לבי כנישתא\u0004 \u0005[מבית כנסת לבית כנסת]\u0006 שבהם היו לומדים — \u0003ממטינן\u0004 \u0005[מביאים\u0006 אותם\u0005],\u0006 \u0003ואי מפסק נהרא\u0004 \u0005[ואם מפסיק הנהר]\u0006 באמצע — \u0003לא ממטינן\u0004 \u0005[אין מביאים],\u0006 שמא יפלו התינוקות בנהר, \u0003ואי איכא תיתורא\u0004 \u0005[ואם יש גשר]\u0006 על הנהר — \u0003ממטינן\u0004 \u0005[מביאים\u0006 אותם\u0005]\u0006 אפילו מעבר לנהר, \u0003ואי איכא גמלא\u0004 \u0005[ואם יש\u0006 רק \u0005גשר צר]\u0006 — \u0003לא ממטינן\u0004 \u0005[אין מביאים].\u0006","\u0003ואמר רבא: סך מקרי דרדקי\u0004 — \u0003עשרין וחמשה ינוקי\u0004 \u0005[הכמות\u0006 המירבית ל\u0005מלמד תינוקות\u0006 אחד היא \u0005עשרים וחמישה תינוקות],\u0006 \u0003ואי איכא חמשין\u0004 \u0005[ואם יש חמישים]\u0006 תינוקות במקום — \u0003מותבינן תרי\u0004 \u0005[מושיבים שני\u0006 מלמדים\u0005]\u0006 שילמדו בנפרד כל אחד עשרים וחמישה, \u0003ואי איכא ארבעין\u0004 \u0005[ואם יש ארבעים]\u0006 — \u0003מוקמינן ריש דוכנא, ומסייעין ליה ממתא\u0004 \u0005[\u0006\u0005מעמידים\u0006 לו \u0005ראש דוכן,\u0006 עוזר, \u0005ומסייעין לו מ\u0006בני \u0005העיר]\u0006 לשלם שכרו של העוזר.","\u0003ואמר רבא: האי מקרי ינוקי דגריס\u0004 \u0005[מלמד תינוקות שגורס],\u0006 \u0003ואיכא אחרינא דגריס טפי מיניה\u0004 \u0005[ויש\u0006 אחר שגורס יותר הלכות \u0005ממנו]\u0006 — \u0003לא מסלקינן ליה\u0004 \u0005[אין מסלקים אותו]\u0006 את המלמד הראשון, \u0003דלמא אתי לאיתרשולי\u0004 \u0005[שמא יבוא\u0006 זה, השני, \u0005להתרשל]\u0006 כיון שאין לו תחרות. \u0003רב דימי מנהרדעא אמר:\u0004 להיפך, \u0003כל שכן דגריס טפי\u0004 \u0005[ש\u0006הוא \u0005גורס\u0006 והוא לומד טוב \u0005יותר]\u0006 כשהוא יודע שהוא נשאר מורה יחיד במקום, כי \u0003קנאת סופרים תרבה חכמה\u0004 וחבירו שסולק ישתדל לדעת יותר, כדי שישכרוהו, ויגרום לשני שלא יתרשל.","\u0003ואמר רבא: הני תרי מקרי דרדקי\u0004 \u0005[שני מלמדי תינוקות],\u0006 \u0003חד גריס ולא דייק\u0004 \u0005[אחד גורס\u0006 הרבה \u0005ואינו מדייק\u0006 בדברים\u0005]\u0006 \u0003וחד דייק ולא גריס\u0004 \u0005[ואחד מדייק ואינו גורס\u0006 הרבה\u0005]\u0006 — \u0003מותבינן ההוא דגריס ולא דייק\u0004 \u0005[מושיבים אנו\u0006 מקבלים ללמד \u0005את ההוא שגורס ואינו מדייק],\u0006 ומדוע? \u0003שבשתא ממילא נפקא\u0004 \u0005[השגיאה מעצמה תצא]\u0006 ואין נזק בכך שילמד בשגיאות. ואילו \u0003רב דימי מנהרדעא אמר: מותבינן דדייק ולא גריס\u0004 \u0005[מושיבים אנו את\u0006 זה \u0005שמדייק ואינו גורס\u0006 הרבה\u0005],\u0006 וזאת משום ש\u0003שבשתא\u0004 \u0005[שגיאה]\u0006 \u0003כיון דעל\u0004 \u0005[שנכנסת]\u0006 — \u0003על\u0004 \u0005[נכנסת]\u0006 ושוב אינה יוצאת.","וראיה לדבר — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"כי ששת חדשים ישב שם יואב וכל ישראל עד הכרית כל זכר באדום\"\u0004 (מלכים א יא, טו), \u0003כי אתא לקמיה\u0004 \u0005[כאשר בא\u0006 יואב \u0005לפני]\u0006 \u0003דוד\u0004 לאחר מעשה, \u0003אמר ליה\u0004 \u0005[לו]\u0006 דוד:"],["\u0003מאי טעמא עבדת הכי\u0004 \u0005[מה טעם עשית כך],\u0006 שהרגת את הזכרים בלבד? \u0003אמר ליה\u0004 \u0005[לו],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"תמחה את זכר עמלק\"\u0004 (דברים כה, יט), כלומר, את זכר עמלק, ועמלק מזרע אדום הוא. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003והא אנן\u0004 \u0005[והרי\u0006 \u0003אנחנו]\u0004 \u0003\"זכר\" קרינן\u0004 \u0005[קראנו]!\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אנא\u0004 \u0005[אני,\u0006 לי\u0005]\u0006 \u0003\"זכר\" אקריון\u0004 \u0005[הקריאו לי].\u0006 \u0003אזל שייליה לרביה\u0004 \u0005[הלך\u0006 יואב ו\u0005שאל את רבו]\u0006 שלימד אותו מקרא, \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003היאך אקריתן\u0004 \u0005[איך הקרית לנו]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003\"זכר\"\u0004 שהוא קרא כראוי, אלא שלא שם לב שתלמידו אינו קורא כראוי.","\u0003שקל ספסירא למיקטליה\u0004 \u0005[נטל\u0006 יואב \u0005חרב להרוג אותו],\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 המלמד: \u0003אמאי\u0004 \u0005[מדוע]\u0006 אתה בא להורגני? \u0003אמר ליה\u0004 \u0005[לו],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ארור עשה מלאכת ה' רמיה\"\u0004 (ירמיהו מח, י), שלימדת שלא כראוי. \u0003אמר ליה\u0004 \u0005[לו]\u0006 המלמד: \u0003שבקיה לההוא גברא דליקום\u0004 \u0005[הנח לאותו אדם שיעמוד]\u0006 \u0003ב\"ארור\"\u0004 זה, ודי בעונש זה ואין צורך להרוג אותי! \u0003אמר ליה\u0004 \u0005[לו],\u0006 \u0003כתיב\u0004 \u0005[נאמר]\u0006 גם: \u0003\"וארור מנע חרבו מדם\"\u0004 (ירמיהו מח, י)! \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]:\u0006 \u0003קטליה\u0004 \u0005[הרגו],\u0006 \u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]:\u0006 \u0003לא קטליה\u0004 \u0005[הרגו].\u0006 ומכל מקום למדים ממקרה זה ששגיאה שלומדים בילדות נשארת למשך כל החיים.","\u0003ואמר רבא: מקרי ינוקא\u0004 \u0005[מלמד תינוקות],\u0006 \u0003שתלא\u0004 \u0005[שותל עצים\u0006 מקצועי\u0005],\u0006 \u0003טבחא\u0004 \u0005[שוחט],\u0006 \u0003ואומנא\u0004 \u0005[ומקיז דם],\u0006 \u0003וסופר מתא\u0004 \u0005[וסופר העיר]\u0006 — \u0003כולן כמותרין ועומדין נינהו\u0004 \u0005[הם].\u0006 לומר שאין צורך להתרות בהם שיעשו מלאכתם כראוי, אלא הרי זה כאילו התרו בהם, ואם עשו דבר שלא כראוי — מותר לסלק אותם מיד מתפקידם. \u0003כללא דמילתא\u0004 \u0005[כללו של דבר]:\u0006 ביחס ל\u0003כל פסידא\u0004 \u0005[הפסד]\u0006 ש\u0003לא הדר\u0004 \u0005[חוזר]\u0006 — \u0003מותרה ועומד הוא.\u0004","\u0003אמר רב הונא: האי בר מבואה דאוקי ריחיא\u0004 \u0005[בן מבוי אחד\u0006 \u0005שהעמיד ריחיים\u0006 במבוי\u0005],\u0006 ומתפרנס על ידי הבאים לטחון בריחיים שלו, \u0003ואתא בר מבואה חבריה וקמוקי גביה\u0004 \u0005[ובא בן המבוי חבירו ומעמיד אצלו\u0006 לידו\u0005]\u0006 ריחיים — \u0003דינא\u0004 \u0005[דין]\u0006 \u0003הוא\u0004 ש\u0003מעכב עילויה\u0004 \u0005[עליו]\u0006 הראשון אם רוצה בכך. \u0003דאמר ליה\u0004 \u0005[שאומר לו]:\u0006 \u0003קא פסקת ליה לחיותי\u0004 \u0005[אתה פוסק את חיותי\u0006 פרנסתי\u0005],\u0006 שהרי אתה לוקח את לקוחותי.","ומציעים: \u0003לימא\u0004 \u0005[\u0006האם \u0005נאמר]\u0006 ש\u0003מסייע ליה\u0004 \u0005[לו]\u0006 לשיטתו מה ששנינו: \u0003מרחיקים מצודת הדג מן הדג,\u0004 כלומר, ממצודה אחרת \u0003כמלא ריצת הדג,\u0004 כלומר, מרחק שממנו מגיעים דגים לאותו מקום. ושאלו: \u0003וכמה\u0004 מרחק זה? \u0003אמר רבה בר רב הונא: עד פרסה\u0004 ומשמע מכאן שצריך להרחיק ממקום שקבע בו חבירו את עבודתו. ומשיבים: מכאן אין הוכחה, אפשר לומר כי \u0003שאני\u0004 \u0005[שונים]\u0006 \u0003דגים, דיהבי סייארא\u0004 \u0005[שנותנים סיור],\u0006 שאחד מהם הולך לפני האחרים, ומורה להם לאן לבוא, ומשום כך כשהם נתקלים במלכודת אחת, שוב לא יבואו לשניה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרבא: לימא\u0004 \u0005[\u0006האם \u0005נאמר]\u0006 על \u0003רב הונא דאמר\u0004 \u0005[ש\u0006הוא \u0005אומר]\u0006 \u0003כ\u0004דעת \u0003ר' יהודה; דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005],\u0006 \u0003ר' יהודה אומר: לא יחלק חנוני קליות ואגוזין לתינוקות, מפני שמרגילן\u0004 בכך לבוא \u0003אצלו, וחכמים מתירין?\u0004 משמע שר' יהודה סבור שכל סוג של תחרות אסור, והוא הדין לריחיים.","ודוחים: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 כשיטת \u0003רבנן\u0004 \u0005[חכמים],\u0006 \u0003עד כאן לא\u0004 שמענו כי \u0003פליגי רבנן עליה\u0004 \u0005[חלוקים חכמים עליו],\u0006 על \u0003ר' יהודה התם\u0004 \u0005[שם]\u0006 \u0003אלא דאמר ליה\u0004 \u0005[שיכול לומר לו]\u0006 החנווני לחבירו: שנינו נמצאים כאן ברשות, \u0003אנא קמפלגינא אמגוזי, את פלוג שיוסקי\u0004 \u0005[אני מחלק אגוזים, אתה חלק שקדים],\u0006 \u0003אבל הכא\u0004 \u0005[כאן]\u0006 בבן מבוי שהעמיד גם הוא ריחיים במבוי, \u0003אפילו רבנן מודו\u0004 \u0005[חכמים מודים],\u0006 \u0003דאמר ליה\u0004 \u0005[שאומר לו]:\u0006 \u0003קא פסקת ליה לחיותי\u0004 \u0005[אתה פוסק את חיותי,\u0006 פרנסתי\u0005],\u0006 שכל הצריך — אצלי בא לטחון.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו: \u0003עושה אדם חנות בצד חנותו של חבירו, ומרחץ בצד מרחצו של חבירו, ואינו יכול למחות בידו, מפני שיכול לומר לו: אתה עושה בתוך שלך ואני עושה בתוך שלי!\u0004","ומשיבים: ענין זה כולו \u0003תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא; דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003כופין בני מבואות זה את זה שלא להושיב ביניהן\u0004 באותו מבוי \u0003לא חייט ולא בורסקי, ולא מלמד תינוקות, ולא אחד מבני בעלי אומניות,\u0004 כלומר, הם יכולים לקבוע ביניהם שאינם רוצים שיהיה בן אומנות ממקום אחר באותו מבוי, \u0003ו\u0004אולם \u0003לשכנו אינו כופיהו,\u0004 שמי שכבר שוכן שם באותו מבוי אינו יכול לכפותו שלא יעסוק באיזה מקצוע. \u0003רבן שמעון בן גמליאל אומר: אף לשכנו כופיהו.\u0004 ונמצא שרב הונא סבור כרבן שמעון בן גמליאל.","\u0003אמר רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע: פשיטא\u0004 \u0005[פשוט]\u0006 \u0003לי\u0004 דבר זה, \u0003בר מתא אבר מתא אחריתי מצי מעכב\u0004 \u0005[בן עיר\u0006 אחת \u0005על בן עיר אחרת יכול לעכב]\u0006 שלא יבוא לעיר לעסוק באותה אומנות, \u0003ואי\u0004 \u0005[ואם]\u0006 הוא \u0003שייך בכרגא דהכא\u0004 \u0005[במס\u0006 הגולגולת \u0005של כאן],\u0006 שמשלם מיסיו לאותה עיר — \u0003לא מצי מעכב\u0004 \u0005[אינו יכול לעכב],\u0006 משום שגם ההוא נחשב כאחד מבני העיר. \u0003בר מבואה אבר מבואה דנפשיה\u0004 \u0005[בן מבוי על בן מבוי שלו]\u0006 — \u0003לא מצי מעכב\u0004 \u0005[אינו יכול לעכב]\u0006 מלעסוק באומנות מסויימת באותו מבוי, וכדברי חכמים בברייתא (ולא כדעת רב הונא לעיל).","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע: בר מבואה אבר מבואה אחרינא, מאי\u0004 \u0005[בן מבוי על בן מבוי אחר, מה\u0006 דינו\u0005]?\u0006 שאלה זו לא נפתרה, ועל כן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה. \u0003אמר רב יוסף: ומודי\u0004 \u0005[ומודה]\u0006 \u0003רב הונא\u0004 שאמר שיכול בן מבוי לעכב על חבירו להעמיד גם הוא ריחיים שם, \u0003במקרי דרדקי דלא מצי מעכב\u0004 \u0005[במלמד תינוקות שאינו יכול לעכב],\u0006 ש\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003עזרא תיקן להן לישראל שיהו מושיבין סופר בצד סופר.\u0004","ושואלים: \u0003וניחוש דילמא אתי לאיתרשולי\u0004 \u0005[ונחשוש שמא יבואו להתרשל]\u0006 על ידי כך! ומשיבים, \u0003אמר ליה\u0004 \u0005[לו]:\u0006"],["\u0003קנאת סופרים תרבה חכמה.\u0004","ובדומה לכך \u0003אמר רב נחמן בר יצחק:\u0004 \u0003ומודה רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע\u0004 שאמר שבני העיר מעכבים על אומנים מעיר אחרת, \u0003ברוכלין המחזירין בעיירות\u0004 ש\u0003לא מצי מעכב\u0004 \u0005[יכול לעכב]\u0006 עליהם רוכל מבני העיר מלבוא לאותו מקום, ש\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003עזרא תקן להן לישראל שיהו רוכלין מחזירין בעיירות, כדי שיהו תכשיטין מצויין לבנות ישראל.\u0004 ומשום שהיא תקנת בנות ישראל תיקנו שלא יעכבו עליהם מלבוא.","ומוסיפים: \u0003והני מילי לאהדורי\u0004 \u0005[ודברים אלה\u0006 אמורים דווקא \u0005לחזר,\u0006 לסובב\u0005]\u0006 בעיר כרוכל, \u0003אבל לאקבועי\u0004 \u0005[לקבוע\u0006 חנות\u0005]\u0006 — \u0003לא. ואי צורבא מרבנן\u0004 \u0005[ואם תלמיד חכם]\u0006 \u0003הוא\u0004 הרוכל, \u0003אפילו לאקבועי נמי\u0004 \u0005[לקבוע גם כן]\u0006 מותר לו. \u0003כי הא\u0004 \u0005[כמו\u0006 מעשה \u0005זה]\u0006 ש\u0003רבא שרא להו\u0004 \u0005[התיר להם]\u0006 \u0003לר' יאשיה ולרב עובדיה לאקבועי\u0004 \u0005[לקבוע]\u0006 מקום ש\u0003לא כהלכתא\u0004 \u0005[כהלכה],\u0006 \u0003מאי טעמא\u0004 \u0005[מה הטעם]?\u0006 — \u0003כיון דרבנן נינהו, אתו לטרדו מגירסייהו\u0004 \u0005[שחכמים הם, עלולים\u0006 הם \u0005להיטרד מלימודם]\u0006 אם יצטרכו לחזר ממקום למקום.","מסופר: \u0003הנהו דיקולאי דאייתו דיקלאי\u0004 \u0005[מוכרי סלים שהביאו סלים]\u0006 \u0003לבבל, אתו בני מתא קא מעכבי עלויהו\u0004 \u0005[באו בני העיר\u0006 ו\u0005עיכבו עליהם]\u0006 שלא ימכרו שם. \u0003אתו לקמיה\u0004 \u0005[באו לפני]\u0006 \u0003רבינא\u0004 לדין, \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003מעלמא אתו ולעלמא ליזבנו\u0004 \u0005[מהעולם,\u0006 מחוץ לעיר \u0005באו, ולעולם,\u0006 לאנשים שמחוץ לעיר \u0005ימכרו],\u0006 שהרי יש לומר שהם מוכרים לאורחים שאינם מבני העיר. ועל כך מעירים: \u0003והני מילי ביומא דשוקא\u0004 \u0005[ודברים אלה\u0006 אמורים דווקא \u0005ביום השוק]\u0006 שאכן באים בני עיירות אחרות לקנות, \u0003אבל בלא יומא דשוקא\u0004 \u0005[יום השוק]\u0006 — \u0003לא. וביומא דשוקא נמי לא אמרינן\u0004 \u0005[וביום השוק גם כן אין אנו אומרים]\u0006 כן \u0003אלא לזבוני בשוקא\u0004 \u0005[למכור בשוק],\u0006 \u0003אבל לאהדורי\u0004 \u0005[לחזר]\u0006 מבית לבית — \u0003לא.\u0004","ועוד מסופר: \u0003הנהו עמוראי דאייתו עמרא\u0004 \u0005[מוכרי צמר שהביאו צמר]\u0006 \u0003ל\u0004עיירה \u0003פום נהרא, אתו בני מתא קא מעכבי עלויהו\u0004 \u0005[באו בני העיר\u0006 ו\u0005עיכבו עליהם]\u0006 שלא ימכרו. \u0003אתו לקמיה\u0004 \u0005[באו לפני]\u0006 \u0003רב כהנא\u0004 לדין, \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003דינא\u0004 \u0005[דין]\u0006 \u0003הוא דמעכבי עלייכו\u0004 \u0005[שמעכבים עליכם].\u0006 \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003אית לן\u0004 \u0005[יש לנו]\u0006 \u0003אשראי,\u0004 חובות, לגבות בעיר, ואנו צריכים למכור דברים כדי להתפרנס בינתיים, עד שנוכל לגבות אותם. \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003זילו זבנו\u0004 \u0005[לכו\u0006 ו\u0005מכרו]\u0006 \u0003שיעור חיותייכו\u0004 \u0005[מחייתכם],\u0006 \u0003עד דעקריתו\u0004 \u0005[שתעקרו],\u0006 תקבלו את ה\u0003אשראי דידכו ואזליתו\u0004 \u0005[שלכם ותלכו].\u0006","מסופר: \u0003רב דימי מנהרדעא אייתי\u0004 \u0005[הביא]\u0006 \u0003גרוגרות בספינה\u0004 כדי למוכרן, \u0003אמר ליה ריש גלותא\u0004 \u0005[לו ראש הגולה]\u0006 \u0003לרבא: פוק חזי אי צורבא מרבנן\u0004 \u0005[צא וראה, אם תלמיד חכם]\u0006 \u0003הוא נקיט ליה שוקא\u0004 \u0005[תפוס לו\u0006 את \u0005השוק],\u0006 שתכריז שיש לו רשות בלעדית למכור את הגרוגרות. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא לרב אדא בר אבא\u0004 תלמידו: \u0003פוק תהי ליה בקנקניה\u0004 \u0005[צא, תהה לו בקנקנו],\u0006 כלומר, בדוק אותו אם תלמיד חכם הוא.","\u0003נפק אזל בעא מיניה\u0004 \u0005[יצא הלך\u0006 ו\u0005שאל אותו]\u0006 את רב דימי שאלה זו: \u0003פיל שבלע כפיפה מצרית\u0004 (סל עשוי מנצרים) \u0003והקיאה,\u0004 הוציא אותה כמות שהיא, \u0003דרך בית הרעי, מהו\u0004 (מה דינה)? האם היא מטמאה עדיין, או נחשבת כמעוכלת ונטהרה? \u0003לא הוה בידיה\u0004 \u0005[היתה בידו]\u0006 תשובה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב דימי לרב אדא בר אבא: \u0003מר ניהו\u0004 \u0005[האם אדוני הוא]\u0006 \u0003רבא\u0004 שאתה שואלני שאלה קשה כזו? \u0003טפח ליה בסנדליה\u0004 \u0005[היכה אותו על סנדלו]\u0006 בדרך זלזול, \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003בין דידי\u0004 \u0005[ביני]\u0006 \u0003ל\u0004בין \u0003רבא איכא טובא\u0004 \u0005[יש הרבה\u0006 הבדל\u0005],\u0006 \u0003מיהו\u0004 \u0005[על כל פנים]\u0006 \u0003על כרחך אנא רבך\u0004 \u0005[אני רבך],\u0006 \u0003ורבא\u0004 הוא \u0003רבה דרבך\u0004 \u0005[רבו של רבך].\u0006","והחליט משום כך רב אדא שאין רב דימי תלמיד חכם חשוב, ולכן \u0003לא נקטו ליה שוקא\u0004 \u0005[תפסו לו שוק],\u0006 \u0003פסיד גרוגרות דידיה\u0004 \u0005[והפסיד\u0006 את \u0005הגרוגרות שלו],\u0006 שנתקלקו. \u0003אתא לקמיה\u0004 \u0005[בא\u0006 רב דימי \u0005לפני]\u0006 \u0003רב יוסף\u0004 להתלונן, \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003חזי מר מאי עבדו\u0004 \u0005[יראה אדוני מה עשו]\u0006 \u0003לי!\u0004 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מאן\u0004 \u0005[מי]\u0006 ש\u0003לא שהייה לאוניתא דמלכא\u0004 \u0005[השהה את הונאתו\u0006 בושתו\u0005]\u0006 של מלך \u0003אדום\u0004 — \u0003לא נשהייה לאוניתיך\u0004 \u0005[ישהה את הונאתך]\u0006 ויעניש את מי שציער אותך, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"כה אמר ה' על שלשה פשעי מואב ועל ארבעה לא אשיבנו על שרפו עצמות מלך אדום לסיד\"\u0004 (עמוס ב, א).","ומספרים: \u0003נח נפשיה\u0004 \u0005[נפטר]\u0006 \u0003רב אדא בר אבא. רב יוסף אמר: אנא ענישתיה, דאנא לטייתיה\u0004 \u0005[אני ענשתי אותו, שאני קיללתי אותו].\u0006 \u0003רב דימי מנהרדעא אמר: אנא ענישתיה, דאפסיד\u0004 \u0005[אני ענשתי אותו,\u0006 בגללי נענש, \u0005שהפסיד]\u0006 ה\u0003גרוגרות דידי\u0004 \u0005[שלי].\u0006 \u0003אביי אמר: אנא ענישתיה\u0004 \u0005[אני ענשתי אותו],\u0006 כלומר, נענש בגללי, על שלא נהג בי כבוד, \u0003דאמר להו לרבנן\u0004 \u0005[שהיה אומר להם לחכמים]:\u0006 \u0003אדמגרמיתו גרמי בי\u0004 \u0005[עד שאתם מכרסמים עצמות\u0006 \u0003אצל]\u0004 \u0003אביי, תו אכלו בישרא שמינא בי\u0004 \u0005[בואו איכלו בשר שמן\u0006 \u0003אצל]\u0004 \u0003רבא,\u0004 כלומר, עדיף ללמוד אצל רבא מאשר אצל אביי. \u0003ורבא אמר: אנא ענישתיה\u0004 \u0005[אני ענשתי אותו],\u0006 בגללי נענש, \u0003דכי הוה אזיל לבי טבחא למשקל אומצא\u0004 \u0005[שכאשר היה הולך לבית הטבח לקחת חתיכת בשר],\u0006 \u0003אמר להו לטבחי\u0004 \u0005[היה אומר להם לטבחים]:\u0006 \u0003אנא שקילנא בישרא מיקמי שמעיה\u0004 \u0005[אני אקח את הבשר לפני שמשו של]\u0006 \u0003רבא\u0004 משום \u0003דאנא עדיפנא מיניה\u0004 \u0005[שאני עדיף ממנו].\u0006","\u0003רב נחמן בר יצחק אמר: אנא ענישתיה\u0004 \u0005[אני ענשתי אותו],\u0006 ומספרים; ש\u0003רב נחמן בר יצחק ריש כלה הוה\u0004 \u0005[היה],\u0006 כלומר, ממונה ללמד את בני הישיבה לאחר ששמעו בראשונה את דרשת ראש הישיבה. \u0003כל יומא\u0004 \u0005[יום]\u0006 \u0003מיקמי דניעול\u0004 \u0005[לפני שהיה נכנס]\u0006 \u0003לכלה, מרהיט בהדיה\u0004 \u0005[היה עובר איתו]\u0006 \u0003רב אדא בר אבא לשמעתיה\u0004 \u0005[את הלכתו]\u0006 \u0003והדר עייל\u0004 \u0005[ואחר כך היה נכנס]\u0006 \u0003לכלה.\u0004","\u0003ההוא יומא נקטוה\u0004 \u0005[\u0006ב\u0005אותו יום אחזו בו]\u0006 \u0003רב פפא ורב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע לרב אדא בר אבא משום\u0004 ש\u0003לא הוו בסיומא\u0004 \u0005[היו בסיום]\u0006 המסכת, \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003אימא לן הני שמעתתא\u0004 \u0005[אמור לנו את ההלכות הללו]\u0006 של \u0003מעשר בהמה היכי אמרינהו\u0004 \u0005[איך אמר אותן]\u0006 \u0003רבא.\u0004 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר רבא והכי\u0004 \u0005[וכך]\u0006 \u0003אמר רבא. אדהכי נגה ליה\u0004 \u0005[בינתיים התאחר לו\u0006 הזמן\u0005]\u0006 \u0003לרב נחמן בר יצחק, ולא אתי\u0004 \u0005[בא]\u0006 \u0003רב אדא בר אבא,\u0004","\u0003אמרו ליה רבנן\u0004 \u0005[לו חכמים]\u0006 \u0003לרב נחמן בר יצחק: קום\u0004 ולמדנו, \u0003דנגה לן\u0004 \u0005[שמאוחר לנו],\u0006 \u0003למה יתיב מר\u0004 \u0005[יושב אדוני]\u0006 ומחכה? \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003יתיבנא וקא מנטרא לערסיה\u0004 \u0005[יושב אני ומחכה למיטתו]\u0006 של \u0003רב אדא בר אבא\u0004 שמן הסתם מת. \u0003אדהכי נפק קלא דנח נפשיה\u0004 \u0005[בינתיים יצא קול שנפטר]\u0006 \u0003רב אדא בר אבא.\u0004 ומעירים: \u0003ומסתברא\u0004 \u0005[ומסתבר],\u0006 ש\u0003רב נחמן בר יצחק ענשיה\u0004 \u0005[ענש אותו]\u0006 כי אירע הדבר ממש מיד כשאמר זאת.","\u0003מי שהיה כותלו סמוך לכותל חבירו, לא יסמוך\u0004 (יבנה סמוך) \u0003לו כותל אחר אלא אם כן הרחיק ממנו ארבע אמות.\u0004 ו\u0003החלונות,\u0004 מרחיק מהן את הכותל \u0003בין מלמעלן בין מלמטן בין כנגדן\u0004 — \u0003ארבע אמות.\u0004","ושואלים: עד שדנים בשאלה אם לסמוך כותל אחר, יש לשאול: \u0003וקמא היכי סמיך\u0004 \u0005[ו\u0006את הכותל \u0005הראשון איך סמך]?\u0006 \u0003אמר רב יהודה, הכי קאמר\u0004 \u0005[כך הוא אומר]:\u0006"],["\u0003הבא לסמוך\u0004 כותל לכותל חבירו, \u0003לא יסמוך אלא אם כן הרחיק ממנו ארבע אמות. מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רבא: והא\u0004 \u0005[והרי]\u0006 \u0003\"מי שהיה כותלו סמוך לכותל חבירו\" קתני\u0004 \u0005[שנה],\u0006 משמע שכבר היה שם כותל!","\u0003אלא אמר רבא, הכי קתני\u0004 \u0005[כך שנה],\u0006 כך צריך להבין: \u0003מי שהיה כותלו סמוך לכותל חבירו ברחוק ארבע אמות ונפל\u0004 כותלו, \u0003לא יסמוך לו\u0004 לכותל חבירו \u0003כותל אחר\u0004 חדש \u0003אלא אם כן הרחיק ממנו ארבע אמות; מאי טעמא\u0004 \u0005[מה טעם]\u0006 להרחקה זו? — משום \u0003דדוושא דהכא מעלי להתם\u0004 \u0005[שדריסת הרגל של כאן מועיל לשם],\u0006 שהקרקע מתחזקת על ידי ההילוך במקום הפנוי.","\u0003אמר רב: לא שנו\u0004 שצריך להניח מקום פנוי \u0003אלא\u0004 ליד \u0003כותל גינה\u0004 של חבירו, שאין מרבים להלך בה מפני הזרעים, \u0003אבל כותל חצר\u0004 שמהלכים בה — \u0003אם בא לסמוך סומך;\u0004 ואילו \u0003ר' אושעיא אומר: אחד כותל גינה ואחד כותל חצר\u0004 — \u0003אם בא לסמוך אינו סומך.\u0004","\u0003אמר ר' יוסי בר חנינא: ולא פליגי\u0004 \u0005[ואין\u0006 הם \u0005חלוקים]\u0006 אלא מדברים במקרים שונים: \u0003הא\u0004 \u0005[זה]\u0006 רב, מדבר \u0003בעיר ישנה\u0004 שבה אדמת חצרותיה כבר נדרכה היטב והיא יציבה, \u0003הא\u0004 \u0005[\u0006ו\u0005זה]\u0006 ר' אושעיא, מדבר \u0003בעיר חדשה\u0004 שגם כותל חצר זקוק להילוך לחזקו.","על הסבר זה לדין המשנה, של דריסת הרגל, מקשים, \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003החלונות,\u0004 צריך להרחיק \u0003בין מלמעלן בין מלמטן בין מכנגדן\u0004 — \u0003ארבע אמות, ותני עלה\u0004 \u0005[ושנויה עליה\u0006 ברייתא\u0005]:\u0006 \u0003מלמעלן\u0004 — צריך להרחיק את גובה הכותל \u0003כדי שלא יציץ\u0004 בחלון \u0003ויראה, מלמטן\u0004 — ינמיך כדי \u0003שלא יעמוד\u0004 על גבי כותלו \u0003ויראה, ומכנגדן\u0004 — ירחיק \u0003שלא יאפיל\u0004 את האור לחלונותיו של חבירו.","ומדייקים: \u0003טעמא\u0004 \u0005[הטעם]\u0006 שנתנו להרחקה זו כנגד החלון הוא דווקא כדי \u0003שלא יאפיל, אבל משום דוושא\u0004 \u0005[דריסת הרגל]\u0006 \u0003לא!\u0004 ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]?\u0006 — \u0003בבא\u0004 הכותל \u0003מן הצד\u0004 של החלון, בניצב לקיר שבו החלון, והוא מאפיל על החלון, אבל אינו מונע דריסת הרגל לאורך כל הקיר.","ושואלים: \u0003וכמה\u0004 ירחיק? \u0003אמר ייבא חמוה\u0004 \u0005[חמיו]\u0006 של \u0003אשיין בר נדבך משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב: כמלא רחב חלון.\u0004 ושואלים: \u0003והלא מציץ,\u0004 אם קרוב הוא כל כך! \u0003אמר רב זביד: במדיר את כותלו,\u0004 כלומר, שעושה מדרון בראש הכותל באופן שאינו יכול עוד לעמוד על גביו ולהסתכל דרך החלון.","ומקשים: \u0003והא אנן תנן\u0004 \u0005[והרי אנו שנינו\u0006 במשנה\u0005]:\u0006 \u0003ארבע אמות!\u0004 ומשיבים: \u0003לא קשיא\u0004 \u0005[קשה]:\u0006 \u0003כאן\u0004 כשבנה כותל \u0003מרוח אחת,\u0004 בצד אחד של החלון, \u0003כאן\u0004 כאשר בונה כתלים \u0003משתי רוחות\u0004 של החלון, שאם יקרבם יאפיל הרבה את החלון אף שהם מן הצד.","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 קושיה נוספת על ההסבר של דריסת הרגל ממה ששנינו: \u0003ו\u0004מרחיקים \u0003את הכותל מן המזחילה\u0004 (מרזב קבוע לאורך הגג) \u0003ארבע אמות, כדי שיהא\u0004 בעל המזחילה \u0003זוקף את הסולם\u0004 במקום הפנוי, לצורך ניקוי ותיקון המזחילה. ונדייק: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 \u0003משום\u0004 העמדת \u0003סולם, אבל משום דוושא\u0004 \u0005[דריסת הרגל]\u0006 \u0003לא!\u0004 ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003במזחילה משופעת,\u0004 היוצאת מעבר לגבול הכותל, \u0003דאי\u0004 \u0005[שאם]\u0006 דין ההרחקה \u0003משום\u0004 הטעם של \u0003דוושא\u0004 \u0005[דריסה]\u0006 \u0003הוא, הא קא אזיל ואתי תותיה\u0004 \u0005[הרי הוא הולך ובא תחתיה],\u0006 ולמרות זאת מצריכה המשנה ארבע אמות ממקום המזחילה\u0005.\u0006","\u0003מרחיקין את הסולם מן השובך\u0004 של חבירו \u0003ארבע אמות, כדי שלא תקפוץ הנמייה\u0004 מן הסולם לשובך ותטרוף את היונים; \u0003ו\u0004מרחיקים \u0003את הכותל מן המזחילה ארבע אמות, כדי שיהא\u0004 חבירו בעל המזחילה \u0003זוקף את הסולם\u0004 לעלות ולתקן את קלקולי המזחילה.","ומציעים: \u0003לימא מתניתין\u0004 \u0005[האם לומר\u0006 ש\u0005משנתנו]\u0006 היא ש\u0003לא כ\u0004שיטת \u0003ר' יוסי, דאי\u0004 \u0005[שאם]\u0006 כשיטת \u0003ר' יוסי\u0004 היא, \u0003הא\u0004 \u0005[הרי]\u0006 \u0003אמר\u0004 בענין נטיעת אילן סמוך לבורו של חבירו: \u0003זה חופר בתוך שלו וזה נוטע בתוך שלו,\u0004 ואין הוא צריך להתחשב במה שקורה אצל חבירו!","ומשיבים: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שהוא כשיטת \u0003ר' יוסי, הא\u0004 \u0005[הרי]\u0006 \u0003אמר רב אשי: כי הוינן בי\u0004 \u0005[כאשר היינו בבית]\u0006 מדרשו של \u0003רב כהנא, הוה אמר\u0004 \u0005[היה אומר\u0006 לנו\u0005]:\u0006 \u0003מודי\u0004 \u0005[מודה]\u0006 \u0003ר' יוסי בגירי דידיה\u0004 \u0005[בחיצים שלו],\u0006 כלומר, בנזק הנגרם על ידו לחבירו על ידי מעשיו, שבמקרה זה צריך להרחיק, \u0003הכא נמי זמנין דבהדי דמנח ליה יתבא\u0004 \u0005[כאן גם כן, פעמים שבזמן ש\u0006הוא \u0005מניח אותו,\u0006 את הסולם, \u0005יושבת]\u0006 הנמייה בינתיים \u0003בחור וקפצה\u0004 \u0005[ו\u0006היא \u0005קופצת]\u0006 ועולה דרך הסולם אל השובך. ושואלים: \u0003והא גרמא\u0004 \u0005[והרי\u0006 רק \u0005גרם]\u0006 נזק \u0003הוא,\u0004 ואינו נזק שבא על ידו ממש! \u0003אמר רב טובי בר מתנה, זאת אומרת:\u0004 אף \u0003גרמא\u0004 \u0005[גרם\u0006 בלבד\u0005]\u0006 \u0003בניזקין אסור\u0004 לעשות.","ובענין זה מסופר: \u0003רב יוסף הוה ליה הנהו תאלי דהוו\u0004 \u0005[היו לו דקלים שהיו]\u0006"],["\u0003אתו אומני ויתבי תותייהו\u0004 \u0005[באים מקיזי דם ויושבים תחתם]\u0006 ועושים שם את מלאכתם, \u0003ואתו עורבי אכלי דמא\u0004 \u0005[ו\u0006היו \u0005עורבים באים אוכלים\u0006 מן \u0005הדם]\u0006 \u0003וסלקי אבי תאלי ומפסדי תמרי\u0004 \u0005[ועולים על הדקלים ומפסידים\u0006 את \u0005התמרים].\u0006 \u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רב יוסף: אפיקו\u0004 \u0005[הוציאו]\u0006 \u0003לי\u0004 את \u0003קורקור מהכא\u0004 \u0005[המקרקרים,\u0006 העורבים, \u0005מכאן],\u0006 כלומר, סלק את האומנים שלא יגרמו עוד להיזק. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: והא גרמא\u0004 \u0005[והרי גרם\u0006 בלבד\u0005]\u0006 \u0003הוא\u0004 ולא הם בעצמם מזיקים! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר רב טובי בר מתנה, זאת אומרת: גרמא\u0004 \u0005[גרם\u0006 בלבד\u0005]\u0006 \u0003בניזקין אסור.\u0004","ושואלים: \u0003והא אחזיק להו\u0004 \u0005[והרי\u0006 כבר \u0005החזיקו]\u0006 להשתמש כך במקום הזה ויש להם חזקת שימוש בזה! אמר לו: \u0003הא\u0004 \u0005[הרי]\u0006 \u0003אמר רב נחמן אמר רבה בר אבוה: אין חזקה לנזקין,\u0004 שאין אומרים שיש לאדם חזקה של שימוש בזמן שהוא מזיק. ושואלים: \u0003ולאו איתמר עלה\u0004 \u0005[והאם לא נאמר עליה]\u0006 ש\u0003רב מרי אמר:\u0004 מדובר דווקא \u0003בקוטרא\u0004 \u0005[בעשן],\u0006 \u0003ורב זביד אמר: בבית הכסא?\u0004 כלומר, לא נאמר כלל זה אלא דווקא בנזקים חמורים כאלה, ולא בפחות מכאן. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הני לדידי, דאנינא דעתאי\u0004 \u0005[אלה בשבילי, שדעתי אנינה\u0006 ומפונקת\u0005],\u0006 \u0003כי קוטרא\u0004 \u0005[כמו עשן]\u0006 \u0003ובית הכסא דמו\u0004 \u0005[\u0006הם \u0005נחשבים]\u0006 \u0003לי\u0004 ולכן אני רשאי להרחיק אותם.","\u0003מרחיקין את השובך מן העיר חמשים אמה,\u0004 שלא יבואו היונים לאכול מהזרעים שבעיר. \u0003ולא יעשה אדם שובך בתוך שלו, אלא אם כן יש לו\u0004 שטח נוסף מרחק \u0003חמשים אמה לכל רוח\u0004 (צד) מן השובך; \u0003ר' יהודה אומר: בית\u0004 מקום זריעה של \u0003ארבעת כורין\u0004 תבואה, שהוא \u0003מלא שגר היונה,\u0004 כלומר, מלוא מעוף היונה בבת אחת. \u0003ואם לקחו\u0004 (קנה אותו), את השובך, עם הקרקע, \u0003אפילו\u0004 אין מסביבו אלא \u0003בית\u0004 זריעת \u0003רובע\u0004 הקב, ולא יותר — \u0003הרי הוא בחזקתו\u0004 ואינו צריך להוציאו משם.","ושואלים: \u0003חמשים אמה ותו\u0004 \u0005[ויותר]\u0006 \u0003לא?\u0004 וזה המרחק שחוששים שיגיעו יונים? \u0003ורמינהי\u0004 \u0005[ומשליכים\u0006 מראים סתירה לכך\u0005]\u0006 ממה ששנינו: \u0003אין פורסין נשבין\u0004 (מצודות) \u0003ליונים\u0004 שלא יתפוס יונים השייכות לאדם אחר, \u0003אלא אם כן היה רחוק מן הישוב שלשים ריס\u0004 (ארבעה מילים, כלומר, שמונת אלפים אמות). משמע שיונים מרחיקות כדי שלושים ריס, וכאן אמר רק חמישים אמה!","\u0003אמר אביי: מישט שייטי טובא\u0004 \u0005[לעוף עפים\u0006 הם \u0005הרבה]\u0006 ולכן צריכים להרחיק עד שלושים ריס כדי שלא יצוד יונים השייכות לחבירו, \u0003ו\u0004אולם \u0003כרסייהו\u0004 \u0005[כריסם]\u0006 \u0003ב\u0004מרחק של \u0003חמשים אמתא מליא\u0004 \u0005[אמה מתמלאה],\u0006 ושוב אינם מזיקים כל כך. ושואלים: \u0003ומישט\u0004 \u0005[ולעוף]\u0006 רק \u0003שלשים ריס\u0004 עפים \u0003ותו\u0004 \u0005[ויותר]\u0006 \u0003לא? והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ובישוב\u0004 עצמו \u0003אפילו\u0004 היה גודלו \u0003מאה מיל לא יפרוס\u0004 מצודה! \u0003רב יוסף אמר:\u0004 מדובר בברייתא \u0003בישוב כרמים,\u0004 שמקום הישוב רצוף כרמים וגינות, והיונים עוברות ממקום למקום אפילו מרחק גדול.","\u0003רבא אמר:\u0004 מדובר שם \u0003בישוב שובכין\u0004, שהיו בו שובכים רבים מפוזרים. ושואלים: \u0003ותיפוק ליה\u0004 \u0005[ותצא לו]\u0006 הלכה זו \u0003משום\u0004 ה\u0003שובכין גופייהו\u0004 \u0005[השובכים עצמם],\u0006 שהרי אמרנו שצריך להרחיק מן השובך בלי קשר עם העיר! ומשיבים: \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 כי מדובר פה בשובכים \u0003דידיה\u0004 \u0005[שלו],\u0006 אלא שיש לחשוש שמא היונים של העיר עוברות דרך השובכים שלו; \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 כי מדובר בשובכים של \u0003גוי\u0004 שאינו מצווה להישמר בנזק העלול להיגרם לו. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 כי מדובר בשובכים של \u0003הפקר.\u0004","שנינו במשנה ש\u0003ר' יהודה אומר: בית ארבעת כורין\u0004 מלוא שגר היונה. אבל אם קנה חצר שהיה בה השובך, אפילו היה המקום קטן — הרי הוא בחזקתו, ואינו צריך להוציאו. \u0003אמר רב פפא, ואיתימא\u0004 \u0005[ויש אומרים שאמר]\u0006 זאת \u0003רב זביד, זאת אומרת:\u0004 בית הדין \u0003טוענין ללוקח\u0004 (קונה) \u0003וטוענין ליורש,\u0004 שהם עצמם אינם צריכים להסביר כיצד הגיע ליד המוכר או המוריש להם נכס זה, אם כבר החזיק בו שלוש שנים.","ומקשים: מדוע הוצרך רב זביד לומר זאת? הרי \u0003יורש\u0004 — \u0003תנינא\u0004 \u0005[\u0006כבר \u0005שנינו]:\u0006 \u0003הבא משום ירושה\u0004 — \u0003אינו צריך טענה\u0004 להוכיח כיצד הגיע הדבר לידי מורישיו! ומשיבים: בענין \u0003לוקח איצטריכא ליה\u0004 \u0005[הוצרכה לו\u0006 לומר\u0005]\u0006 הלכה זו, שטוענים לו. ומקשים: \u0003לוקח נמי תנינא\u0004 \u0005[גם כן שנינו\u0006 במשנה\u0005]:\u0006 \u0003לקח\u0004 (קנה) \u0003חצר ובה זיזין וגזוזטראות\u0004 הבולטים לרשות הרבים — \u0003הרי זה בחזקתה\u0004 ואין אומרים לו להסירם!","ומשיבים: מכל מקום \u0003צריכא\u0004 \u0005[צריך\u0006 הדבר להיאמר\u0005],\u0006 \u0003דאי אשמעינן התם\u0004 \u0005[שאם היה משמיע לנו\u0006 רק \u0005שם]\u0006 היינו אומרים שהוא דווקא \u0003גבי\u0004 \u0005[אצל]\u0006 זיז או גזוזטרא היוצא ל\u0003רשות הרבים\u0004 — משום \u0003דאימור\u0004 \u0005[שאמור]\u0006 שמא \u0003כונס לתוך שלו הוא\u0004 כאשר נבנה מתחילה על ידי המוכר, ולא הוציא לתחום רשות הרבים. \u0003אי נמי אחולי אחול\u0004 \u0005[או גם כן מחלו]\u0006 \u0003בני רשות הרבים גביה\u0004 \u0005[לו]\u0006 על מה שהוציא לרשותם, שאם לא כן לא היו מניחים לו, \u0003אבל הכא\u0004 \u0005[כאן]\u0006 שמזיק לאדם פרטי — \u0003לא;\u0004","\u0003ואי אשמעינן הכא\u0004 \u0005[ואם היה משמיע לנו\u0006 רק \u0005כאן]\u0006 במשנתנו\u0005,\u0006 היינו אומרים: ש\u0003כיון\u0004 ש\u0003יחיד הוא\u0004 — \u0003אימא\u0004 \u0005[אמור]:\u0006 שמא \u0003פיוסיה פייסיה\u0004 \u0005[פייס אותו]\u0006 את שכנו במעות כדי שירשה לו לעשות כן, \u0003אי נמי אחולי אחיל גביה\u0004 \u0005[או גם כן\u0006 שמא \u0005מחל לו],\u0006 \u0003אבל\u0004 כאשר הנזק מגיע לרשות ה\u0003רבים,\u0004 שיש לומר \u0003מאן פייס ומאן שביק\u0004 \u0005[\u0006את \u0005מי פייס ומי הניח,\u0006 מחל לו\u0005]\u0006 — \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 נעמוד בצד הלוקח, אם כן \u0003צריכא\u0004 \u0005[נצרכה]\u0006 הלכה זו להיאמר.","שנינו במשנה שאם קנה את השובך, אפילו אם אין לצידו אלא בית רובע קרקע \u0003הרי הוא בחזקתו.\u0004 ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר רב נחמן אמר רבה בר אבוה: אין חזקה לנזקין!\u0004 ומדוע כאן כשהיונים שלו מזיקות בכל זאת יש חזקה? \u0003רב מרי אמר:\u0004 מה שאמר רב נחמן, כוונתו דווקא \u0003בקוטרא\u0004 \u0005[בעשן]\u0006 שנזק חמור כזה אין בו חזקה, \u0003רב זביד אמר: בבית הכסא\u0004 שריחו קשה ביותר."],["\u0003ניפול\u0004 (גוזל של יונים שנפל) \u0003הנמצא בתוך חמשים אמה\u0004 לשובך — \u0003הרי הוא של בעל השובך.\u0004 נמצא \u0003חוץ מחמשים אמה\u0004 — \u0003הרי הוא של מוצאו. נמצא בין שני שובכות\u0004 בתוך חמישים אמה \u0003לשניהם,\u0004 אם היה \u0003קרוב לזה\u0004 — הרי הוא \u0003שלו, קרוב לזה\u0004 — \u0003שלו,\u0004 היה \u0003מחצה\u0004 \u0003על מחצה\u0004 במרחק שווה משניהם — \u0003שניהם יחלוקו.\u0004","\u0003אמר ר' חנינא:\u0004 כשיש לנו ספק בדבר הנמצא, לאיזה מקום הוא שייך, ומצד אחד אפשר ללכת בו אחר ה\u0003רוב,\u0004 ולשייך אותו למקום אחד. \u0003ו\u0004מצד שני אפשר ללכת בו אחר ה\u0003קרוב\u0004 (מה שסמוך יותר), ולשייך אותו למקום האחר — \u0003הולכין אחר הרוב, ואף על גב דרובא דאורייתא וקורבא דאורייתא\u0004 \u0005[ואף על פי ש\u0006דין \u0005רוב\u0006 הוא \u0005מן התורה ו\u0006דין \u0005קירבה\u0006 הוא \u0005מן התורה],\u0006 \u0003אפילו הכי\u0004 \u0005[כך]\u0006 \u0003רובא\u0004 \u0005[הרוב]\u0006 \u0003עדיף.\u0004","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003ר' זירא:\u0004 והרי נאמר לענין הרוג שנמצא ולא ידוע מי רצחו: \u0003\"והיה העיר הקרבה אל החלל\"\u0004 (דברים כא, ג) שהיא העיר שזקניה צריכים להביא עגלה ערופה, \u0003ו\u0004משמע \u0003אף על גב דאיכא אחריתי דנפישא מינה\u0004 \u0005[אף על פי שיש\u0006 עיר \u0005אחרת שמרובה ממנה],\u0006 ולדברי ר' חנינא, במקרה כזה היה צריך ללכת אחר הרוב!","ומשיבים: מדובר פה \u0003בדליכא\u0004 \u0005[בשאין]\u0006 עיר אחרת גדולה יותר. ומקשים: ומכל מקום, גם אם הולכים אחר הרוב, מדוע נלך אחר העיר הקרובה? \u0003וליזיל בתר רובא דעלמא\u0004 \u0005[ונלך אחר רוב העולם]\u0006 והרי הרוב נמצא במקומות אחרים! ומשיבים: מדובר \u0003ב\u0004עיר ש\u0003יושבת בין ההרים,\u0004 שהיא מבודדת, ואין להניח שבא לכאן רוצח ממקום אחר.","ומביאים ראיה נוספת, \u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003ניפול הנמצא בתוך חמשים אמה\u0004 — \u0003הרי הוא של בעל השובך; ו\u0004מסתימת הדברים יש להבין שדין זה חל \u0003אף על גב דאיכא אחרינא דנפיש מיניה\u0004 \u0005[אף על פי שיש\u0006 שובך \u0005אחר שמרובה ממנו]\u0006 במספר היונים, אלא שאינו בתוך חמשים אמה. ואם כך הרי שאין הולכים אחר הרוב אלא אחר הקרוב! ומשיבים: מדובר פה \u0003בדליכא\u0004 \u0005[בשאין]\u0006 שובך כזה באיזור.","ומקשים: \u0003אי הכי, אימא סיפא\u0004 \u0005[אם כך, אמור\u0006 את \u0005הסוף]\u0006 של אותה הלכה: \u0003חוץ מחמשים אמה\u0004 — \u0003הרי הוא של מוצאו; ואי דליכא\u0004 \u0005[ואם שאין]\u0006 שובך אחר באותו איזור, \u0003ודאי מההוא\u0004 \u0005[מאותו]\u0006 שובך \u0003נפל!\u0004 ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003ב\u0004גוזל ה\u0003מדדה,\u0004 שאינו עף עדיין, אלא רק מקפץ ממקום למקום. ש\u0003אמר רב עוקבא בר חמא: כל המדדה\u0004 — \u0003אין מדדה יותר מחמשים\u0004 אמה. ולכן כל שהוא בתוך חמשים אמה לשובך — מן הסתם משם בא, ואם רחוק משם — ודאי הגיע ממקום אחר, או שנפל מעוברים ושבים.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' ירמיה:\u0004 היתה \u0003רגלו אחת\u0004 של הגוזל \u0003בתוך חמשים אמה\u0004 מהשובך \u0003ורגלו אחת חוץ מחמשים אמה, מהו?\u0004 ומעירים: \u0003ועל\u0004 שאלה \u0003דא אפקוהו\u0004 \u0005[זו הוציאוהו]\u0006 את \u0003ר' ירמיה מבי מדרשא\u0004 \u0005[מבית המדרש],\u0006 ששאלה זו נראתה כפקפוק בדברי חכמים.","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו במשנתנו: \u0003נמצא בין שני שובכות, קרוב לזה\u0004 — \u0003שלו, וקרוב לזה\u0004 — \u0003שלו; ואף על גב דחד מינייהו נפיש מחבריה\u0004 \u0005[ואף על פי שאחד מהם מרובה מחבירו]\u0006 בכל זאת אין הולכים אחר הרוב אלא אחר הקרוב! ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — במקרה \u0003ששניהן שוין\u0004 בכמות הגוזלים שבהם. ושואלים: ומדוע נלך אחר הקרוב מבין שניהם? \u0003וליזיל בתר רובא דעלמא\u0004 \u0005[ונלך אחר רוב העולם]\u0006 ומלבד שובכים אלה יש שובכים רבים, ומספר יונים גדול יותר! ודוחים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 —"],["\u0003בשביל של כרמים\u0004 שעובר בין הכרמים, ושם מצויים שני שובכים אלו, ש\u0003אם איתא דמעלמא אתי\u0004 \u0005[יש\u0006 מקום לומר \u0005שמהעולם,\u0006 ממקום אחר, הגוזל \u0005בא],\u0006 \u0003כיון דמידדי\u0004 \u0005[ש\u0006הוא \u0005מדדה]\u0006 \u0003לא מצי אתי\u0004 \u0005[היה יכול לבוא\u0006 לשם\u0005],\u0006 ש\u0003כל דמידדי והדר חזי ליה לקיניה\u0004 \u0005[המדדה ופונה\u0006 ו\u0005רואה את קינו]\u0006 — \u0003מידדי\u0004 \u0005[מדדה]\u0006 הלאה, \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא,\u0004 שהרחיק עד שאינו יכול לראות את הקן — \u0003לא מידדי\u0004 \u0005[מדדה].\u0006 ואם כן, גוזל מדדה זה שנמצא — לא בא אלא מאחד משני שובכים אלו.","\u0003אמר אביי: אף אנן נמי תנינא\u0004 \u0005[אנו גם כן שנינו]\u0006 שהולכים אחר הרוב ולא אחר הקרוב, ששנינו: \u0003דם שנמצא בפרוזדור\u0004 (בחלק החיצון של בית הרחם) — הרי \u0003ספיקו,\u0004 אם לא ברור אם דם זה דם נידה הוא או דם אחר, \u0003טמא, שחזקתו\u0004 שבא \u0003מן המקור\u0004 (הרחם, שמשם יוצא דם הנידה); \u0003ואף על גב דאיכא\u0004 \u0005[ואף על פי שיש]\u0006 \u0003עלייה,\u0004 כיס השתן, הנפתח לפרוזדור \u0003דמקרבא\u0004 \u0005[שקרוב\u0006 יותר\u0005]!\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא\u0004 בדחיה: מקרה שהוא גם \u0003רוב ומצוי קא אמרת\u0004 \u0005[אתה אומר],\u0006 ממנו אתה רוצה להוכיח? כשיש \u0003רוב\u0004 שהוא גם \u0003מצוי ליכא למאן דאמר\u0004 \u0005[אין מי שאומר]\u0006 שאין הולכים אחר הרוב אלא אחר הקרוב. והדם שמן המקור לא רק שמרובה יותר, אלא גם מצוי יותר שיגיע לפרוזדור, שבדרך כלל אין דם מן העלייה.","ומביאים ראיה לשיטת רבא, \u0003דתני\u0004 \u0005[ששנה]\u0006 \u0003ר' חייא: דם הנמצא בפרוזדור\u0004 — רואים אותו כדם נידה ממש, ובין האשה ובין מי שבא עליה במצב זה \u0003חייבין עליו\u0004 כרת, ובשוגג — קרבן, \u0003על ביאת מקדש\u0004 בטומאה, \u0003ו\u0004אם נגעה האשה בתרומה — \u0003שורפין עליו את התרומה,\u0004 ואין זה נחשב כענין של ספק.","\u0003ו\u0004בענין זה מביאים דברים לכאורה הפוכים ש\u0003אמר רבא, שמע מינה\u0004 \u0005[למד מכאן]\u0006 \u0003מ\u0004דברי \u0003ר' חייא תלת\u0004 \u0005[שלושה\u0006 דברים\u0005]:\u0006 \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 ש\u0003רוב וקרוב הלך אחר הרוב; ושמע מינה רובא דאורייתא\u0004 \u0005[ולמד מכאן\u0006 שדין \u0005רוב\u0006 הוא \u0005מן התורה],\u0006 שהרי שורפים עליו את התרומה, וחייבים עליו בקרבן; \u0003ושמע מינה\u0004 \u0005[ולמד מכאן]\u0006 \u0003איתא\u0004 \u0005[יש]\u0006 מקור \u0003ל\u0004דברי \u0003ר' זירא,\u0004 ש","\u0003אמר ר' זירא:\u0004 בשר הנמצא בשוק של עיר שרוב החנויות בה מוכרות בשר כשר — הולכים אחר רוב זה והבשר מותר, \u0003אף על פי שדלתות מדינה\u0004 (העיר) \u0003נעולות.\u0004 ואין צורך ברוב כפול, ולהסתמך גם על ההנחה שהבשר נפל מאנשים שבאו לעיר, שרובם יהודים.","\u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003אשה דכי\u0004 \u0005[שכמו]\u0006 \u0003דלתות מדינה נעולות\u0004 \u0003דמיא\u0004 \u0005[\u0006היא \u0005נחשבת],\u0006 שאין שם אלא רוב אחד, \u0003ואפילו הכי\u0004 \u0005[כך]\u0006 \u0003קא אזלינן בתר רובא\u0004 \u0005[הולכים אנו אחר הרוב].\u0006","ויש לשאול: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003רבא הוא דקאמר\u0004 \u0005[שאמר]\u0006 והוכיח מכאן ש\u0003רוב ומצוי ליכא למאן דאמר\u0004 \u0005[אין מי שאומר]\u0006 שאין הולכים אחר הרוב, אבל ברוב סתם לא אמר! ומשיבים: \u0003הדר ביה\u0004 \u0005[חזר בו]\u0006 \u0003רבא מההיא\u0004 \u0005[מאותה\u0006 סברה\u0005]\u0006 וסבור שהולכים אחר הרוב בכל מקרה.","\u0003איתמר\u0004 \u0005[נאמר]:\u0006 \u0003חבית\u0004 של יין \u0003ש\u0004נמצאה \u0003צפה בנהר,\u0004 ואין ידוע מה טיבו של היין שבתוכה, \u0003אמר רב:\u0004 אם \u0003נמצאת כנגד עיר שרובה ישראל\u0004 — \u0003מותר\u0004 היין שבה, שמן הסתם יין של ישראל הוא, אם נמצאת \u0003כנגד עיר שרובה גוים\u0004 — \u0003אסירא\u0004 \u0005[אסורה]\u0006 משום יינם של גויים. \u0003ושמואל אמר: אפילו נמצאת כנגד עיר שרובה ישראל\u0004 — \u0003אסירא\u0004 \u0005[אסורה],\u0006 ומדוע? \u0003אימור מהאי\u0004 \u0005[אמור\u0006 ש\u0005מ\u0006המחוז \u0005הזה]\u0006 של \u0003קרא אתאי\u0004 \u0005[בא\u0006 היין\u0005],\u0006 שהרוב שם הם גויים.","ומציעים: \u0003לימא\u0004 \u0005[האם לומר]\u0006 שבדברי \u0003ר' חנינא קא מיפלגי\u0004 \u0005[חלוקים הם],\u0006 \u0003דמר אית ליה\u0004 \u0005[שחכם זה\u0006 שמואל, \u0005יש לו,\u0006 מקבל\u0005]\u0006 את דברי \u0003ר' חנינא\u0004 והולך אחר הרוב, \u0003ומר לית ליה\u0004 \u0005[וחכם זה,\u0006 רב, \u0005אין לו]\u0006 את שיטת \u0003ר' חנינא\u0004 ולכן הוא הולך אחר הקרוב?","ודוחים: \u0003לא, דכולי עלמא אית להו\u0004 \u0005[לדעת הכל יש להם,\u0006 מקבלים\u0005]\u0006 את דברי \u0003ר' חנינא, והכא בהא קמיפלגי\u0004 \u0005[וכאן בזה הם חלוקים],\u0006 \u0003דמר סבר\u0004 \u0005[שחכם זה,\u0006 רב, \u0005סבור]:\u0006 \u0003אם איתא דמהאי\u0004 \u0005[אמנם שמ\u0006מחוז \u0005זה]\u0006 של \u0003קרא אתאי\u0004 \u0005[בא]\u0006 \u0003עקולי ופשורי הוה מטבעי לה\u0004 \u0005[עיקולי הנהר ומקומות\u0006 בהם הזרימה חלשה \u0005היו מטביעים אותה]\u0006 ולכן מסתבר שמן העיר הקרובה נפלה החבית. \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 שמואל, \u0005סבור]:\u0006 שמא \u0003חריפא דנהרא נקט ואתאי\u0004 \u0005[חריפות,\u0006 עיקר שטפו, \u0005של הנהר תפס\u0006 את החבית \u0005והביאה]\u0006 שהרי רואים אנו שהנהר זורם כדרכו ומביא דברים ממרחק.","מסופר: \u0003ההוא חצבא דחמרא דאישתכח בפרדיסא\u0004 \u0005[כד אחד של יין שנמצא בפרדס],\u0006 כרם שהיו בו ענבים של \u0003ערלה,\u0004 \u0003שריא\u0004 \u0005[התיר\u0006 אותו\u0005]\u0006 \u0003רבינא\u0004 ולא חשש שהוא מגפני אותו כרם. ושואלים: \u0003לימא\u0004 \u0005[האם לומר]\u0006 ש\u0003משום דסבר לה\u0004 \u0005[ש\u0006הוא \u0005סבור]\u0006 כדעת \u0003ר' חנינא\u0004 שהולכים אחר רוב הכרמים שאינם ערלה, ולא אחר הקרוב?","ומשיבים: \u0003שאני התם\u0004 \u0005[שונה\u0006 המקרה \u0005שם],\u0006 \u0003דאי מיגניב מינה\u0004 \u0005[שאם היו גונבים ממנו],\u0006 מאותו כרם עצמו — \u0003אצנועי בגויה לא מצנעי\u0004 \u0005[לא היו מחביאים בתוכו]\u0006 ואם החביאו בתוכו מסתבר שגנבו את החבית ממקום אחר. ומעירים: \u0003והני מילי חמרא\u0004 \u0005[ודברים אלה\u0006 אמורים דווקא \u0005ביין],\u0006 שאין מחביאים אותו באותו כרם, \u0003אבל עינבי מצנעי\u0004 \u0005[ענבים מצניעים]\u0006 ואם כן יש לחשוש שמאותו כרם הם.","ועוד מסופר: \u0003הנהו זיקי דחמרא דאשתכחן בי קופאי\u0004 \u0005[אותם נאדות יין שנמצאו בין הגפנים],\u0006 במקום של ישראל \u0003שרנהו\u0004 \u0005[התיר אותם]\u0006 \u0003רבא\u0004 ולא חשש משום יין נסך. ושואלים: \u0003לימא\u0004 \u0005[האם לומר]\u0006 שהוא \u0003לא סבר לה\u0004 \u0005[אינו סבור]\u0006 כדברי \u0003ר' חנינא\u0004 שהולכים אחר הרוב? ומשיבים: \u0003שאני התם\u0004 \u0005[שונה שם],\u0006 \u0003דרובא\u0004 \u0005[שרוב]\u0006"],["\u0003דשפוכאי\u0004 \u0005[שופכי היין]\u0006 מן החביות השופכים את היין לנאדות, \u0003ישראל נינהו\u0004 \u0005[הם],\u0006 ולכן יש לתלות שהיין הוא של ישראל. ומעירים: \u0003והני מילי\u0004 \u0005[ודברים אלה\u0006 אמורים\u0005]\u0006 דווקא \u0003ברברבי\u0004 \u0005[ב\u0006נאדות \u0005גדולים],\u0006 \u0003אבל\u0004 אם היו \u0003זוטרי\u0004 \u0005[קטנים],\u0006 \u0003אימור\u0004 \u0005[אמור]\u0006 ש\u0003מעוברי דרכים\u0004 שרובם גויים \u0003נפול\u0004 \u0005[נפלו],\u0006 ואסורים. \u0003ואי איכא רברבי בהדייהו\u0004 \u0005[ואם היו\u0006 נאדות \u0005גדולים איתם],\u0006 \u0003אימור\u0004 \u0005[אמור]:\u0006 שמא \u0003באברורי הוה מנחי\u0004 \u0005[היו מונחים כמאזנים]\u0006 את משא החמור, ונפלו יחד.","\u0003מרחיקין את האילן מן העיר עשרים וחמש אמה, ובחרוב ובשקמה\u0004 שענפיהם מרובים — \u0003חמשים אמה. אבא שאול אומר: כל אילן סרק\u0004 מרחיקים \u0003חמשים אמה. ואם העיר קדמה\u0004 ונטע אחרי כן את האילן סמוך מדי לעיר — \u0003קוצץ\u0004 אחד מבני העיר את האילן, \u0003ואינו נותן\u0004 לבעל האילן \u0003דמים,\u0004 דמי האילן שקצץ. \u0003ואם אילן קדם\u0004 והעיר אחר כך גדלה והתקרבה אליו — \u0003קוצץ\u0004 את האילן \u0003ונותן\u0004 לבעליו \u0003דמים. ספק זה קדם וספק זה קדם\u0004 — \u0003קוצץ ואינו נותן דמים.\u0004","שואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 מרחיקים את האילן מן העיר? \u0003אמר עולא: משום נויי העיר,\u0004 שאין זה נוי לעיר שחומותיה אינן גלויות אלא מכוסות בענפי אילנות. ושואלים: \u0003ותיפוק ליה\u0004 \u0005[ותצא לו]\u0006 הלכה זו מטעם אחר, ששנינו במסכת ערכין ש\u0003אין עושין שדה\u0004 של העיר \u0003מגרש\u0004 (תחום פנוי שמסביב לעיר), \u0003ולא\u0004 עושים \u0003מגרש שדה\u0004 אלא יש להם מקום ושיעור קבוע (ראה במדבר פרק לה). ואם כן, כיון שנטע עצים במגרש העיר הרי הוא עושה את מגרש העיר שדה!","ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא \u0003ל\u0004דעת \u0003ר' אלעזר\u0004 ש\u0003אמר: עושין שדה מגרש ומגרש שדה,\u0004 אבל \u0003הכא\u0004 \u0005[כאן]\u0006 בקירוב מקום כל כך \u0003משום נויי העיר לא עבדינן\u0004 \u0005[עושים].\u0006","ומוסיפים: \u0003ולרבנן נמי דאמרי\u0004 \u0005[ולחכמים גם כן שאומרים]\u0006 ש\u0003אין עושין שדה מגרש ולא מגרש שדה,\u0004 אפשר לומר כי \u0003הני מילי\u0004 \u0005[דברים אלה\u0006 אמורים\u0005]\u0006 ב\u0003זרעים,\u0004 שאין זורעים זרעים במגרש העיר שייעשה כשדה, \u0003אבל אילנות עבדינן\u0004 \u0005[עושים אנו],\u0006 נוטעים במגרש, \u0003והכא\u0004 \u0005[וכאן]\u0006 \u0003משום נויי העיר לא,\u0004 אין עושים.","\u0003ומנא תימרא דשאני\u0004 \u0005[ומנין אתה אומר ששונה\u0006 הדין\u0005]\u0006 \u0003בין זרעין לאילנות? דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 בהלכות שבת: היה \u0003קרפף\u0004 (חצר אחורית) ששטחו \u0003יותר מבית סאתים שהוקף ל\u0004שם \u0003דירה,\u0004 שהגדר נעשתה כדי שידורו אנשים במקום, הרי כיון שיש לקרפף מחיצות — דינו כרשות היחיד, ומותר לטלטל בתוכו.","אבל אם \u0003נזרע רובו\u0004 של הקרפף — \u0003הרי הוא כגינה ואסור\u0004 לטלטל בו, לפי שאז יש לו דין כרמלית, ואולם אם \u0003ניטע רובו\u0004 — \u0003הרי הוא כחצר ומותר.\u0004 משמע שנטיעת עצים בחצר אינה נחשבת כאלו עשו את המקום שדה, כפי שהוא בזריעה.","שנינו במשנה: \u0003ואם העיר קדמה\u0004 — \u0003קוצץ\u0004 אחד מבני העיר את האילן \u0003ואינו נותן\u0004 לבעליו כל \u0003דמים וכו'.\u0004 ושואלים: \u0003מאי שנא\u0004 \u0005[מה שונה]\u0006 הדין \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003בור, דקתני\u0004 \u0005[ששנה\u0006 בו\u0005]\u0006 שאם נטע אילן סמוך לבורו של חבירו והבור קדם — \u0003קוצץ\u0004 את האילן \u0003ונותן\u0004 בעל הבור עבורו \u0003דמים, ומאי שנא הכא דקתני\u0004 \u0005[ומה שונה כאן ששנה]:\u0006 \u0003קוצץ ואינו נותן דמים?\u0004","\u0003אמר רב כהנא:\u0004 לפי הפתגם העממי, \u0003קידרא דבי שותפי לא חמימא ולא קרירא\u0004 \u0005[קדירה של שותפים אינה חמה ואינה קרה].\u0006 כלומר, דבר שאינו שייך לאדם אחד, אלא לכמה אנשים — אין איש משגיח בו. ואף כאן, כיון שמדובר פה בדבר הנוגע לבני העיר בכללם, אין ממי לגבות את הכסף לשלם עבור העץ.","ושואלים: \u0003ומאי קושיא\u0004 \u0005[ומה הקושיה\u0006 מעיקרה\u0005]?\u0006 \u0003דלמא שאני הזיקא\u0004 \u0005[שמא שונה היזק]\u0006 של \u0003רבים מהזיקא\u0004 \u0005[מהיזק]\u0006 של \u0003יחיד,\u0004 שהמזיק את הרבים אינו מקבל כל פיצוי, מה שאין כן בבור של יחיד!","\u0003אלא אי איתמר\u0004 \u0005[אם נאמרו\u0006 דבריו\u0005]\u0006 של \u0003רב כהנא\u0004 – \u0003אסיפא איתמר\u0004 \u0005[על הסוף\u0006 של המשנה \u0005נאמרו]:\u0006 \u0003אם האילן קדם\u0004 — \u0003קוצץ ונותן דמים,\u0004 ועל כך יש לשאול: \u0003ולימא להו\u0004 \u0005[ושיאמר להם]\u0006 בעל האילן לבני העיר: \u0003הבו\u0004 \u0005[תנו]\u0006 \u0003לי ברישא דמי\u0004 \u0005[בתחילה כסף]\u0006 \u0003והדר איקוץ\u0004 \u0005[ואחר כך אקצוץ]!\u0006 על כך \u0003אמר רב כהנא: קידרא דבי שותפי לא חמימא ולא קרירא\u0004 \u0005[קדירה של שותפים אינה חמה ואינה קרה].\u0006 שאין הרבים גובים ומשלמים מיד כמו היחיד, ונמצא זמן רב עובר עד שייקצץ האילן.","שנינו במשנה: \u0003ספק זה קדם וספק זה קדם\u0004 — \u0003קוצץ ואינו נותן דמים.\u0004 ושואלים: \u0003מאי שנא\u0004 \u0005[מה שונה]\u0006 דין זה \u0003מ\u0004דין אילן סמוך ל\u0003בור\u0004 ש\u0003אמרת\u0004 במשנה להלן, שבמקרה של ספק \u0003לא יקוץ?\u0004","ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 שבמקרה של \u0003ודאי לאו למיקץ קאי\u0004 \u0005[לא לקציצה עומד\u0006 האילן\u0005],\u0006 כי אם קדם האילן לבור אין בעל הבור רשאי לקצצו — \u0003ספיקו נמי\u0004 \u0005[גם כן]\u0006 \u0003לא אמרינן ליה\u0004 \u0005[אין אנו אומרים לו]:\u0006 \u0003קוץ\u0004 \u0005[קצוץ],\u0006 \u0003הכא\u0004 \u0005[כאן],\u0006 שבמקרה של \u0003ודאי למיקץ קאי\u0004 \u0005[לקציצה\u0006 האילן \u0005עומד]\u0006 גם אם קדם לעיר, אלא שיש ספק אם צריך לשלם את הכסף לבעלים — משום כך \u0003ספיקו נמי\u0004 \u0005[גם כן]\u0006 \u0003אמרינן ליה\u0004 \u0005[אומרים אנו לו]:\u0006 \u0003קוץ\u0004 \u0005[קצוץ].\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003משום דמי\u0004 \u0005[הכסף]\u0006 שתובע עבור האילן, \u0003אמרינן ליה\u0004 \u0005[אומרים אנו לו]:\u0006 \u0003אייתי\u0004 \u0005[הבא]\u0006 \u0003ראיה\u0004 שאילנך קדם \u0003ושקול\u0004 \u0005[וקח]\u0006 את הכסף. וכיון שאין בידו ראיה — אין נוטל דמים.","\u0003מרחיקין את\u0004 ה\u0003גורן\u0004 ה\u0003קבוע מן העיר חמשים אמה,\u0004 כדי שהמוץ שזורים בגורן לא יזיק לבני העיר. ועוד: \u0003לא יעשה אדם גורן קבוע\u0004 אפילו \u0003בתוך שלו, אלא אם כן יש לו חמשים אמה\u0004 שטח שלו \u0003לכל רוח\u0004 (צד), \u0003ומרחיק\u0004 את הגורן \u0003מנטיעותיו של חבירו, ומנירו\u0004 (שדה חרוש), \u0003בכדי שלא יזיק.\u0004","ושואלים: \u0003מאי שנא רישא\u0004 \u0005[מה שונה\u0006 הדין \u0005בראש\u0006 המשנה\u0005]\u0006 שניתן שיעור הרחקה מסויים לגורן, \u0003ומאי שנא סיפא\u0004 \u0005[ומה שונה\u0006 ב\u0005סוף\u0006 המשנה\u0005]\u0006 שלא ניתן שיעור להרחקה, אלא אמרו בדרך כלל \"בכדי שלא יזיק\"? \u0003אמר אביי: סיפא אתאן\u0004 \u0005[\u0006ב\u0005סוף באנו]\u0006 \u0003לגורן שאינו קבוע\u0004 שגם אותו צריך להרחיק משל חבירו.","ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק]\u0006 הוא \u0003גורן שאינו קבוע? אמר ר' יוסי בר' חנינא: כל שאינו זורה ברחת\u0004 (כלי המיוחד לזרייה), אלא באופן אחר, ואין המוץ הולך רחוק כל כך. זה היה הסבר אחד לסתירה.","\u0003רב אשי אמר:\u0004 \"בכדי שלא יזיק\" אינו שיעור של מרחק, אלא נימוק, ובלשון \u0003מה טעם קאמר\u0004 \u0005[הוא אומר]:\u0006 \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 ש\u0003מרחיקין גורן קבוע מן העיר חמשים אמה?\u0004 — \u0003כדי שלא יזיק.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על אביי ממה ששנינו בברייתא: \u0003מרחיקין גורן קבוע מן העיר חמשים אמה; וכשם שמרחיקין\u0004 אותו \u0003מן העיר חמשים אמה, כך מרחיקין\u0004 אותו \u0003מדלועיו\u0004 של חבירו \u0003ומקשואיו ומנטיעותיו ומנירו של חבירו חמשים אמה, כדי שלא יזיק;\u0004 ומעתה: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003לרב אשי ניחא\u0004 \u0005[נוח\u0006 הדבר\u0005],\u0006 שהרי כך הסביר את לשון המשנה, שאין הבדל שיעור בין ראשה וסופה, ולדבריו, אף מן הניר ומן הנטיעות מרחיק חמישים אמה. \u0003אלא לאביי קשיא\u0004 \u0005[קשה]!\u0006 ואומרים: אכן, \u0003קשיא\u0004 \u0005[קשה\u0006 הדבר\u0005]\u0006 ואין הלשון מדוייקת.","לגופה של אותה ברייתא שואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 שאמרנו שצריך להרחיק \u0003ממקשואיו ומדלועיו,\u0004 וזה משום \u0003דאזיל אבקא ואתי בליביה\u0004 \u0005[שהולך האבק\u0006 של הגורן \u0005ובא\u0006 וחודר \u0005בתוך ליבו]\u0006 של הפרח \u0003ומצוי ליה\u0004 \u0005[ומייבש אותו],\u0006 \u0003אלא מנירו אמאי\u0004 \u0005[מדוע]\u0006 צריך להרחיק? \u0003אמר ר' אבא בר זבדא, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003ר' אבא בר זוטרא: מפני\u0004"],["\u0003שעושה אותו גלל\u0004 (זבל), שהמוץ נעשה כזבל, וזבל מרובה זה משחית את הזרעים.","\u0003מרחיקין את הנבלות ואת הקברות ואת הבורסקי\u0004 (מקום עיבוד עורות) \u0003מן העיר חמשים אמה. אין עושין בורסקי אלא למזרח העיר\u0004 לפי שכרגיל נושבת רוח ממערב, והיא מרחיקה מן העיר את הריחות הרעים. \u0003ר' עקיבא אומר: לכל רוח\u0004 (צד) \u0003הוא עושה\u0004 את הבורסקי, \u0003חוץ ממערבה\u0004 שמשם בוודאי באה רוח ומביאה את הריחות לעיר, \u0003ומרחיק חמשים אמה. ומרחיקין את המשרה\u0004 הבריכה שבה שורים את הפשתן \u0003מן הירק,\u0004 לפי שמים אלה מזיקים לירקות. \u0003ו\u0004כן מרחיקים \u0003את הכרישין מן הבצלים, ואת החרדל מן הדבורים, ור' יוסי מתיר בחרדל.\u0004","בפירוש משנתנו \u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 \u0003ר' עקיבא\u0004 שאמר בסוף דבריו \"ומרחיק חמשים אמה\", \u0003היכי קאמר\u0004 \u0005[כיצד אמר]?\u0006 האם כוונת הדברים היתה: \u0003לכל רוח הוא עושה\u0004 בורסקי \u0003ו\u0004אף \u0003סומך\u0004 את הבורסקי שעושה לעיר, \u0003חוץ ממערבה\u0004 ש\u0003מרחיק חמשים אמה ועושה. או דלמא\u0004 \u0005[שמא]\u0006 כך אמר: \u0003לכל רוח הוא עושה ומרחיק חמשים אמה, חוץ ממערבה\u0004 ש\u0003אינו עושה כלל?\u0004","ומביאים ראיה, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]:\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' עקיבא אומר: לכל רוח הוא עושה ומרחיק חמשים אמה, חוץ ממערבה\u0004 ש\u0003אינו עושה כל עיקר, מפני ש\u0004הרוח הזאת \u0003היא תדירא\u0004 \u0005[מצויה]\u0006 יותר.","על הסבר זה שבברייתא \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא לרב נחמן: מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003תדירא? אילימא\u0004 \u0005[אם תאמר]\u0006 שהיא \u0003תדירא ברוחות,\u0004 שהרוח הזו נושבת תמיד, \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר רב חנן בר אבא אמר רב: ארבע רוחות מנשבות בכל יום\u0004 מכל הצדדים \u0003ורוח צפונית\u0004 מנשבת \u0003עם כולן, שאילמלא כן\u0004 שאם לא היתה מנשבת — \u0003אין העולם מתקיים אפילו שעה אחת,\u0004 לפי שהיא רוח נוחה, המשככת את השפעתן החריפה של רוחות אחרות. \u0003ורוח דרומית\u0004 היא ה\u0003קשה מכולן, ואילמלא בן נץ\u0004 (מלאך שנקרא כך) \u0003שמעמידה,\u0004 שלא תהיה חזקה מדי — הריהי \u0003מחרבת את העולם, שנאמר: \"המבינתך יאבר נץ יפרש כנפו לתימן\"\u0004 (איוב לט, כו), ונמצא שהרוח הצפונית היא התדירה ברוחות, ולא המערבית!","\u0003אלא מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003תדירא\u0004 — \u0003תדירא בשכינה,\u0004 שבצד הזה מצויה השכינה, ואין ראוי לעשות מקום שריחו רע לצד חשוב זה. ש\u0003אמר ר' יהושע בן לוי: בואו ונחזיק טובה לאבותינו שהודיעו\u0004 לנו \u0003מקום תפלה, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וצבא השמים לך משתחוים\"\u0004 (נחמיה ט, ו), וכיון שצבא השמים פונים ממזרח למערב הריהם משתחווים לצד זה, ומשמע ששכינה במערב.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב אחא בר יעקב:\u0004 מה הראיה מכאן? \u0003ודלמא\u0004 \u0005[ושמא]\u0006 המזלות הם \u0003כעבד שנוטל\u0004 \u0003פרס\u0004 (מתנה) \u0003מרבו, וחוזר לאחוריו ומשתחוה!\u0004 ונאמר איפוא שהשכינה היא במזרח, והם כהולכים אחורנית! ואומרים: אכן \u0003קשיא\u0004 \u0005[קשה\u0006 הדבר\u0005],\u0006 לפי שאין זו ראיה גמורה.","ומעירים: \u0003ור' אושעיא סבר\u0004 \u0005[סבור]\u0006 שה\u0003שכינה\u0004 מצויה \u0003בכל מקום,\u0004 ש\u0003אמר ר' אושעיא, מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"אתה הוא ה' לבדך אתה עשית את השמים...\u0004 ואתה מחיה את כולם וצבא השמים לך משתחווים \u0003\"\u0004\u0003וגו'\u0004 (נחמיה ט, ו)? — לומר: \u0003שלוחיך לא כשלוחי בשר ודם; שלוחי בשר ודם, ממקום שמשתלחים\u0004 — \u0003לשם\u0004 בסוף הם שבים לשולחם ו\u0003מחזירים שליחותן\u0004 להודיע מה עשו. \u0003אבל שלוחיך,\u0004 \u0003למקום שמשתלחין\u0004 — \u0003משם\u0004 מאותו מקום שמגיעים אליו \u0003מחזירין שליחותן, שנאמר: \"התשלח ברקים וילכו ויאמרו לך הננו\"\u0004 (איוב לח, לה), \u0003\"יבואו ויאמרו\" לא נאמר,\u0004 שאין הם חוזרים למקומם, \u0003אלא \"וילכו ויאמרו\", מלמד שהשכינה בכל מקום.\u0004","ומעירים: \u0003ואף ר' ישמעאל סבר\u0004 \u0005[סבור]\u0006 שה\u0003שכינה\u0004 מצויה \u0003בכל מקום, דתנא דבי\u0004 \u0005[ששנה\u0006 החכם מ\u0005בית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל: מנין ששכינה בכל מקום?\u0004 — \u0003שנאמר: \"\u0004ו\u0003הנה המלאך הדבר בי יצא ומלאך אחר יצא לקראתו\"\u0004 (זכריה ב, ז), \u0003\"אחריו\" לא נאמר, אלא \"לקראתו\", מלמד ששכינה בכל מקום,\u0004 ולפיכך יוצאים המלאכים לשליחותם מכל מקום.","\u0003ואף רב ששת סבר\u0004 \u0005[סבור]\u0006 שה\u0003שכינה\u0004 מצויה \u0003בכל מקום,\u0004 ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב ששת לשמעיה\u0004 \u0005[לשמשו]:\u0006 \u0003לכל רוחתא אוקמן\u0004 \u0005[רוח,\u0006 צד, \u0005העמד אותי\u0006 להתפלל\u0005]\u0006 שלפי שהיה עיוור היה נזקק לשמש שיעמיד אותו, \u0003לבר\u0004 \u0005[חוץ]\u0006 \u0003מ\u0004צד \u0003מזרח,\u0004 שאל תעמיד אותי לשם, והסביר לו: \u0003ולאו\u0004 \u0005[ולא]\u0006 \u0003משום דלית ביה\u0004 \u0005[שאין בו]\u0006 \u0003שכינה, אלא משום דמורו\u0004 \u0005[שמורים]\u0006 \u0003בה מיני\u0004 \u0005[המינים]\u0006 שהם פונים בתפילתם למזרח, ולכן הוא רצה להימנע מלעשות כמותם.","\u0003ור' אבהו אמר: שכינה במערב,\u0004 ש\u0003אמר ר' אבהו: מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"אוריה\"\u0004 (שהוא שם כינוי לצד מערב)? \u0003אויר יה,\u0004 כלומר, שם הוא מקום השכינה.","ואגב שהוזכרו ארבע הרוחות מביאים מה שדרשו חכמים בעניינן. \u0003אמר רב יהודה, מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \"יערוף כמטר לקחי, תזל כטל אמרתי, כשעירים עלי דשא וכרביבים עלי עשב\" (דברים לב, ב)? \u0003\"יערף כמטר לקחי\"\u0004 — \u0003זו רוח מערבית שבאה מערפו של עולם\u0004 (שצד מערב נקרא גם \"אחור\") ולכן קוראים לנשיבתה \"יערף\".","\u0003\"תזל כטל אמרתי\"\u0004 — \u0003זו רוח צפונית, ש\u0004מביאה אויר יבש וממעטת את הגשמים ואת התבואות, ו\u0003מזלת\u0004 (ומוזילה) \u0003את\u0004 מחיר \u0003הזהב.\u0004 כי כאשר התבואה אינה מצויה מחירה עולה, ולכן מחיר הזהב יורד. \u0003וכן הוא אומר\u0004 לשון \"זול\" לענין זהב: \u0003\"הזלים זהב מכיס\"\u0004 (ישעיה מו, ו).","\u0003\"כשעירם עלי דשא\"\u0004 — \u0003זו רוח מזרחית,\u0004 בשעה שנושבת בחוזקה \u0003שמסערת\u0004 (עושה סערה) \u0003את כל העולם כשעיר\u0004 (שד). \u0003\"וכרביבים עלי עשב\"\u0004 — \u0003זו רוח דרומית, שהיא מעלה רביבים\u0004 (מטר) \u0003ומגדלת עשבים.\u0004","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' אליעזר אומר: עולם\u0004"],["\u0003לאכסדרה\u0004 (מבנה שיש בו רק שלושה קירות) \u0003הוא דומה, ורוח צפונית\u0004 של העולם \u0003אינה מסובבת\u0004 במחיצה כשאר רוחות, שאין שם דבר, אלא החמה מתחילה את סיבובה במזרח ועוברת לדרום ולמערב, \u0003וכיון שהגיעה חמה אצל קרן מערבית צפונית\u0004 — הריהי \u0003נכפפת ועולה\u0004 במשך הלילה \u0003למעלה מן הרקיע\u0004 לצד מזרח, ואינה עוברת בצד צפון. \u0003ור' יהושע אומר: עולם לקובה\u0004 (אוהל קטן) \u0003הוא דומה, ורוח צפונית\u0004 גם היא \u0003מסובבת\u0004 במחיצה, אבל \u0003כיון שחמה מגעת לקרן מערבית צפונית\u0004 — היא יוצאת מאותה \"קובה\", \u0003מקפת וחוזרת אחורי כיפה,\u0004 כלומר, מחוץ למחיצה הצפונית, עד שמגיעה למזרח.","\u0003שנאמר: \"הולך אל דרום וסובב אל צפון\" וגו'\u0004 (קהלת א, ו), ומפרש: גלגל החמה \u0003\"הולך אל דרום\",\u0004 כלומר, בצד דרום — \u0003ביום, \"וסובב אל צפון\"\u0004 מקיף אותו מבחוץ — \u0003בלילה. \"סובב סבב הולך הרוח\u0004 (כיוון החמה) \u0003ועל סביבתיו שב הרוח\"\u0004 (קהלת א, ו) — \u0003אלו פני מזרח ופני מערב, שפעמים\u0004 בימות החורף הקצרים, החמה \u0003מסבבתן\u0004 מקיפה אותם מבחוץ, ואינה מאירה, \u0003ופעמים\u0004 בימות החמה הארוכים \u0003מהלכתן\u0004 מהלכת ברוחות אלו בתוך ה\"קובה\".","וממשיכים בברייתא: \u0003הוא היה אומר.\u0004 ומעירה הגמרא: בדברים אלה \u0003אתאן\u0004 \u0005[באנו]\u0006 חזרנו שוב \u0003ל\u0004שיטת \u0003ר' אליעזר\u0004 שהוא המביא ראיה לדבריו, שרוח צפונית פרוצה, מן הכתוב. נאמר: \u0003\"מן החדר תבא סופה\"\u0004 (איוב לז, ט), ומפרשים: \u0003זו רוח דרומית,\u0004 צד דרום, שהוא ושתי מחיצות שבצידו — הריהו כחדר. \u0003\"וממזרים קרה\"\u0004 (איוב לז, ט) — \u0003זו רוח צפונית,\u0004 משם באה הרוח המשיבה ומפזרת (\"מזרים\") קור. \u0003\"מנשמת אל יתן קרח\"\u0004 (איוב לז, י) — \u0003זו רוח מערבית. \"ורחב מים במוצק\"\u0004 (איוב לז, י) — \u0003זו רוח מזרחית\u0004 משם באים הגשמים.","ומקשים: \u0003והאמר מר\u0004 \u0005[והרי אמר החכם]\u0006 בעמוד הקודם: \u0003רוח דרומית\u0004 היא \u0003מעלה רביבים\u0004 (גשמים) \u0003ומגדלת עשבים!\u0004 ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]:\u0006 \u0003הא דאתיא מטרא בניחותא\u0004 \u0005[זה שיורד הגשם בנחת]\u0006 ואז הוא משקה ומגדל, \u0003הא בשפיכותא\u0004 \u0005[זה\u0006 שהוא בא \u0005בשפיכה]\u0006 כאשר יש בבת אחת הרבה גשם, אז הוא מזיק.","\u0003אמר רב חסדא, מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"מצפון זהב יאתה\"\u0004 (איוב לז, כב) — \u0003זו רוח צפונית שמזלת את הזהב,\u0004 שגורמת שיעלה מחיר התבואה בגלל הבצורת. \u0003וכן הוא אומר: \"הזלים זהב מכיס\"\u0004 (ישעיה מו, ו).","\u0003אמר רפרם בר פפא אמר רב חסדא: מיום שחרב בית המקדש לא הוגשמה\u0004 (לא הביאה גשם) \u0003רוח דרומית, שנאמר\u0004 בתיאור החורבן: \u0003\"ויגזר על ימין ורעב, ויאכל על שמאל ולא שבעו\"\u0004 (ישעיה ט, יט), כלומר, גזר ה' על רוח דרום הקרויה \"ימין\" שתביא עמה רעב, \u0003וכתיב\u0004 \u0005[ו\u0006כן \u0005נאמר]:\u0006 \u0003\"צפון וימין אתה בראתם\"\u0004 (תהלים פט, יג), ומכאן ש\"ימין\" פירושו דרום.","\u0003ואמר רפרם בר פפא אמר רב חסדא: מיום שחרב בית המקדש אין הגשמים יורדין\u0004 עוד \u0003מאוצר טוב, שנאמר: \"יפתח ה' לך את אוצרו הטוב\u0004 את השמים לתת מטר ארצך בעתו\u0003\"\u0004 (דברים כח, יב), \u0003בזמן שישראל עושין רצונו של מקום וישראל שרויין על אדמתם\u0004 — אז \u0003גשמים יורדין מאוצר טוב, בזמן שאין ישראל שרויין על אדמתם\u0004 — \u0003אין גשמים יורדין\u0004 עוד \u0003מאוצר טוב.\u0004","\u0003אמר ר' יצחק: הרוצה שיחכים\u0004 — \u0003ידרים\u0004 יפנה בתפילתו לדרום, \u0003ושיעשיר\u0004 — \u0003יצפין, וסימניך:\u0004 שבמקדש מונח \u0003שלחן\u0004 שהוא הסמל לשפע ולברכה \u0003בצפון, ומנורה\u0004 שהיא סמל לאור החכמה \u0003בדרום; ור' יהושע בן לוי אמר: לעולם ידרים, שמתוך שמתחכם\u0004 גם \u0003מתעשר\u0004 אחר כך, \u0003שנאמר\u0004 לגבי התורה: \u0003\"ארך ימים בימינה בשמאלה עשר וכבוד\"\u0004 (משלי ג, טז).","ושואלים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003ר' יהושע בן לוי\u0004 הוא ש\u0003אמר: שכינה במערב\u0004 וכיצד ידרים בתפילתו? \u0003דמצדד אצדודי\u0004 \u0005[\u0006שהוא \u0005מצודד],\u0006 שפניו למערב ונוטה מעט לדרום. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' חנינא\u0004 \u0003לרב אשי: כגון אתון דיתביתו\u0004 \u0005[אתם שיושבים]\u0006 \u0003בצפונה\u0004 של \u0003ארץ ישראל\u0004 — \u0003אדרימו אדרומי\u0004 \u0005[הדרימו,\u0006 פנו לצד דרום\u0005]\u0006 בזמן שאתם מתפללים. \u0003ומנא לן\u0004 \u0005[ומנין לנו]\u0006 ש\u0003בבל לצפונה\u0004 של \u0003ארץ ישראל קיימא\u0004 \u0005[עומדת]?\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בנבואה על חורבן ירושלים בידי הבבלים: \u0003\"מצפון תפתח הרעה על כל ישבי הארץ\"\u0004 (ירמיהו א, יד).","שנינו במשנה: \u0003מרחיקין את המשרה מן הירק\u0004 ואת החרדל מן הדבורים. \u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003ר' יוסי מתיר בחרדל, שיכול\u0004 בעל החרדל \u0003לומר לו\u0004 לבעל הדבורים: \u0003עד שאתה אומר לי הרחק חרדלך מן דבוריי\u0004 שהוא מזיק להן, יכול אני לומר לך להיפך: \u0003הרחק דבורך מן חרדליי, שבאות ואוכלות לגלוגי\u0004 (פרחי) \u0003חרדליי.\u0004 וכיון ששניהם מזיקים זה לזה אין אחד יכול להכריח את חבירו להרחיק.","\u0003מרחיקין את האילן מן הבור עשרים וחמש אמה,\u0004 שלא יזיקו שורשיו את הבור, \u0003ובחרוב ובשקמה\u0004 ששורשיהם מתפשטים יותר — מרחיקים \u0003חמשים אמה, בין\u0004 שהיה הבור \u0003מלמעלה בין\u0004 שהיה \u0003מן הצד\u0004 של האילן. \u0003אם\u0004 חפירת \u0003הבור קדמה\u0004 לאילן — \u0003קוצץ\u0004 את האילן \u0003ונותן\u0004 בעל הבור \u0003דמים, ואם אילן קדם\u0004 — \u0003לא יקוץ\u0004 את האילן. \u0003ספק זה קדם וספק זה קדם\u0004 — \u0003לא יקוץ. ר' יוסי אומר: אף על פי שהבור קודמת לאילן\u0004 — \u0003לא יקוץ,\u0004 ומדוע? \u0003שזה חופר בתוך שלו וזה נוטע בתוך שלו,\u0004 שר' יוסי סבור שבכגון זה אין המזיק צריך להרחיק את עצמו.","על מה ששנינו במשנתנו שמרחיקים את האילן \"בין מלמעלה\", מביאים, \u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003בין שהבור למטה ואילן למעלה, בין שהבור למעלה ואילן למטה.\u0004 ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 שה\u0003בור למטה ואילן למעלה\u0004 נגרם נזק, שהרי \u0003קא אזלין שרשין מזקי לה\u0004 \u0005[הולכים השורשים ומזיקים לו]\u0006 \u0003לבור\u0004 כאשר בוקעים את קירותיו. \u0003אלא\u0004 אם ה\u0003בור למעלה ואילן למטה, אמאי\u0004 \u0005[מדוע]\u0006 ירחיק? והרי השורשים הולכים כלפי מטה! \u0003אמר ר' חגא בשם ר' יוסי: מפני שמחלידין\u0004 (מחוררים) \u0003את הקרקע ומלקין\u0004 (מקלקלים) על ידי כך את \u0003קרקעיתה של\u0004 ה\u0003בור.\u0004","\u0003ר' יוסי אומר: אף על פי שהבור קודמת לאילן\u0004 — \u0003לא יקוץ, שזה חופר בתוך שלו וזה נוטע בתוך שלו. אמר רב יהודה אמר שמואל: הלכה כ\u0004שיטת \u0003ר' יוסי. אמר רב אשי, כי הואן\u0004 \u0005[כאשר היינו]\u0006 \u0003בי\u0004 \u0005[בבית]\u0006 \u0003רב כהנא הוה אמרינן\u0004 \u0005[היינו אומרים]:\u0006 \u0003מודי\u0004 \u0005[מודה]\u0006 \u0003ר' יוסי בגירי דידיה\u0004 \u0005[בחיצים שלו],\u0006 כלומר, בנזק ישיר שנגרם על ידי דבר שברשותו, אף על פי שהוא עושה אותו בתוך רשותו.","מסופר: איש אחד שנקרא \u0003פאפי יונאה\u0004 \u0003עני והעשיר הוה\u0004 \u0005[היה],\u0006 \u0003בנה אפדנא\u0004 \u0005[ארמון]\u0006 במקום מושבו, \u0003הוו הנך עצורי בשיבבותיה\u0004 \u0005[היו\u0006 שם \u0005עושי שמן שומשומין בשכנותו],\u0006 \u0003דכי הוו דייקי שומשמי הוה ניידא אפדניה\u0004 \u0005[שכאשר היו דכים את השומשומים היה נד\u0006 רועד \u0005הארמון שלו],\u0006 \u0003אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003רב אשי\u0004 להתלונן, \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003כי הואן בי\u0004 \u0005[כאשר היינו בבית]\u0006 \u0003רב כהנא הוה אמרינן\u0004 \u0005[היינו אומרים]:\u0006 \u0003מודי\u0004 \u0005[מודה]\u0006 \u0003ר' יוסי בגירי דיליה\u0004 \u0005[בחיצים שלו].\u0006 ואף כאן, כיון שהם גורמים נזק ישיר, צריכים הם להרחיק.","ומעירים: \u0003וכמה\u0004 הוא השיעור של תנודה שבגללו אומרים להם להרחיק?"]]};
